	c.CommitCount, c.UnrevealedCount = total, total
	for i := 0; i < total; i++ {
		commits.Set(key+"|g1test"+strconv.Itoa(i), commitreveal.Record{})
	}
	const other = "Q:20|g1test0"
	commits.Set(other, commitreveal.Record{})
