func addBenchRankedSubmission(c *challengeRecord, sub *submissionRecord) {
	submissions.Set(c.RoundKey+"|"+sub.Solver, sub)
	leaderboards, _ = leaderboards.Set(leaderboardKey(c.RoundKey, sub), sub.Solver)
	c.RevealCount++
}

func assertBenchContains(t *testing.T, got string, fragments ...string) {
	t.Helper()
	for _, fragment := range fragments {
		if !strings.Contains(got, fragment) {
			t.Errorf("missing fragment %q in %q", fragment, got)
		}
	}
}

package bench

import (
	"strings"
	"time"

	"gno.land/p/g1nvxaasuu2muqg0nf05jezu5422qtgnx60h2qlp/commitreveal"
	"gno.land/p/g1nvxaasuu2muqg0nf05jezu5422qtgnx60h2qlp/cube3x3"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

func writeJSONString(b *strings.Builder, s string) {
	const digits = "0123456789abcdef"
	s = strings.ToValidUTF8(s, "\uFFFD")
	b.WriteByte('"')
	start := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		var escape string
		switch c {
		case '"':
			escape = `\"`
		case '\\':
			escape = `\\`
		case '\b':
			escape = `\b`
		case '\f':
			escape = `\f`
		case '\n':
			escape = `\n`
		case '\r':
			escape = `\r`
		case '\t':
			escape = `\t`
		default:
			if c >= 0x20 {
				continue
			}
		}
		b.WriteString(s[start:i])
		if escape == "" {
			b.WriteString(`\u00`)
			b.WriteByte(digits[c>>4])
			b.WriteByte(digits[c&0xf])
		} else {
			b.WriteString(escape)
		}
		start = i + 1
	}
	b.WriteString(s[start:])
	b.WriteByte('"')
}

func writeJSONText(b *strings.Builder, prefix, value string) {
	b.WriteString(prefix)
	writeJSONString(b, value)
}

func dailyRounds(dayID int64) (classic, twisted *challengeRecord) {
	prefix := dailyRoundPrefix(dayID)
	classic, _ = challenges.Get(prefix + "wca").(*challengeRecord)
	twisted, _ = challenges.Get(prefix + "twisted").(*challengeRecord)
	return classic, twisted
}

func roundRuleMetadata(ruleKey string) (title, description string, isCustom bool) {
	if rule, ok := cube3x3.BuiltinRule(ruleKey); ok {
		return rule.Title(), rule.Description(), false
	}
	entry, _ := customRules.Get(ruleKey).(registeredRule)
	return entry.Title, entry.Description, true
}

func forEachRecentQuickRound(visit func(*challengeRecord)) {
	quickRounds.ReverseIterateByOffset(0, RecentQuickRoundsLimit, func(_ string, value any) bool {
		if c, ok := challenges.Get(value.(string)).(*challengeRecord); ok {
			visit(c)
		}
		return false
	})
}

func forEachRankedSubmission(roundKey string, visit func(rank int, sub *submissionRecord) bool) {
	prefix := roundKey + "|"
	rank := 0
	leaderboards.Iterate(prefix, prefixRangeEnd(prefix), func(row *avl.Node) bool {
		sub, ok := submissions.Get(prefix + row.Value().(string)).(*submissionRecord)
		if !ok {
			return false
		}
		rank++
		return visit(rank, sub)
	})
}

func bestObtm(roundKey string) int {
	best := 0
	forEachRankedSubmission(roundKey, func(_ int, sub *submissionRecord) bool {
		best = sub.OBTM
		return true
	})
	return best
}

type roundJSONView uint8

const (
	todayRoundJSON roundJSONView = iota
	yesterdayRoundJSON
	quickRoundJSON
	challengeDetailJSON
)

func writeRoundJSON(b *strings.Builder, c *challengeRecord, nowUnix int64, view roundJSONView) {
	if c == nil {
		b.WriteString("null")
		return
	}
	title, description, isCustom := roundRuleMetadata(c.RuleKey)
	writeJSONText(b, `{"roundKey":`, c.RoundKey)
	writeJSONText(b, `,"kind":`, c.Kind)
	if c.Kind == "quick" {
		writeJSONText(b, `,"creator":`, c.Creator)
	}
	writeJSONText(b, `,"ruleKey":`, c.RuleKey)
	writeJSONText(b, `,"ruleTitle":`, title)
	switch view {
	case todayRoundJSON, challengeDetailJSON:
		writeJSONText(b, `,"ruleDescription":`, description)
		writeJSONText(b, `,"scramble":`, c.ScrambleStr)
	case quickRoundJSON:
		ufmt.Fprintf(b, `,"isCustom":%t`, isCustom)
	}
	writeJSONText(b, `,"phase":`, computePhase(c, nowUnix))
	ufmt.Fprintf(b, `,"commitDeadline":%d,"revealDeadline":%d,"commitCount":%d,"revealCount":%d`,
		c.CommitDeadline, c.RevealDeadline, c.CommitCount, c.RevealCount)
	switch view {
	case yesterdayRoundJSON:
		ufmt.Fprintf(b, `,"bestObtm":%d`, bestObtm(c.RoundKey))
	case challengeDetailJSON:
		writeJSONText(b, `,"svgDataUri":`, cube3x3.RenderCubeNetDataURI(c.ScrambleState))
		ufmt.Fprintf(b, `,"unrevealedCount":%d`, c.UnrevealedCount)
		if c.Kind == "quick" {
			ufmt.Fprintf(b, `,"commitWindowSeconds":%d`, c.CommitWindowSeconds)
		}
	}
	b.WriteByte('}')
}

func writeRuleOptionJSON(b *strings.Builder, key, title string, isCustom bool) {
	writeJSONText(b, `{"ruleKey":`, key)
	writeJSONText(b, `,"title":`, title)
	ufmt.Fprintf(b, `,"isCustom":%t}`, isCustom)
}

// GetTodayJSON returns the daily challenges, recent quick rounds, and rule options.
func GetTodayJSON() string {
	nowUnix := time.Now().Unix()
	dayID := nowUnix / secondsPerDay
	classic, twisted := dailyRounds(dayID)
	seeded := classic != nil && twisted != nil
	if !seeded {
		classic, twisted = nil, nil
	}
	var b strings.Builder
	ufmt.Fprintf(&b, `{"nowUnix":%d,"dayId":%d`, nowUnix, dayID)
	writeJSONText(&b, `,"domain":`, Domain)
	ufmt.Fprintf(&b, `,"today":{"seeded":%t,"classic":`, seeded)
	writeRoundJSON(&b, classic, nowUnix, todayRoundJSON)
	b.WriteString(`,"twisted":`)
	writeRoundJSON(&b, twisted, nowUnix, todayRoundJSON)

	classic, twisted = dailyRounds(dayID - 1)
	ufmt.Fprintf(&b, `},"yesterday":{"dayId":%d,"classic":`, dayID-1)
	writeRoundJSON(&b, classic, nowUnix, yesterdayRoundJSON)
	b.WriteString(`,"twisted":`)
	writeRoundJSON(&b, twisted, nowUnix, yesterdayRoundJSON)

	b.WriteString(`},"recentQuickRounds":[`)
	first := true
	forEachRecentQuickRound(func(c *challengeRecord) {
		if !first {
			b.WriteByte(',')
		}
		first = false
		writeRoundJSON(&b, c, nowUnix, quickRoundJSON)
	})
	b.WriteString(`],"availableRules":[`)
	for i, key := range []string{"wca_obtm", "no_fb", "no_half_turns", "checkpoint_cross_f2l", "pattern_checkerboard"} {
		if i > 0 {
			b.WriteByte(',')
		}
		title, _, _ := roundRuleMetadata(key)
		writeRuleOptionJSON(&b, key, title, false)
	}
	customRules.Iterate("", "", func(key string, value any) bool {
		b.WriteByte(',')
		writeRuleOptionJSON(&b, key, value.(registeredRule).Title, true)
		return false
	})
	b.WriteString(`]}`)
	return b.String()
}

// GetChallengeJSON returns the round details or a round-not-found response.
func GetChallengeJSON(roundKey string) string {
	var b strings.Builder
	if c, ok := challenges.Get(roundKey).(*challengeRecord); ok {
		writeRoundJSON(&b, c, time.Now().Unix(), challengeDetailJSON)
	} else {
		writeJSONText(&b, `{"error":`, ErrRoundNotFound)
		writeJSONText(&b, `,"roundKey":`, roundKey)
		b.WriteByte('}')
	}
	return b.String()
}

// GetCommitStatusJSON reports the caller's pending commitment and published solve.
func GetCommitStatusJSON(roundKey string, addr string) string {
	key := roundKey + "|" + addr
	rec, committed := commits.Get(key).(commitreveal.Record)
	revealed := submissions.Has(key)

	var b strings.Builder
	writeJSONText(&b, `{"roundKey":`, roundKey)
	writeJSONText(&b, `,"caller":`, addr)
	ufmt.Fprintf(&b, `,"committed":%t`, committed)
	writeJSONText(&b, `,"commitHash":`, rec.CommitHash)
	ufmt.Fprintf(&b, `,"committedAt":%d,"updatedCount":%d,"revealed":%t}`, rec.CommittedAt, rec.UpdatedCount, revealed)
	return b.String()
}

// GetLeaderboardJSON returns up to limit published solves in score order.
func GetLeaderboardJSON(roundKey string, limit int) string {
	c, ok := challenges.Get(roundKey).(*challengeRecord)
	if !ok {
		return `{"error":"` + ErrRoundNotFound + `"}`
	}
	phase := computePhase(c, time.Now().Unix())
	total := c.RevealCount
	if phase == "commit_open" {
		total, limit = 0, 0
	} else if limit > MaxLeaderboardLimit {
		limit = MaxLeaderboardLimit
	}

	var b strings.Builder
	writeJSONText(&b, `{"roundKey":`, roundKey)
	writeJSONText(&b, `,"phase":`, phase)
	ufmt.Fprintf(&b, `,"totalRevealed":%d,"rows":[`, total)
	if limit > 0 {
		forEachRankedSubmission(roundKey, func(rank int, sub *submissionRecord) bool {
			if rank > 1 {
				b.WriteByte(',')
			}
			writeLeaderboardRowJSON(&b, rank, sub)
			return rank == limit
		})
	}
	b.WriteString(`]}`)
	return b.String()
}

func writeLeaderboardRowJSON(b *strings.Builder, rank int, sub *submissionRecord) {
	ufmt.Fprintf(b, `{"rank":%d`, rank)
	writeJSONText(b, `,"solver":`, sub.Solver)
	ufmt.Fprintf(b, `,"obtm":%d,"qtm":%d,"revealedAt":%d`, sub.OBTM, sub.QTM, sub.RevealedAt)
	writeJSONText(b, `,"moves":`, sub.CanonicalMoves)
	writeJSONText(b, `,"notes":`, sub.Notes)
	writeJSONText(b, `,"modeTag":`, sub.ModeTag)
	writeJSONText(b, `,"agentModel":`, sub.AgentModel)
	b.WriteString(`,"phases":`)
	writePhaseReportJSON(b, &sub.Phases)
	b.WriteByte('}')
}

func writePhaseReportJSON(b *strings.Builder, phases *cube3x3.PhaseReport) {
	if phases == nil {
		b.WriteString("null")
		return
	}
	writeJSONText(b, `{"crossFace":`, phases.CrossFace)
	ufmt.Fprintf(b, `,"crossColor":%d,"crossAtMove":%d,"f2lAtMove":%d,"ollAtMove":%d,"pllAtMove":%d,"segments":[`,
		int(phases.CrossColor), phases.CrossAtMove, phases.F2LAtMove, phases.OLLAtMove, phases.PLLAtMove)
	for i, segment := range phases.Segments {
		if i > 0 {
			b.WriteByte(',')
		}
		writeJSONText(b, `{"name":`, segment.Name)
		ufmt.Fprintf(b, `,"startMove":%d,"endMove":%d,"obtm":%d}`, segment.StartMove, segment.EndMove, segment.OBTM)
	}
	b.WriteString(`]}`)
}

// VerifyDryRunJSON checks a proposed solution without creating a submission.
func VerifyDryRunJSON(roundKey string, moves string) string {
	var result cube3x3.VerifyResult
	if c, ok := challenges.Get(roundKey).(*challengeRecord); ok {
		rule, _ := resolveRule(c.RuleKey)
		result = cube3x3.VerifySolution(c.ScrambleMoves, moves, rule)
	} else {
		result.ErrorCode = ErrRoundNotFound
		result.ErrorMessage = "Round not found."
	}

	var b strings.Builder
	ufmt.Fprintf(&b, `{"valid":%t`, result.Valid)
	writeJSONText(&b, `,"errorCode":`, result.ErrorCode)
	writeJSONText(&b, `,"errorMessage":`, result.ErrorMessage)
	writeJSONText(&b, `,"canonicalMoves":`, result.CanonicalMoves)
	ufmt.Fprintf(&b, `,"obtm":%d,"qtm":%d,"solved":%t,"phases":`, result.OBTM, result.QTM, result.Solved)
	writePhaseReportJSON(&b, result.Phases)
	b.WriteByte('}')
	return b.String()
}

package bench

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1nvxaasuu2muqg0nf05jezu5422qtgnx60h2qlp/cube3x3"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/mux/v0"
	"gno.land/p/nt/ufmt/v0"
)

const benchPage = "/r/g1nvxaasuu2muqg0nf05jezu5422qtgnx60h2qlp/bench"

var benchRouter = mux.NewRouter()

func init() {
	benchRouter.HandleFunc("", renderDashboard)
	benchRouter.HandleFunc("round/{roundKey}", renderRound)
	benchRouter.HandleFunc("solve/{roundKey}/{addr}", renderSolve)
	benchRouter.SetNotFoundHandler(func(res *mux.ResponseWriter, _ *mux.Request) {
		res.Write("# Page not found\n\n[Back to Colorado](" + benchPage + ")\n")
	})
}

// Render serves the Colorado lobby, round details, and published solutions.
func Render(path string) string {
	return benchRouter.Render(strings.TrimPrefix(path, "/"))
}

func roundPage(roundKey string) string {
	return benchPage + ":round/" + roundKey
}

func phaseLabel(phase string) string {
	switch phase {
	case "commit_open":
		return "Open for solutions"
	case "reveal_open":
		return "Open to publish"
	default:
		return "Completed"
	}
}

func renderDashboard(res *mux.ResponseWriter, _ *mux.Request) {
	nowUnix := time.Now().Unix()
	dayID := nowUnix / secondsPerDay
	var b strings.Builder
	b.WriteString("# Colorado\n\n## Today's Challenges\n\n")
	classic, special := dailyRounds(dayID)
	if classic == nil || special == nil {
		b.WriteString("[Start Today's Challenges](" + benchPage + "$help&func=EnsureTodayChallenges)\n")
	} else {
		writeDailyRoundLink(&b, classic, "Classic", nowUnix)
		writeDailyRoundLink(&b, special, "Special", nowUnix)
	}

	b.WriteString("\n## Yesterday's Rounds\n\n")
	classic, special = dailyRounds(dayID - 1)
	if classic == nil && special == nil {
		b.WriteString("There were no rounds yesterday.\n")
	} else {
		for _, round := range []struct {
			challenge *challengeRecord
			label     string
		}{{classic, "Classic"}, {special, "Special"}} {
			if round.challenge != nil {
				writeDailyRoundLink(&b, round.challenge, round.label, nowUnix)
			}
		}
	}

	b.WriteString("\n## Recent Quick Rounds\n\n")
	first := true
	forEachRecentQuickRound(func(c *challengeRecord) {
		if first {
			b.WriteString("| Round | Rule | Status |\n| --- | --- | --- |\n")
			first = false
		}
		title, _, _ := roundRuleMetadata(c.RuleKey)
		ufmt.Fprintf(&b, "| [Quick Round %s](%s) | %s | %s |\n",
			strings.TrimPrefix(c.RoundKey, "Q:"), roundPage(c.RoundKey), sanitize.TableCell(title), phaseLabel(computePhase(c, nowUnix)))
	})
	if first {
		b.WriteString("No quick rounds yet.\n")
	}

	b.WriteString("\n## Community Rules\n\n")
	if customRules.Size() == 0 {
		b.WriteString("No community rules yet.\n")
	}
	customRules.Iterate("", "", func(_ string, value any) bool {
		rule := value.(registeredRule)
		b.WriteString("- **" + sanitize.InlineText(rule.Title) + "**")
		if rule.Description != "" {
			b.WriteString(" · " + sanitize.InlineText(rule.Description))
		}
		b.WriteByte('\n')
		return false
	})
	res.Write(b.String())
}

func writeDailyRoundLink(b *strings.Builder, c *challengeRecord, label string, nowUnix int64) {
	title, _, _ := roundRuleMetadata(c.RuleKey)
	ufmt.Fprintf(b, "- [%s](%s) · %s · %s\n", label, roundPage(c.RoundKey), sanitize.InlineText(title), phaseLabel(computePhase(c, nowUnix)))
}

func roundTitle(c *challengeRecord) string {
	category := "Classic Challenge"
	switch c.Kind {
	case "quick":
		return "Quick Round " + strings.TrimPrefix(c.RoundKey, "Q:")
	case "daily_twisted":
		category = "Special Challenge"
	}
	day := time.Unix(c.CommitDeadline-secondsPerDay, 0).UTC()
	return category + " · " + day.Format("January 2, 2006")
}

func renderRound(res *mux.ResponseWriter, req *mux.Request) {
	c, ok := challenges.Get(req.GetVar("roundKey")).(*challengeRecord)
	if !ok {
		res.Write("# Round not found\n\n[Back to Colorado](" + benchPage + ")\n")
		return
	}
	var b strings.Builder
	phase := computePhase(c, time.Now().Unix())
	title, description, _ := roundRuleMetadata(c.RuleKey)
	b.WriteString("[Back to Colorado](" + benchPage + ")\n\n# " + roundTitle(c) + "\n\n## " + sanitize.InlineText(title) + "\n\n")
	if description != "" {
		b.WriteString("Rule details · " + sanitize.InlineText(description) + "\n\n")
	}
	const dateFormat = "2006-01-02 15:04:05 UTC"
	ufmt.Fprintf(&b, "**%s**\n\n- Submissions close at %s\n- Publishing closes at %s\n\n",
		phaseLabel(phase), time.Unix(c.CommitDeadline, 0).UTC().Format(dateFormat), time.Unix(c.RevealDeadline, 0).UTC().Format(dateFormat))
	b.WriteString("## Scramble\n\n" + sanitize.CodeBlock(c.ScrambleStr) + "\n\n")
	b.WriteString(cube3x3.RenderCubeNetMarkdown(c.ScrambleState, "Scrambled 3x3 cube net") + "\n\n")
	if phase == "commit_open" {
		b.WriteString("Solutions stay hidden until publishing opens.\n")
	} else {
		writeLeaderboardMarkdown(&b, c.RoundKey)
	}
	if phase == "finalized" && c.UnrevealedCount > 0 {
		ufmt.Fprintf(&b, "\n[Clean Up Expired Entries](%s$help&func=PruneExpiredCommits&roundKey=%s&maxDelete=%d)\n",
			benchPage, c.RoundKey, DefaultPruneLimit)
	}
	res.Write(b.String())
}

func writeLeaderboardMarkdown(b *strings.Builder, roundKey string) {
	b.WriteString("## Leaderboard\n\n")
	first := true
	forEachRankedSubmission(roundKey, func(rank int, sub *submissionRecord) bool {
		if first {
			b.WriteString("| Rank | Player | Moves | Quarter turns |\n| ---: | --- | ---: | ---: |\n")
			first = false
		}
		ufmt.Fprintf(b, "| %d | [%s](%s:solve/%s/%s) | %d | %d |\n", rank, sub.Solver, benchPage, roundKey, sub.Solver, sub.OBTM, sub.QTM)
		return rank == MaxLeaderboardLimit
	})
	if first {
		b.WriteString("No published solutions yet.\n")
	}
}

func renderSolve(res *mux.ResponseWriter, req *mux.Request) {
	roundKey := req.GetVar("roundKey")
	c, ok := challenges.Get(roundKey).(*challengeRecord)
	if !ok {
		res.Write("# Round not found\n\n[Back to Colorado](" + benchPage + ")\n")
		return
	}
	back := "[Back to Round](" + roundPage(c.RoundKey) + ")\n\n"
	if computePhase(c, time.Now().Unix()) == "commit_open" {
		res.Write(back + "Solutions stay hidden until publishing opens.\n")
		return
	}
	addr := req.GetVar("addr")
	sub, ok := submissions.Get(roundKey + "|" + addr).(*submissionRecord)
	if !ok {
		res.Write(back + "# Solution not found\n")
		return
	}
	var b strings.Builder
	b.WriteString(back + "# Published Solution\n\n")
	if rank := submissionRank(roundKey, sub); rank > 0 {
		ufmt.Fprintf(&b, "Rank %d · ", rank)
	}
	ufmt.Fprintf(&b, "%d moves · %d quarter turns\n\n", sub.OBTM, sub.QTM)
	b.WriteString("**Solve method (self-declared)** " + solverModeLabel(sub.ModeTag))
	if sub.AgentModel != "" {
		b.WriteString(" · " + sanitize.InlineText(sub.AgentModel))
	}
	b.WriteString("\n\n## Moves\n\n" + sanitize.CodeBlock(sub.CanonicalMoves) + "\n\n")
	b.WriteString("## Phase Breakdown\n\n| Phase | Completed at move |\n| --- | ---: |\n")
	for _, phase := range []struct {
		name string
		move int
	}{{"Cross", sub.Phases.CrossAtMove}, {"F2L", sub.Phases.F2LAtMove}, {"OLL", sub.Phases.OLLAtMove}, {"PLL", sub.Phases.PLLAtMove}} {
		move := "Not reached"
		if phase.move > 0 {
			move = strconv.Itoa(phase.move)
		}
		ufmt.Fprintf(&b, "| %s | %s |\n", phase.name, move)
	}
	if sub.Notes != "" {
		b.WriteString("\n**Solver notes** " + sanitize.InlineText(sub.Notes) + "\n")
	}
	res.Write(b.String())
}

func solverModeLabel(mode string) string {
	switch mode {
	case "assisted":
		return "Human + AI"
	case "ai":
		return "AI Only"
	default:
		return "Human"
	}
}

package bench

import (
	"crypto/sha256"
	"strconv"
	"strings"

	"gno.land/p/g1nvxaasuu2muqg0nf05jezu5422qtgnx60h2qlp/cube3x3"
	"gno.land/p/nt/avl/v0"
)

var (
	challenges   = avl.NewTree() // roundKey -> *challengeRecord
	commits      = avl.NewTree() // roundKey|addr -> commitreveal.Record
	submissions  = avl.NewTree() // roundKey|addr -> *submissionRecord
	leaderboards *avl.Node       // roundKey|pad(obtm,4)|pad(qtm,4)|pad(revealedAt,12)|addr -> addr
	quickRounds  = avl.NewTree() // pad(seq,10) -> roundKey
	customRules  = avl.NewTree() // <pkgPath>:<ruleID> -> registeredRule
	quickSeq     uint64
)

func computeRoundSeed(roundKey string, height int64, blockTimeUnix int64) [32]byte {
	return sha256.Sum256([]byte(Domain + "|" + roundKey + "|" + strconv.FormatInt(height, 10) + "|" + strconv.FormatInt(blockTimeUnix, 10)))
}

func computePhase(c *challengeRecord, nowUnix int64) string {
	if nowUnix < c.CommitDeadline {
		return "commit_open"
	}
	if nowUnix < c.RevealDeadline {
		return "reveal_open"
	}
	return "finalized"
}

func normalizeModeTag(raw string) (string, bool) {
	switch raw {
	case "":
		return "human", true
	case "human", "assisted", "ai":
		return raw, true
	default:
		return "", false
	}
}

func validateAgentModel(raw string) (string, bool) {
	model := strings.Trim(raw, " ")
	if len(model) > MaxAgentModelBytes {
		return "", false
	}
	for i := 0; i < len(model); i++ {
		if model[i] < 0x20 || model[i] > 0x7e {
			return "", false
		}
	}
	return model, true
}

// padInt64 preserves numeric ordering for nonnegative key parts that fit width.
func padInt64(n int64, width int) string {
	digits := strconv.FormatInt(n, 10)
	if len(digits) >= width {
		return digits
	}
	return strings.Repeat("0", width-len(digits)) + digits
}

// prefixRangeEnd returns the exclusive AVL bound for prefix roundKey + "|".
// ASCII '~' sorts after '|', decimal digits and lowercase address characters.
func prefixRangeEnd(prefix string) string {
	return prefix + "~"
}

func leaderboardKey(roundKey string, sub *submissionRecord) string {
	return roundKey + "|" + padInt64(int64(sub.OBTM), 4) + "|" + padInt64(int64(sub.QTM), 4) + "|" +
		padInt64(sub.RevealedAt, 12) + "|" + sub.Solver
}

func submissionRank(roundKey string, sub *submissionRecord) int {
	index, _, found := leaderboards.Get(leaderboardKey(roundKey, sub))
	if !found {
		return 0
	}
	// Get returns the insertion index for a missing key. The bare prefix sorts
	// immediately before this round's entries, so its index is the round's offset.
	first, _, _ := leaderboards.Get(roundKey + "|")
	return index - first + 1
}

func resolveRule(ruleKey string) (cube3x3.ConstraintRule, bool) {
	if rule, ok := cube3x3.BuiltinRule(ruleKey); ok {
		return rule, true
	}
	entry, ok := customRules.Get(ruleKey).(registeredRule)
	return entry.Rule, ok
}

