// Package townmath holds the pure integer formulas shared by the town realm,
// the villagers realm and (later) a Go operator server. No state, no floats.
package townmath

// BpsOne is 100% in basis points.
const BpsOne int64 = 10000

// MulBps returns x * bps / 10000 without overflowing for large x.
// It splits x so the intermediate products stay small:
// x/10000*bps + x%10000*bps/10000.
func MulBps(x, bps int64) int64 {
	return x/BpsOne*bps + x%BpsOne*bps/BpsOne
}

// clamp limits v to the range [lo, hi].
func clamp(v, lo, hi int64) int64 {
	if v < lo {
		return lo
	}
	if v > hi {
		return hi
	}
	return v
}

package townmath

// Mix is the splitmix64 finalizer applied to x + golden gamma. It is a pure
// deterministic hash; uint64 arithmetic wraps on overflow.
func Mix(x uint64) uint64 {
	x += 0x9E3779B97F4A7C15
	z := x
	z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9
	z = (z ^ (z >> 27)) * 0x94D049BB133111EB
	return z ^ (z >> 31)
}

// Event kinds.
const (
	EventNone     = 0
	EventFestival = 1
	EventShortage = 2
	EventRival    = 3
	EventTaxDay   = 4
)

// Event is the town-wide modifier for one game day. BoostBps scales customer
// demand, GrainMulBps scales the grain price, TaxBps is a tax on a tavern's
// gold (the town realm deducts it once per tax day).
// Hours is 24 for every real event (it lasts the whole game day) and 0 for
// EventNone.
type Event struct {
	Kind                                 int
	BoostBps, GrainMulBps, TaxBps, Hours int64
}

// EventForDay derives the event for a game day from the season seed.
// Distribution: 55% none, 15% festival, 15% shortage, 8% rival, 7% tax day.
func EventForDay(seed uint64, day int64) Event {
	roll := Mix(seed+uint64(day)) % 100
	switch {
	case roll < 55:
		return Event{Kind: EventNone, BoostBps: 10000, GrainMulBps: 10000}
	case roll < 70:
		return Event{Kind: EventFestival, BoostBps: 17000, GrainMulBps: 10000, Hours: 24}
	case roll < 85:
		return Event{Kind: EventShortage, BoostBps: 10000, GrainMulBps: 18000, Hours: 24}
	case roll < 93:
		return Event{Kind: EventRival, BoostBps: 7000, GrainMulBps: 10000, Hours: 24}
	}
	return Event{Kind: EventTaxDay, BoostBps: 10000, GrainMulBps: 10000, TaxBps: 800, Hours: 24}
}

package townmath

// Farm, Town Farm and ad constants.
const (
	CropGrain           = 0
	CropHops            = 1
	GrainPerPlotHour    = 3
	HopsPerPlotHour     = 2
	MaxFarmCatchUpHours = 24
	MaxFarmPlots        = 50
	MaxAdLevel          = 5
	MaxAdHours          = 24
	AdLevelBps          = 500
	AdUnitCostCg        = 100
)

// Harvest returns the crop made by a farm and the stock after storing it.
// Hours are clamped to 0..MaxFarmCatchUpHours and plots to 0..MaxFarmPlots
// before multiplying, so nothing overflows. An unknown crop makes nothing.
// yieldBps is clamped to 0..20000. A negative stock counts as 0 and a
// negative storageCap means no room. Made is limited to the room left.
func Harvest(plots int64, crop int, hours, stock, storageCap, yieldBps int64) (made, stockAfter int64) {
	plots = clamp(plots, 0, MaxFarmPlots)
	hours = clamp(hours, 0, MaxFarmCatchUpHours)
	if stock < 0 {
		stock = 0
	}
	rate := int64(0)
	if crop == CropGrain {
		rate = GrainPerPlotHour
	} else if crop == CropHops {
		rate = HopsPerPlotHour
	}
	gross := plots * rate * hours
	made = MulBps(gross, clamp(yieldBps, 0, 2*BpsOne))
	if storageCap < 0 {
		storageCap = 0
	}
	room := storageCap - stock // both >= 0, cannot wrap
	if room < 0 {
		room = 0
	}
	made = min64(made, room)
	return made, stock + made
}

// HarvestCarry is Harvest with the fraction of a unit carried between calls,
// so settling often makes the same crop as settling once. Carry is in
// 1/10000 units, clamped to 0..9999 on input. total = plots*rate*hours *
// yieldBps + carry (the same clamps as Harvest: at most 3600 * 20000 + 9999,
// no overflow); made = total / 10000, newCarry = total % 10000 (always
// 0..9999, also when full storage limits made). Made is limited to the room
// left, as in Harvest.
func HarvestCarry(plots int64, crop int, hours, stock, storageCap, yieldBps, carry int64) (made, stockAfter, newCarry int64) {
	plots = clamp(plots, 0, MaxFarmPlots)
	hours = clamp(hours, 0, MaxFarmCatchUpHours)
	if stock < 0 {
		stock = 0
	}
	rate := int64(0)
	if crop == CropGrain {
		rate = GrainPerPlotHour
	} else if crop == CropHops {
		rate = HopsPerPlotHour
	}
	total := plots*rate*hours*clamp(yieldBps, 0, 2*BpsOne) + clamp(carry, 0, BpsOne-1)
	made = total / BpsOne
	newCarry = total % BpsOne
	if storageCap < 0 {
		storageCap = 0
	}
	room := storageCap - stock // both >= 0, cannot wrap
	if room < 0 {
		room = 0
	}
	made = min64(made, room)
	return made, stock + made, newCarry
}

// TownFarmSellCg is the price a player PAYS the Town Farm for one unit of a
// good. The Town Farm sells above market: marketCg * sellBps, with sellBps
// clamped to 10000..30000 (default 13000, so 130% of market). Never below 1,
// and a market price <= 0 gives 1. The realm must pass a fixed constant such
// as 13000, never a caller-supplied value.
func TownFarmSellCg(marketCg, sellBps int64) int64 {
	v := MulBps(marketCg, clamp(sellBps, BpsOne, 3*BpsOne))
	if v < 1 {
		return 1
	}
	return v
}

// TownFarmBuyCg is the price the Town Farm PAYS a player for one unit of a
// good. The Town Farm buys below market: marketCg * buyBps, with buyBps
// clamped to 1000..10000 (default 7000, so 70% of market). Never below 1,
// and a market price <= 0 gives 1. The realm must pass a fixed constant such
// as 7000, never a caller-supplied value. Because the farm pays less than it
// charges, buying and reselling to the farm always loses gold.
func TownFarmBuyCg(marketCg, buyBps int64) int64 {
	v := MulBps(marketCg, clamp(buyBps, BpsOne/10, BpsOne))
	if v < 1 {
		return 1
	}
	return v
}

// Capped returns how much of amount still fits under limit given used so far.
// Never negative and never more than amount. Negative limit or used count as
// 0, so extreme inputs cannot wrap.
func Capped(amount, limit, used int64) int64 {
	if amount <= 0 {
		return 0
	}
	if limit < 0 {
		limit = 0
	}
	if used < 0 {
		used = 0
	}
	room := limit - used // both >= 0, cannot wrap
	if room <= 0 {
		return 0
	}
	return min64(amount, room)
}

// AdWeightBps is the customer-draw weight of a tavern ad level, in bps.
func AdWeightBps(level int64) int64 {
	return BpsOne + clamp(level, 0, MaxAdLevel)*AdLevelBps
}

// AdCostCg is the gold cost of running an ad level for the given hours.
func AdCostCg(level, hours int64) int64 {
	return clamp(level, 0, MaxAdLevel) * clamp(hours, 0, MaxAdHours) * AdUnitCostCg
}

package townmath

// HourCurveTable is the relative customer demand for each hour of the day
// (index 0 to 23), in arbitrary weight units.
var HourCurveTable = [24]int64{2, 1, 0, 0, 0, 0, 1, 2, 3, 3, 4, 5, 6, 6, 5, 5, 6, 8, 12, 15, 16, 14, 9, 4}

// Supply drift constants.
const (
	maxDriftHours = 48
	driftPercent  = 2
)

// PriceFactorBps returns how a tavern's menu price affects demand, in basis
// points. A price equal to the market price gives 10000. Cheaper sells more
// (up to 20000), dearer sells less (down to 800). mkt <= 0 gives 10000.
func PriceFactorBps(price, mkt int64) int64 {
	if mkt <= 0 {
		return BpsOne
	}
	return clamp(BpsOne+(mkt-price)*22000/mkt, 800, 20000)
}

// RepFactorBps returns the reputation effect on demand in basis points:
// 6000 at rep 0 up to 14000 at rep 500 and above. Negative rep counts as 0.
func RepFactorBps(rep int64) int64 {
	return 6000 + clamp(rep, 0, 500)*16
}

// HourCurve returns the demand weight for an hour of day. The hour wraps
// modulo 24, so 24 is hour 0 and -1 is hour 23.
func HourCurve(hour int) int64 {
	h := hour % 24
	if h < 0 {
		h += 24
	}
	return HourCurveTable[h]
}

// SupplyBps returns total as a share of target in basis points. A target of
// zero or less gives 5000 (the neutral midpoint).
func SupplyBps(total, target int64) int64 {
	if target <= 0 {
		return 5000
	}
	return total * BpsOne / target
}

// PriceFromSupply turns a supply level (basis points of target) into a price.
// Supply is clamped to [1500, 8800]; 5000 gives the base price, scarcer is
// dearer, plentiful is cheaper. The result is never below 1.
func PriceFromSupply(baseCg, supplyBps int64) int64 {
	s := clamp(supplyBps, 1500, 8800)
	p := MulBps(baseCg, BpsOne+(5000-s)*9/10)
	if p < 1 {
		return 1
	}
	return p
}

// DriftSupply moves supply toward half of target by 2% of the gap per hour.
// Hours are capped at 48; zero or fewer hours returns supply unchanged.
func DriftSupply(supply, target, hours int64) int64 {
	if hours > maxDriftHours {
		hours = maxDriftHours
	}
	mid := target / 2
	for i := int64(0); i < hours; i++ {
		supply += (mid - supply) * driftPercent / 100
	}
	return supply
}

package townmath

// Needs are a villager's three needs, each in 0..10000.
type Needs struct {
	Thirst, Fun, Energy int64
}

// TraitMods scale the per-hour decay of each need, in basis points
// (10000 = normal speed, 15000 = decays 50% faster).
type TraitMods struct {
	ThirstBps, FunBps, EnergyBps int64
}

const (
	MoodMiserable = 0
	MoodOkay      = 1
	MoodHappy     = 2

	// RoundCostCg is the gold cost (in centigold) of buying a round.
	RoundCostCg = 600
	// DayOffCostCg is the gold cost of a day off (free).
	DayOffCostCg = 0
)

const (
	needMax         int64 = 10000
	maxDecayHours   int64 = 48
	thirstPerHour   int64 = 300
	funPerHour      int64 = 200
	energyPerHour   int64 = 100
	roundThirstGain int64 = 4000
	dayOffEnergy    int64 = 5000
	moodHappyMin    int64 = 6200
	moodOkayMin     int64 = 4000
)

func clampNeeds(n Needs) Needs {
	return Needs{
		Thirst: clamp(n.Thirst, 0, needMax),
		Fun:    clamp(n.Fun, 0, needMax),
		Energy: clamp(n.Energy, 0, needMax),
	}
}

func decayOne(v, base, modBps, hours int64) int64 {
	perHour := MulBps(base, clamp(modBps, 0, 1<<40))
	return clamp(v-perHour*hours, 0, needMax)
}

// Decay lowers each need by its base hourly rate (thirst 300, fun 200,
// energy 100) scaled by the trait modifier, for the given hours. Hours are
// clamped to 0..48. Results are clamped to 0..10000; negative modifiers
// count as zero.
func Decay(n Needs, m TraitMods, hours int64) Needs {
	n = clampNeeds(n)
	h := clamp(hours, 0, maxDecayHours)
	return Needs{
		Thirst: decayOne(n.Thirst, thirstPerHour, m.ThirstBps, h),
		Fun:    decayOne(n.Fun, funPerHour, m.FunBps, h),
		Energy: decayOne(n.Energy, energyPerHour, m.EnergyBps, h),
	}
}

// Mood maps the average of the three needs to a mood:
// >= 6200 happy, >= 4000 okay, otherwise miserable.
func Mood(n Needs) int {
	n = clampNeeds(n)
	avg := (n.Thirst + n.Fun + n.Energy) / 3
	if avg >= moodHappyMin {
		return MoodHappy
	}
	if avg >= moodOkayMin {
		return MoodOkay
	}
	return MoodMiserable
}

// BuyRound raises thirst by 4000, capped at 10000.
func BuyRound(n Needs) Needs {
	n = clampNeeds(n)
	n.Thirst = clamp(n.Thirst+roundThirstGain, 0, needMax)
	return n
}

// DayOff raises energy by 5000, capped at 10000.
func DayOff(n Needs) Needs {
	n = clampNeeds(n)
	n.Energy = clamp(n.Energy+dayOffEnergy, 0, needMax)
	return n
}

// RegularBonus is the extra customers a villager brings to their tavern.
// Only during hours 18..22: a happy villager with loyalty >= 5 gives 1 (plus
// 1 more at loyalty >= 9); an okay villager with loyalty >= 5 gives 1;
// anything else gives 0.
func RegularBonus(mood int, loyalty int64, hour int) int64 {
	if hour < 18 || hour > 22 || loyalty < 5 {
		return 0
	}
	switch mood {
	case MoodHappy:
		if loyalty >= 9 {
			return 2
		}
		return 1
	case MoodOkay:
		return 1
	}
	return 0
}

package townmath

// Shared customer pool math. All customers of an hour form one pool that is
// split among pubs by weight. Everything is integer math, no floats.

// Defaults for the pool exponent step count and the demand scale. They may be
// tuned later.
const (
	PoolExponentK       = 2
	PoolScaleBps  int64 = 10000
)

// Input caps that keep every intermediate product far below int64 overflow.
const (
	maxPoolPubs   int64 = 1000000
	maxPoolMilli  int64 = 10000000
	maxPoolWeight int64 = 100000000
	maxPoolScale  int64 = 100000
	maxSeatsInPub int64 = 50
)

// maxSqrtArg is the floor of the square root of the largest int64.
const maxSqrtArg int64 = 3037000499

// isqrt returns floor(sqrt(x)) by binary search. x <= 0 gives 0. The loop
// runs at most 32 times.
func isqrt(x int64) int64 {
	if x <= 0 {
		return 0
	}
	lo, hi := int64(0), maxSqrtArg
	if x < hi {
		hi = x
	}
	for i := 0; i < 40 && lo < hi; i++ {
		mid := lo + (hi-lo+1)/2
		if mid*mid <= x {
			lo = mid
		} else {
			hi = mid - 1
		}
	}
	return lo
}

// PoolPowMilli returns n^(1 - 2^-k) * 1000. k is clamped to 1..3 (n^0.5,
// n^0.75, n^0.875). n <= 0 gives 0 and n is capped at 1,000,000. The pool
// grows with the number of pubs, but slower than the pub count, so adding
// pubs never multiplies the customers per pub.
func PoolPowMilli(n int64, k int) int64 {
	if n <= 0 {
		return 0
	}
	if n > maxPoolPubs {
		n = maxPoolPubs
	}
	if k < 1 {
		k = 1
	}
	if k > 3 {
		k = 3
	}
	scaled := n * 1000000
	// r ends as n^(2^-k) * 1000.
	r := isqrt(scaled)
	for i := 1; i < k; i++ {
		r = isqrt(r * 1000)
	}
	if r == 0 {
		return 0
	}
	return scaled / r
}

// PoolCustomersMilli returns the customers (in thousandths) that walk in
// during one hour for a town of pubs pubs: the hour curve times the pool
// power, scaled by scaleBps (clamped to 0..100000).
func PoolCustomersMilli(hour int, pubs int64, k int, scaleBps int64) int64 {
	return MulBps(HourCurve(hour)*PoolPowMilli(pubs, k), clamp(scaleBps, 0, maxPoolScale))
}

// WeightIn holds the inputs that decide a pub's share of the pool.
type WeightIn struct {
	PriceCg, MarketCg, Rep, Seats, StaffBps, AdBps int64
}

// PubWeight returns a pub's pull on the pool: price, reputation, staff and
// ad factors (basis points) times its seats (0..50).
func PubWeight(in WeightIn) int64 {
	f := MulBps(PriceFactorBps(in.PriceCg, in.MarketCg), RepFactorBps(in.Rep))
	f = MulBps(f, clamp(in.StaffBps, 5000, 20000))
	f = MulBps(f, clamp(in.AdBps, 10000, 20000))
	return f * clamp(in.Seats, 0, maxSeatsInPub)
}

// PubShareMilli returns a pub's part of the pool: poolMilli * weight /
// totalWeight, rounded down. Any argument <= 0 gives 0. A weight at or above
// the total takes the whole (capped) pool.
func PubShareMilli(poolMilli, weight, totalWeight int64) int64 {
	if poolMilli <= 0 || weight <= 0 || totalWeight <= 0 {
		return 0
	}
	poolMilli = min64(poolMilli, maxPoolMilli)
	if weight >= totalWeight {
		return poolMilli
	}
	weight = min64(weight, maxPoolWeight)
	return poolMilli * weight / totalWeight
}

// CarryDemand adds a fractional carry (0..999) to milli customers and returns
// the whole customers plus the new carry. Negative milli counts as 0.
func CarryDemand(milli, carry int64) (customers, newCarry int64) {
	if milli < 0 {
		milli = 0
	}
	total := milli + clamp(carry, 0, 999)
	return total / 1000, total % 1000
}

package townmath

// PayoutBps is the share of the season pot paid to ranks 1..10, in basis
// points. It sums to 10000.
var PayoutBps = [10]int64{3000, 2000, 1400, 1000, 800, 600, 450, 300, 250, 200}

// Payout returns the prize for a rank (1 to 10) from the pot in ugnot.
// Ranks outside 1..10 and non-positive pots pay 0. Rounding is floor, so the
// total paid never exceeds the pot.
func Payout(potUgnot int64, rank int) int64 {
	if rank < 1 || rank > 10 || potUgnot <= 0 {
		return 0
	}
	return MulBps(potUgnot, PayoutBps[rank-1])
}

// SeasonScore ranks taverns: profit in copper-gold / 100 plus twice the
// reputation.
func SeasonScore(profitCg, rep int64) int64 {
	return profitCg/100 + rep*2
}

// CapGain limits growth per step: min(next, prev+cap). A negative cap is
// treated as 0 so a bad argument cannot push the value below prev.
func CapGain(prev, next, cap int64) int64 {
	if cap < 0 {
		cap = 0
	}
	return min64(next, prev+cap)
}

// SplitPayment splits a payment into the season pot share (potBps of amount,
// rounded down) and the treasury remainder, so pot + treasury == amount.
// potBps is clamped to 0..10000; a non-positive amount splits to (0, 0).
func SplitPayment(amount, potBps int64) (pot, treasury int64) {
	if amount <= 0 {
		return 0, 0
	}
	pot = MulBps(amount, clamp(potBps, 0, BpsOne))
	return pot, amount - pot
}

// Entry is one leaderboard row.
type Entry struct {
	Owner string
	Score int64
}

// UpdateTop returns a new leaderboard with e applied: any existing entry for
// the same owner is replaced by e (new score, even if lower), the list is
// sorted by score descending with ties keeping the earlier entry first, and
// it is truncated to n. top is never modified. n <= 0 returns an empty
// slice; an entry with an empty owner is ignored.
func UpdateTop(top []Entry, e Entry, n int) []Entry {
	out := make([]Entry, 0, len(top)+1)
	if n <= 0 {
		return out
	}
	// copy everything except the owner's old entry
	for i := 0; i < len(top); i++ {
		if e.Owner != "" && top[i].Owner == e.Owner {
			continue
		}
		out = append(out, top[i])
	}
	if e.Owner != "" {
		// insert after every entry whose score is >= e.Score
		pos := len(out)
		for i := 0; i < len(out); i++ {
			if out[i].Score < e.Score {
				pos = i
				break
			}
		}
		out = append(out, Entry{})
		for i := len(out) - 1; i > pos; i-- {
			out[i] = out[i-1]
		}
		out[pos] = e
	}
	if len(out) > n {
		out = out[:n]
	}
	return out
}

// InsertTop applies e to the leaderboard held in buf[:length] in place and
// returns the new length. The result buf[:new length] is exactly
// UpdateTop(buf[:length], e, len(buf)): the owner's old entries are removed,
// e is inserted after every entry with a score >= e.Score, and the list is
// cut to len(buf). It allocates nothing, so a realm can keep its board in a
// fixed array and update it with element writes. length is clamped to
// 0..len(buf); an entry with an empty owner changes nothing. Loops are
// bounded by len(buf).
func InsertTop(buf []Entry, length int, e Entry) int {
	n := len(buf)
	if n <= 0 {
		return 0
	}
	if length < 0 {
		length = 0
	}
	if length > n {
		length = n
	}
	if e.Owner == "" {
		return length
	}
	// remove every old entry of the owner, keeping the order of the rest
	k := 0
	for i := 0; i < length; i++ {
		if buf[i].Owner == e.Owner {
			continue
		}
		if k != i {
			buf[k] = buf[i]
		}
		k++
	}
	for i := k; i < length; i++ {
		buf[i] = Entry{}
	}
	length = k
	pos := length
	for i := 0; i < length; i++ {
		if buf[i].Score < e.Score {
			pos = i
			break
		}
	}
	if pos >= n {
		return length // full and e ranks last: dropped, as UpdateTop cuts it
	}
	end := length
	if end == n {
		end = n - 1 // the last entry falls off
	}
	for j := end; j > pos; j-- {
		buf[j] = buf[j-1]
	}
	buf[pos] = e
	if length < n {
		length++
	}
	return length
}

package townmath

// MaxCatchUpHours caps how many hours one settlement applies.
const MaxCatchUpHours int64 = 24

// Reputation bounds after settlement.
const (
	repMin int64 = 50
	repMax int64 = 500
)

// SettleIn is the state of one tavern entering settlement.
// PriceCg is the menu price, MarketCg the market price of the same item.
// EventBps and StaffBps are demand multipliers in basis points (10000 = 1.0).
// RegularBonus is extra customers per hour from regulars.
type SettleIn struct {
	PriceCg, MarketCg, Rep, Stock, Seats, EventBps, StaffBps, RegularBonus int64
}

// SettleOut is the result of settling one or more hours.
// RepDelta is the raw sum of the per-hour changes (before the [50,500]
// clamp); RepAfter is the clamped reputation to store.
type SettleOut struct {
	Served, UnservedStock, RevenueCg, RepDelta, StockLeft, RepAfter, HoursApplied int64
}

func min64(a, b int64) int64 {
	if a < b {
		return a
	}
	return b
}

// SettleHour settles a single hour of day. The potential customer count comes
// from the formulas below, then SettleHourDemand applies the seat and stock
// limits. Nothing negative is ever served.
func SettleHour(hour int, in SettleIn) SettleOut {
	potential := HourCurve(hour)
	potential = potential * PriceFactorBps(in.PriceCg, in.MarketCg) / BpsOne
	potential = potential * RepFactorBps(in.Rep) / BpsOne
	potential = potential * in.EventBps / BpsOne
	potential = potential * in.StaffBps / BpsOne
	potential += in.RegularBonus
	return SettleHourDemand(in, potential)
}

// SettleHourDemand settles one hour for a given customer demand instead of
// the formula potential. A negative demand counts as zero. Seats, stock and
// price are floored at zero, and at most Seats*2 customers are served.
func SettleHourDemand(in SettleIn, demand int64) SettleOut {
	if demand < 0 {
		demand = 0
	}

	seats := in.Seats
	if seats < 0 {
		seats = 0
	}
	stock := in.Stock
	if stock < 0 {
		stock = 0
	}
	price := in.PriceCg
	if price < 0 {
		price = 0
	}

	capped := min64(demand, seats*2)
	served := min64(capped, stock)
	unserved := capped - served
	repDelta := served/5 - unserved*4/5

	return SettleOut{
		Served:        served,
		UnservedStock: unserved,
		RevenueCg:     served * price,
		RepDelta:      repDelta,
		StockLeft:     stock - served,
		RepAfter:      clamp(in.Rep+repDelta, repMin, repMax),
		HoursApplied:  1,
	}
}

// SettleRange settles hours consecutive hours starting at startHour (wrapping
// modulo 24), carrying stock and reputation from each hour to the next.
// hours is capped at MaxCatchUpHours; zero or fewer returns the input stock
// and reputation unchanged.
func SettleRange(startHour int, hours int64, in SettleIn) SettleOut {
	if hours > MaxCatchUpHours {
		hours = MaxCatchUpHours
	}
	total := SettleOut{StockLeft: in.Stock, RepAfter: in.Rep}
	cur := in
	for i := int64(0); i < hours; i++ {
		out := SettleHour(startHour+int(i), cur)
		total.Served += out.Served
		total.UnservedStock += out.UnservedStock
		total.RevenueCg += out.RevenueCg
		total.RepDelta += out.RepDelta
		total.StockLeft = out.StockLeft
		total.RepAfter = out.RepAfter
		total.HoursApplied++
		cur.Stock = out.StockLeft
		cur.Rep = out.RepAfter
	}
	return total
}

// SettleRangeDemand settles one hour per entry of demands, carrying stock and
// reputation from each hour to the next like SettleRange. At most
// MaxCatchUpHours entries are used and HoursApplied counts them. A negative
// entry counts as zero customers but still uses its hour. An empty or nil
// slice returns the input stock and reputation unchanged.
func SettleRangeDemand(demands []int64, in SettleIn) SettleOut {
	n := int64(len(demands))
	if n > MaxCatchUpHours {
		n = MaxCatchUpHours
	}
	total := SettleOut{StockLeft: in.Stock, RepAfter: in.Rep}
	cur := in
	for i := int64(0); i < n; i++ {
		out := SettleHourDemand(cur, demands[i])
		total.Served += out.Served
		total.UnservedStock += out.UnservedStock
		total.RevenueCg += out.RevenueCg
		total.RepDelta += out.RepDelta
		total.StockLeft = out.StockLeft
		total.RepAfter = out.RepAfter
		total.HoursApplied++
		cur.Stock = out.StockLeft
		cur.Rep = out.RepAfter
	}
	return total
}

package villagersv1

import (
	"gno.land/p/nt/grc721/v0"
	"gno.land/p/g17wg7tk6az05tz7vu6qfkvzau6p30aezuct3nt3/townmath"
)

// Restricted functions: only the realm whose package path is the stored
// town path may call them. A user call (PkgPath "") and any other realm
// abort, and so does everyone before SetTown.
//
// Coins: these functions do not check unsafe.OriginSend. The only allowed
// caller is the town realm, and the town's GNOT shop mints in the same
// transaction as the player's payment, so OriginSend is non-empty there. The
// payment goes to the realm the player called (the town), never to this
// realm, so no coins can be stuck here.

// MintFor mints a new villager to `to` from seed at game hour hoursNow and
// returns its token id (the next sequential decimal id).
func MintFor(cur realm, to address, seed uint64, hoursNow int64) string {
	assertTown(cur)
	assertHour(hoursNow)
	if !to.IsValid() {
		panic("villagers: invalid address")
	}
	n := lastID + 1
	id := idOf(n)
	key, ok := keyOf(id)
	if !ok {
		panic("villagers: id space exhausted")
	}
	// The ledger mint is the first write and fails without writing.
	if err := ledger.Mint(to, grc721.TokenID(id)); err != nil {
		panic("villagers: " + err.Error())
	}
	lastID = n
	records.Set(key, &Villager{
		ID:      id,
		Seed:    seed,
		Job:     RollJob(seed),
		Loyalty: StartLoyalty,
		Traits:  RollTraits(seed),
		Needs:   townmath.Needs{Thirst: StartNeed, Fun: StartNeed, Energy: StartNeed},
		NeedsAt: hoursNow,
	})
	return id
}

// ApplyRound settles the villager's needs to hoursNow, then a bought round:
// +4000 thirst (capped) and loyalty +1 up to MaxLoyalty.
func ApplyRound(cur realm, id string, hoursNow int64) {
	assertTown(cur)
	assertHour(hoursNow)
	v := mustGet(id)
	n := townmath.BuyRound(needsAt(v, hoursNow))
	settle(v, n, hoursNow)
	if v.Loyalty < MaxLoyalty {
		v.Loyalty++
	}
}

// ApplyDayOff settles the villager's needs to hoursNow, then a day off:
// +5000 energy (capped).
func ApplyDayOff(cur realm, id string, hoursNow int64) {
	assertTown(cur)
	assertHour(hoursNow)
	v := mustGet(id)
	settle(v, townmath.DayOff(needsAt(v, hoursNow)), hoursNow)
}

// settle stores needs n as of hoursNow. NeedsAt never moves back, so an
// earlier hour (which decayed 0 hours) cannot make a later call decay the
// same hours twice.
func settle(v *Villager, n townmath.Needs, hoursNow int64) {
	v.Needs = n
	if hoursNow > v.NeedsAt {
		v.NeedsAt = hoursNow
	}
}

// assertHour aborts unless 0 <= hoursNow <= MaxHour. Every stored NeedsAt
// passed this check, so hoursNow - NeedsAt cannot overflow.
func assertHour(hoursNow int64) {
	if hoursNow < 0 || hoursNow > MaxHour {
		panic("villagers: bad hour")
	}
}

// assertTown aborts unless the caller is the town realm.
func assertTown(cur realm) {
	prev := cur.Previous()
	if townPath == "" || prev.IsUserCall() || prev.PkgPath() != townPath {
		panic("villagers: town only")
	}
}

package villagersv1

import "gno.land/p/g17wg7tk6az05tz7vu6qfkvzau6p30aezuct3nt3/townmath"

// TraitCount is the number of traits; trait indexes are 0..TraitCount-1.
const TraitCount = 8

// Trait indexes.
const (
	TraitNightOwl   = 0
	TraitLoud       = 1
	TraitCharming   = 2
	TraitGrumpy     = 3
	TraitHardWorker = 4
	TraitBroke      = 5
	TraitCreative   = 6
	TraitCheerful   = 7
)

// Jobs (Villager.Job).
const (
	JobRegular = 0
	JobBard    = 1
	JobCook    = 2
	JobBarkeep = 3
)

const jobCount = 4

// TraitName returns the trait's display name, or "" for an index out of range.
func TraitName(i int) string {
	switch i {
	case TraitNightOwl:
		return "NIGHT OWL"
	case TraitLoud:
		return "LOUD"
	case TraitCharming:
		return "CHARMING"
	case TraitGrumpy:
		return "GRUMPY"
	case TraitHardWorker:
		return "HARD WORKER"
	case TraitBroke:
		return "BROKE"
	case TraitCreative:
		return "CREATIVE"
	case TraitCheerful:
		return "CHEERFUL"
	}
	return ""
}

// traitMods returns one trait's decay modifiers in basis points
// (10000 = normal). An index out of range is neutral (10000 each).
func traitMods(i int) townmath.TraitMods {
	switch i {
	case TraitNightOwl:
		return townmath.TraitMods{ThirstBps: 10000, FunBps: 10000, EnergyBps: 5000}
	case TraitLoud:
		return townmath.TraitMods{ThirstBps: 15000, FunBps: 10000, EnergyBps: 10000}
	case TraitCharming:
		return townmath.TraitMods{ThirstBps: 10000, FunBps: 7000, EnergyBps: 10000}
	case TraitGrumpy:
		return townmath.TraitMods{ThirstBps: 10000, FunBps: 15000, EnergyBps: 10000}
	case TraitHardWorker:
		return townmath.TraitMods{ThirstBps: 10000, FunBps: 10000, EnergyBps: 7000}
	case TraitBroke:
		return townmath.TraitMods{ThirstBps: 12000, FunBps: 10000, EnergyBps: 10000}
	case TraitCreative:
		return townmath.TraitMods{ThirstBps: 10000, FunBps: 8000, EnergyBps: 12000}
	case TraitCheerful:
		return townmath.TraitMods{ThirstBps: 9000, FunBps: 9000, EnergyBps: 10000}
	}
	return townmath.TraitMods{ThirstBps: 10000, FunBps: 10000, EnergyBps: 10000}
}

// CombinedMods multiplies the two traits' modifiers component by component
// (townmath.MulBps). An index out of range counts as 10000.
func CombinedMods(t [2]int) townmath.TraitMods {
	a, b := traitMods(t[0]), traitMods(t[1])
	return townmath.TraitMods{
		ThirstBps: townmath.MulBps(a.ThirstBps, b.ThirstBps),
		FunBps:    townmath.MulBps(a.FunBps, b.FunBps),
		EnergyBps: townmath.MulBps(a.EnergyBps, b.EnergyBps),
	}
}

// RollTraits returns the two distinct trait indexes a seed gives:
// a = Mix(seed) % 8, b = (a + 1 + Mix(seed ^ 0x5A5A) % 7) % 8, so b != a.
// Pure: the web client can replay it.
func RollTraits(seed uint64) [2]int {
	a := townmath.Mix(seed) % TraitCount
	b := (a + 1 + townmath.Mix(seed^0x5A5A)%(TraitCount-1)) % TraitCount
	return [2]int{int(a), int(b)}
}

// RollJob returns the job a seed gives: Mix(seed ^ 0xA5A5) % 4.
func RollJob(seed uint64) int64 {
	return int64(townmath.Mix(seed^0xA5A5) % jobCount)
}

// Package villagers holds The Joint's collectible villagers: GRC721 tokens
// with two traits, a job, loyalty and three needs that decay over game hours.
// Only the town realm (its path is set once by the admin) can mint villagers
// and change their needs; owners move them with the GRC721 calls below.
// Needs are settled lazily: a record keeps the needs at NeedsAt and reads
// project them forward with townmath.Decay.
package villagersv1

import (
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/grc721/v0"
	"gno.land/p/nt/ownable/v0"
	"gno.land/p/g17wg7tk6az05tz7vu6qfkvzau6p30aezuct3nt3/townmath"
)

// Starting values of a new villager.
const (
	StartLoyalty int64 = 3
	MaxLoyalty   int64 = 10
	StartNeed    int64 = 8000
)

// MaxHour is the largest game hour the restricted functions accept (about
// 317 years at 10 seconds per game hour).
const MaxHour int64 = 1_000_000_000

// MaxPage is the largest page Villagers returns.
const MaxPage = 50

// idWidth is the zero-padded width of record keys, so the tree orders
// villagers by numeric id.
const idWidth = 12

// noKeyAdmin is used only when init sees an empty deployer address, which
// happens in the gno test VM (package init runs with an empty caller) and
// never on chain. It is the raw bytes "noadmin_____________", not derived
// from any public key, so nobody can sign as it. Tests act as admin through
// Admin().
const noKeyAdmin address = "g1dehkzerdd9h97h6lta047h6lta047h6l4mazdj"

// Villager is one villager's record. ID is the GRC721 token id (a decimal
// string). Traits are two distinct trait indexes. Needs are the needs at
// game hour NeedsAt.
type Villager struct {
	ID      string
	Seed    uint64
	Job     int64
	Loyalty int64
	Traits  [2]int
	Needs   townmath.Needs
	NeedsAt int64
}

var (
	admin    *ownable.Ownable
	townPath string
	token    *grc721.Token
	ledger   *grc721.PrivateLedger
	teller   grc721.Teller
	records  avl.Tree // zero-padded id -> *Villager
	lastID   int64    // the last id minted; ids start at 1
)

func init(cur realm) {
	deployer := cur.Previous().Address()
	if deployer == "" {
		deployer = noKeyAdmin
	}
	admin = ownable.NewWithAddress(deployer)
	token, ledger = grc721.NewToken("The Joint Villager", "TJV", 0, cur)
	teller = ledger.CallerTeller()
}

// Admin returns the admin address (the deployer).
func Admin() address {
	return admin.Owner()
}

// SetTown stores the town realm's package path, the only caller allowed to
// use the restricted functions. Admin only; it can be called once. The path
// must be a realm path (prefix "gno.land/r/").
func SetTown(cur realm, path string) {
	if !admin.OwnedBy(cur.Previous().Address()) {
		panic("villagers: admin only")
	}
	assertNoSend()
	if path == "" {
		panic("villagers: town path is empty")
	}
	if !strings.HasPrefix(path, "gno.land/r/") {
		panic("villagers: town must be a realm path")
	}
	if townPath != "" {
		panic("villagers: town already set")
	}
	townPath = path
}

// GetTown returns the stored town path ("" before SetTown).
func GetTown() string {
	return townPath
}

// Count returns the number of villagers.
func Count() int {
	return records.Size()
}

// GetVillager returns a copy of a villager's record. Aborts for an unknown id.
func GetVillager(id string) Villager {
	return *mustGet(id)
}

// NeedsNow projects a villager's needs to hoursNow with its traits; nothing
// is stored. An hour before NeedsAt counts as 0 elapsed hours.
func NeedsNow(id string, hoursNow int64) townmath.Needs {
	return needsAt(mustGet(id), hoursNow)
}

// MoodNow is townmath.Mood of NeedsNow.
func MoodNow(id string, hoursNow int64) int {
	return townmath.Mood(needsAt(mustGet(id), hoursNow))
}

// OwnerOf returns a villager's owner. Aborts for an unknown id.
func OwnerOf(id string) address {
	mustGet(id)
	owner, err := token.OwnerOf(grc721.TokenID(id))
	if err != nil {
		panic("villagers: " + err.Error())
	}
	return owner
}

// Villagers returns copies of up to count villagers (clamped to 1..50)
// starting at offset (negative counts as 0), ordered by id.
func Villagers(offset, count int) []Villager {
	if offset < 0 {
		offset = 0
	}
	if count < 1 {
		count = 1
	}
	if count > MaxPage {
		count = MaxPage
	}
	n := records.Size() - offset
	if n <= 0 {
		return []Villager{}
	}
	if n > count {
		n = count
	}
	out := make([]Villager, 0, n)
	records.IterateByOffset(offset, n, func(_ string, value any) bool {
		out = append(out, *value.(*Villager))
		return false
	})
	return out
}

// TransferFrom moves a villager from `from` to `to`. The signer must own it
// or be approved for it. A wallet pop-up is expected: NFT moves are never
// batched.
func TransferFrom(cur realm, from, to address, id string) {
	assertNoSend()
	if err := teller.TransferFrom(0, cur, from, to, grc721.TokenID(id)); err != nil {
		panic("villagers: " + err.Error())
	}
}

// Approve lets `to` transfer one villager (the zero address revokes).
func Approve(cur realm, to address, id string) {
	assertNoSend()
	if err := teller.Approve(0, cur, to, grc721.TokenID(id)); err != nil {
		panic("villagers: " + err.Error())
	}
}

// SetApprovalForAll lets operator transfer all of the signer's villagers.
func SetApprovalForAll(cur realm, operator address, approved bool) {
	assertNoSend()
	if err := teller.SetApprovalForAll(0, cur, operator, approved); err != nil {
		panic("villagers: " + err.Error())
	}
}

// needsAt projects v's needs to hoursNow (no write). An hour at or before
// NeedsAt counts as 0 elapsed hours. NeedsAt is in 0..MaxHour, so the
// subtraction runs only when hoursNow > NeedsAt >= 0 and cannot overflow.
func needsAt(v *Villager, hoursNow int64) townmath.Needs {
	elapsed := int64(0)
	if hoursNow > v.NeedsAt {
		elapsed = hoursNow - v.NeedsAt
	}
	return townmath.Decay(v.Needs, CombinedMods(v.Traits), elapsed)
}

// keyOf returns the record key of a canonical id (decimal, 1..12 digits,
// no leading zero), or false.
func keyOf(id string) (string, bool) {
	if len(id) == 0 || len(id) > idWidth || id[0] == '0' {
		return "", false
	}
	for i := 0; i < len(id); i++ {
		if id[i] < '0' || id[i] > '9' {
			return "", false
		}
	}
	return "000000000000"[len(id):] + id, true
}

// idOf formats a sequential id.
func idOf(n int64) string {
	return strconv.FormatInt(n, 10)
}

// mustGet returns the stored record of id. Callers must not leak the pointer.
func mustGet(id string) *Villager {
	key, ok := keyOf(id)
	if !ok {
		panic("villagers: no such villager")
	}
	v := records.Get(key)
	if v == nil {
		panic("villagers: no such villager")
	}
	return v.(*Villager)
}

// assertNoSend rejects attached coins on functions that do not take payment;
// without it coins sent by mistake would be stuck in the realm.
func assertNoSend() {
	if len(unsafe.OriginSend()) != 0 {
		panic("villagers: this function takes no coins")
	}
}

package jointv1

import (
	"chain/runtime/unsafe"
	"time"
)

// Admin returns the admin address (the deployer).
func Admin() address {
	return admin.Owner()
}

// SetSecondsPerGameHour sets the real seconds per game hour (10 to 3600).
// Admin only. Game hours stay continuous: the clock is re-anchored at the
// current hour (old speed) before the new speed applies. Same value: no-op.
func SetSecondsPerGameHour(cur realm, s int64) {
	assertAdmin(cur)
	assertNoSend()
	if s < MinSecondsPerGameHour || s > MaxSecondsPerGameHour {
		panic("town: seconds per game hour must be 10 to 3600")
	}
	if s == params.SecondsPerGameHour {
		return
	}
	hourBase = CurrentGameHour() // at the old speed
	anchorUnix = time.Now().Unix()
	params.SecondsPerGameHour = s
}

// SetPotBps sets the share of GNOT shop sales that goes to the season pot,
// in basis points (0 to 10000). Admin only.
func SetPotBps(cur realm, bps int64) {
	assertAdmin(cur)
	assertNoSend()
	if bps < MinPotBps || bps > MaxPotBps {
		panic("town: pot bps must be 0 to 10000")
	}
	params.PotBps = bps
}

// SetPoolK sets the pool exponent step count (1 to 3: N^0.5, N^0.75,
// N^0.875). Admin only. It applies to every hour settled after the change,
// including missed hours not yet settled.
func SetPoolK(cur realm, k int) {
	assertAdmin(cur)
	assertNoSend()
	if k < MinPoolK || k > MaxPoolK {
		panic("town: pool k must be 1 to 3")
	}
