}

// SetTreasury sets the only address that may withdraw the GNOT treasury.
// Admin only. An empty address is refused.
func SetTreasury(cur realm, addr address) {
	assertAdmin(cur)
	assertNoSend()
	if addr == "" {
		panic("town: treasury address is empty")
	}
	treasuryAddr = addr
}

// SetPubPotBps sets the pubs' share of a frozen season pot, in basis points
// (4000 to 8000). Farms receive the rest. Admin only. It applies the next
// time a season is frozen.
func SetPubPotBps(cur realm, bps int64) {
	assertAdmin(cur)
	assertNoSend()
	if bps < MinPubPotBps || bps > MaxPubPotBps {
		panic("town: pub pot bps must be 4000 to 8000")
	}
	pubPotBps = bps
}

// SetPaused pauses or resumes all game actions. Reads keep working. Admin only.
func SetPaused(cur realm, p bool) {
	assertAdmin(cur)
	assertNoSend()
	params.Paused = p
}

func assertAdmin(cur realm) {
	if !admin.OwnedBy(cur.Previous().Address()) {
		panic("town: admin only")
	}
}

// assertNotPaused guards every game action.
func assertNotPaused() {
	if params.Paused {
		panic("town: game is paused")
	}
}

// assertNoSend rejects attached coins on functions that do not take payment;
// without it coins sent by mistake would be stuck in the realm.
func assertNoSend() {
	if len(unsafe.OriginSend()) != 0 {
		panic("town: this function takes no coins")
	}
}

package jointv1

import (
	"gno.land/p/nt/avl/v0"
	"gno.land/p/g17wg7tk6az05tz7vu6qfkvzau6p30aezuct3nt3/townmath"
	villagers "gno.land/r/g17wg7tk6az05tz7vu6qfkvzau6p30aezuct3nt3/villagersv1"
)

// Villager crews. A pub has up to MaxCrew villagers from the villagers realm
// in its crew (Tavern.Crew, "" = empty slot). The owner can buy a crew
// villager a round (RoundCostCg of the pub's gold, destroyed) or give it a
// day off (RestHours without a bonus). A happy or okay villager with
// loyalty of at least 5 brings extra customers in the evening (see
// crewBonus). A villager works for one pub at a time: crewHome maps it to the
// pub owner's address. A villager transferred to another wallet stays in the
// old crew but brings nothing (stale) until its old pub unassigns it or the
// new owner assigns it to their own pub, which clears the old slot.

const (
	// MaxCrew is the most villagers one pub can have in its crew.
	MaxCrew = 3
	// RestHours is how long a day off lasts: no bonus until then.
	RestHours int64 = 12
	// BonusSampleHour is the hour of day whose mood a settle uses for every
	// hour of that game day (clamped into the hours the settle credits).
	BonusSampleHour int64 = 20
)

// crewKeyWidth is the zero-padded width of crewHome keys (as in the
// villagers realm, so the tree orders villagers by id).
const crewKeyWidth = 12

var (
	// crewHome: zero-padded villager id -> the address string of the pub
	// owner whose crew it is in. About 2 KB of deposit per entry, paid by
	// the assigner and refunded when the entry is removed on unassign.
	crewHome avl.Tree
	// Cross-realm reads made by settlements (read-only counters for tests
	// and audits): villagers.GetVillager and villagers.OwnerOf calls.
	crewVillagerReads int64
	crewOwnerReads    int64
)

// AssignVillager puts one of the caller's villagers in the caller's pub
// crew. Pubs only. The caller must own the villager, the crew must have a
// free slot and the villager must not be in it already. A villager
// registered to another pub whose owner no longer owns it (it was
// transferred) is taken over: the old pub's slot is cleared. The pub is
// settled first, so the villager brings nothing for earlier hours. An own
// action (a dormant pub rejoins).
func AssignVillager(cur realm, id string) {
	actor := userActor(cur)
	assertNotPaused()
	t := mustTavern(actor.String())
	assertPub(t)
	owner := villagers.OwnerOf(id) // aborts for an unknown id
	if owner != actor {
		panic("town: not your villager")
	}
	if crewSlot(t, id) >= 0 {
		panic("town: already in the crew")
	}
	slot := freeSlot(t)
	if slot < 0 {
		panic("town: crew is full")
	}
	key := crewKey(id)
	var old *Tavern
	oldSlot := -1
	if v := crewHome.Get(key); v != nil {
		home := v.(string)
		if home != actor.String() {
			// The registered pub's owner keeps the villager only while it
			// owns it. The caller owns it now, so the registration is stale.
			if address(home) == owner {
				panic("town: villager works elsewhere")
			}
			if ov := taverns.Get(home); ov != nil {
				old = ov.(*Tavern)
				oldSlot = crewSlot(old, id)
			}
		}
	}
	settleTavern(t)
	ownerActs(t)
	if old != nil && oldSlot >= 0 {
		// The old pub gets no bonus from it anyway (not owned), so its
		// earnings do not change and it needs no settle.
		old.Crew[oldSlot] = ""
		old.CrewRestUntil[oldSlot] = 0
	}
	t.Crew[slot] = id
	t.CrewRestUntil[slot] = 0
	crewHome.Set(key, actor.String())
}

// UnassignVillager removes a villager from the caller's pub crew and drops
// its registration (the storage deposit is refunded). The villager need not
// be owned by the caller any more. Pubs only; an own action.
func UnassignVillager(cur realm, id string) {
	actor := userActor(cur)
	assertNotPaused()
	t := mustTavern(actor.String())
	assertPub(t)
	slot := crewSlot(t, id)
	if slot < 0 {
		panic("town: not in the crew")
	}
	settleTavern(t)
	ownerActs(t)
	t.Crew[slot] = ""
	t.CrewRestUntil[slot] = 0
	key := crewKey(id)
	if v := crewHome.Get(key); v != nil && v.(string) == actor.String() {
		crewHome.Remove(key)
	}
}

// BuyRound buys a crew villager a round: the pub pays RoundCostCg (the gold
// is destroyed) and the villager gets +4000 thirst and +1 loyalty (see the
// villagers realm). The villager must be in the caller's crew and still
// owned by the caller. Pubs only; an own action.
func BuyRound(cur realm, id string) {
	actor := userActor(cur)
	assertNotPaused()
	t := mustTavern(actor.String())
	assertPub(t)
	assertOwnCrew(t, actor, id)
	settleTavern(t)
	if t.GoldCg < townmath.RoundCostCg {
		panic("town: not enough gold")
	}
	ownerActs(t)
	cost := int64(townmath.RoundCostCg)
	t.GoldCg -= cost
	goldDestroyedCg += cost
	t.ProfitTodayCg -= cost
	t.SeasonProfitCg -= cost
	villagers.ApplyRound(cross(cur), id, CurrentGameHour())
}

// DayOff gives a crew villager a day off (free, DayOffCostCg): +5000 energy
// now, and no bonus for the next RestHours game hours. The villager must be
// in the caller's crew, owned by the caller and not resting. Pubs only; an
// own action.
func DayOff(cur realm, id string) {
	actor := userActor(cur)
	assertNotPaused()
	t := mustTavern(actor.String())
	assertPub(t)
	slot := assertOwnCrew(t, actor, id)
	now := CurrentGameHour()
	if now < t.CrewRestUntil[slot] {
		panic("town: already resting")
	}
	settleTavern(t)
	ownerActs(t)
	t.CrewRestUntil[slot] = now + RestHours
	villagers.ApplyDayOff(cross(cur), id, now)
}

// MintVillager mints a villager to `to` from seed at the current game hour.
// Admin only, for demos and tests; its id is villagers.Count() after the
// mint. The storage deposit of the new villager is paid by the signer.
func MintVillager(cur realm, to address, seed uint64) {
	assertAdmin(cur)
	if !cur.Previous().IsUserCall() {
		panic("town: must be a direct user call")
	}
	assertNoSend()
	assertNotPaused()
	villagers.MintFor(cross(cur), to, seed, CurrentGameHour())
}

// CrewOf returns a copy of the crew of owner's pub ("" = empty slot, all
// empty when owner has no business). Read-only.
func CrewOf(owner string) [MaxCrew]string {
	v := taverns.Get(owner)
	if v == nil {
		return [MaxCrew]string{}
	}
	return v.(*Tavern).Crew
}

// VillagerHome returns the address string of the pub owner whose crew the
// villager is registered to, or "". Read-only.
func VillagerHome(id string) string {
	if !canonicalID(id) {
		return ""
	}
	v := crewHome.Get(crewKey(id))
	if v == nil {
		return ""
	}
	return v.(string)
}

// CrewReads returns how many villagers.GetVillager and villagers.OwnerOf
// calls settlements have made in total. Read-only.
func CrewReads() (villagerReads, ownerReads int64) {
	return crewVillagerReads, crewOwnerReads
}

// assertOwnCrew aborts unless id is in t's crew and actor owns it; it
// returns the slot.
func assertOwnCrew(t *Tavern, actor address, id string) int {
	slot := crewSlot(t, id)
	if slot < 0 {
		panic("town: not in the crew")
	}
	if villagers.OwnerOf(id) != actor {
		panic("town: not your villager")
	}
	return slot
}

// crewSlot returns the slot of t's crew holding id, or -1 (always -1 for
// the empty id, which marks a free slot).
func crewSlot(t *Tavern, id string) int {
	if id == "" {
		return -1
	}
	for i := 0; i < MaxCrew; i++ {
		if t.Crew[i] == id {
			return i
		}
	}
	return -1
}

// freeSlot returns the first free slot of t's crew, or -1.
func freeSlot(t *Tavern) int {
	for i := 0; i < MaxCrew; i++ {
		if t.Crew[i] == "" {
			return i
		}
	}
	return -1
}

// canonicalID reports whether id is a villager id as the villagers realm
// writes them: 1..12 decimal digits, no leading zero.
func canonicalID(id string) bool {
	if len(id) == 0 || len(id) > crewKeyWidth || id[0] == '0' {
		return false
	}
	for i := 0; i < len(id); i++ {
		if id[i] < '0' || id[i] > '9' {
			return false
		}
	}
	return true
}

// crewKey is the crewHome key of a canonical id.
func crewKey(id string) string {
	return "000000000000"[len(id):] + id
}

// crewMember is what a settle reads once about one crew slot.
type crewMember struct {
	active  bool // in the crew and still owned by the pub owner
	restTo  int64
	loyalty int64
	needs   townmath.Needs
	mods    townmath.TraitMods
	needsAt int64
}

// loadCrew reads t's crew once for a settle: one villagers.OwnerOf per
// filled slot, and one villagers.GetVillager per villager the pub owner
// still owns (at most MaxCrew of each, none for an empty crew). It reports
// whether any member is active.
func loadCrew(t *Tavern, crew *[MaxCrew]crewMember) bool {
	found := false
	for i := 0; i < MaxCrew; i++ {
		id := t.Crew[i]
		if id == "" {
			continue
		}
		crewOwnerReads++
		if villagers.OwnerOf(id) != t.Owner {
			continue // transferred: stale, brings nothing
		}
		crewVillagerReads++
		v := villagers.GetVillager(id)
		crew[i] = crewMember{
			active:  true,
			restTo:  t.CrewRestUntil[i],
			loyalty: v.Loyalty,
			needs:   v.Needs,
			mods:    villagers.CombinedMods(v.Traits),
			needsAt: v.NeedsAt,
		}
		found = true
	}
	return found
}

// dayMoods sets each active member's mood for the game day whose credited
// hours are from..to: the mood at hour BonusSampleHour of that day, clamped
// into from..to.
func dayMoods(crew *[MaxCrew]crewMember, moods *[MaxCrew]int, day, from, to int64) {
	sample := day*24 + BonusSampleHour
	if sample < from {
		sample = from
	}
	if sample > to {
		sample = to
	}
	for i := 0; i < MaxCrew; i++ {
		m := crew[i]
		if !m.active {
			continue
		}
		moods[i] = townmath.Mood(townmath.Decay(m.needs, m.mods, sample-m.needsAt))
	}
}

// crewBonus is the extra customers t's active crew brings in game hour h:
// the sum of townmath.RegularBonus over members not resting at h.
func crewBonus(crew *[MaxCrew]crewMember, moods *[MaxCrew]int, h int64) int64 {
	hod := int(h % 24)
	sum := int64(0)
	for i := 0; i < MaxCrew; i++ {
		m := crew[i]
		if !m.active || h < m.restTo {
			continue
		}
		sum += townmath.RegularBonus(moods[i], m.loyalty, hod)
	}
	return sum
}

package jointv1

import "gno.land/p/g17wg7tk6az05tz7vu6qfkvzau6p30aezuct3nt3/townmath"

// Roles, farms and town stats.
//
// Pubs and farms share the taverns tree (one business per address). The
// town keeps pubCount, farmCount, totalWeight, totalPriceCg and
// totalPriceWeight up to date incrementally: every change to a pub's price,
// reputation, seats or barmaid calls reweigh, which applies only the deltas,
// and a pub enters or leaves the totals only through joinTotals and
// leaveTotals (idle.gno). RecountStats recomputes them from scratch so tests
// can prove they never drift.

// maxRecount bounds the businesses one RecountStats call visits.
const maxRecount = 2000

// Farm harvest constants (placeholders, tunable before the final deploy).
const (
	// FarmStorageCap is the most a farm stores of each good; harvest stops there.
	FarmStorageCap int64 = 120
	// FarmShortageYieldBps is a farm's yield on a shortage day (10000 otherwise).
	FarmShortageYieldBps int64 = 5000
	// DailyFarmScoreCap is the most a farm's season score can grow in one
	// game day. A tuned farm harvests more than this, so the cap bites.
	DailyFarmScoreCap int64 = 200
)

// CreateFarm opens a farm for the calling user. It uses the same checks, in
// the same order, as CreateTavern: one business (pub or farm) per address.
func CreateFarm(cur realm, name string) {
	prev := cur.Previous()
	// validate everything first; mutate only after
	if !prev.IsUserCall() {
		panic("town: CreateFarm must be a direct user call")
	}
	assertNotPaused()
	assertNoSend()
	validateName(name)
	owner := prev.Address()
	key := owner.String()
	assertNoBusiness(key)

	t := &Tavern{
		Owner:    owner,
		Name:     name,
		GoldCg:   params.StartGoldCg,
		Rep:      StartRep,
		LastHour: CurrentGameHour(),
		Role:     RoleFarm,
		Plots:    FarmStartPlots,
		ScoreGen: seasonGen,
	}
	t.Inv[GoodGrain] = FarmStartGrain
	taverns.Set(key, t)
	farmCount++
}

// TownStats returns the pub count, farm count, the sum of pub weights and
// the sum of pub prices (centigold). Dormant pubs are not counted. Read-only.
func TownStats() (pubs, farms, totalW, totalPrice int64) {
	return pubCount, farmCount, totalWeight, totalPriceCg
}

// RecountStats recomputes TownStats from the stored businesses, visiting at
// most limit of them (limit is clamped to 1..2000). Dormant pubs are not in
// the totals and are skipped. Read-only; with limit at or above the business
// count it must equal TownStats.
func RecountStats(limit int) (pubs, farms, totalW, totalPrice int64) {
	if limit < 1 {
		limit = 1
	}
	if limit > maxRecount {
		limit = maxRecount
	}
	taverns.IterateByOffset(0, limit, func(_ string, v any) bool {
		t := v.(*Tavern)
		if t.Role == RoleFarm {
			farms++
			return false
		}
		if t.Dormant != 0 {
			return false // not in the totals
		}
		pubs++
		totalW += pubWeight(t)
		totalPrice += t.PriceCg
		return false
	})
	return pubs, farms, totalW, totalPrice
}

// TownPriceWeight returns the sum of PriceCg * Weight over all pubs. The
// pool elasticity uses TownPriceWeight / total weight as the town's average
// price, so pubs with almost no weight barely move it. Read-only.
func TownPriceWeight() int64 {
	return totalPriceWeight
}

// RecountPriceWeight recomputes TownPriceWeight from the stored pubs that
// are not dormant, with weights recomputed from scratch, visiting at most limit businesses (clamped
// to 1..2000). Read-only; with limit at or above the business count it must
// equal TownPriceWeight.
func RecountPriceWeight(limit int) int64 {
	if limit < 1 {
		limit = 1
	}
	if limit > maxRecount {
		limit = maxRecount
	}
	sum := int64(0)
	taverns.IterateByOffset(0, limit, func(_ string, v any) bool {
		t := v.(*Tavern)
		if t.Role == RolePub && t.Dormant == 0 {
			sum += t.PriceCg * pubWeight(t)
		}
		return false
	})
	return sum
}

// GoldFlow returns all gold (centigold) the game has created (customer
// revenue, Town Farm purchases from farms) and destroyed (tax, hires, Town
// Farm sales to pubs). Start capital is not counted: the gold of all
// businesses is businesses * StartGoldCg + created - destroyed. Read-only.
func GoldFlow() (created, destroyed int64) {
	return goldCreatedCg, goldDestroyedCg
}

// BusinessCount returns the number of stored businesses: pubs (dormant or
// not) and farms. Read-only.
func BusinessCount() int {
	return taverns.Size()
}

// BusinessOwners returns up to count (clamped to 1..50) owner addresses of
// stored businesses from offset (at least 0), in the order the recounts
// visit them. Read-only.
func BusinessOwners(offset, count int) []string {
	if offset < 0 {
		offset = 0
	}
	if count < 1 {
		count = 1
	}
	if count > 50 {
		count = 50
	}
	out := make([]string, 0, count)
	taverns.IterateByOffset(offset, count, func(k string, _ any) bool {
		out = append(out, k)
		return false
	})
	return out
}

// RecountGold sums GoldCg over the stored businesses (pubs and farms),
// visiting at most limit of them (clamped to 1..2000). Read-only.
func RecountGold(limit int) int64 {
	if limit < 1 {
		limit = 1
	}
	if limit > maxRecount {
		limit = maxRecount
	}
	sum := int64(0)
	taverns.IterateByOffset(0, limit, func(_ string, v any) bool {
		sum += v.(*Tavern).GoldCg
		return false
	})
	return sum
}

// pubWeight is a pub's pull on the customer pool, measured against the fixed
// ReferencePriceCg. Ads are not counted yet (level 0).
func pubWeight(t *Tavern) int64 {
	staff := townmath.BpsOne
	if t.HasBarmaid {
		staff = BarmaidStaffBps
	}
	return townmath.PubWeight(townmath.WeightIn{
		PriceCg:  t.PriceCg,
		MarketCg: ReferencePriceCg,
		Rep:      t.Rep,
		Seats:    t.Seats,
		StaffBps: staff,
		AdBps:    townmath.AdWeightBps(0),
	})
}

// reweigh recomputes a pub's Weight and applies the deltas of weight, price
// and price x weight to the town totals. oldPriceCg is the price counted in totalPriceCg
// before the change (pass t.PriceCg when the price did not change). Call it
// after every change to price, reputation, seats or barmaid. It then records
// the totals in the snapshot ring for the current hour. A farm keeps Weight
// 0 and never touches the totals or the ring, and so does a dormant pub
// (it is not in the totals).
func reweigh(t *Tavern, oldPriceCg int64) {
	if t.Role != RolePub || t.Dormant != 0 {
		return
	}
	w := pubWeight(t)
	totalWeight += w - t.Weight
	totalPriceCg += t.PriceCg - oldPriceCg
	totalPriceWeight += t.PriceCg*w - oldPriceCg*t.Weight
	t.Weight = w
	writeSnapshot(CurrentGameHour()) // skipped when nothing changed
}

// SetCrop sets what the caller's farm grows: townmath.CropGrain (0) or
// townmath.CropHops (1). The farm is settled first, so the hours before the
// change harvest the old crop. Farms only.
func SetCrop(cur realm, crop int) {
	setCrop(userActor(cur), crop)
}

func setCrop(actor address, crop int) {
	assertNotPaused()
	if crop != townmath.CropGrain && crop != townmath.CropHops {
		panic("town: crop must be 0 (grain) or 1 (hops)")
	}
	t := mustTavern(actor.String())
	assertFarm(t)
	settleFarm(t)
	if t.Crop != int64(crop) {
		t.Carry = 0 // a fraction of the old crop is not the new crop
	}
	t.Crop = int64(crop)
}

// settleFarm applies the elapsed game hours to a farm, like settleTavern for
// a pub: a LastHour at or ahead of the clock credits nothing; otherwise the
// last at most 24 hours are split at day boundaries (at most 3 segments) and
// each segment harvests t.Crop with that day's yield (FarmShortageYieldBps on
// a shortage day), up to FarmStorageCap. The fraction of a unit carries in
// t.Carry (1/10000 units, 0..9999), so settling every hour makes the same
// crop as settling once a day. The harvest raises the town supply
// of the good. Harvested units (not gold) add to SeasonProd. At each day
// boundary ScoreDayStart becomes the score so far, and the score is
// CapGain of SeasonProd from that start, at most DailyFarmScoreCap, and
// never below the previous score. The result is submitted to the farm
// board only. LastHour moves to the current hour. Farms are not taxed and
// never touch the pub totals.
func settleFarm(t *Tavern) {
	ensureSeasonScore(t)
	ensureDaySeed()
	touchMarket()
	now := CurrentGameHour()
	last := t.LastHour
	if last >= now {
		return
	}
	hours := now - last
	if hours > townmath.MaxFarmCatchUpHours {
		hours = townmath.MaxFarmCatchUpHours
	}
	good := cropGood(t.Crop)
	h := now - hours + 1
	profitDay := last / 24
	// 24 hours span at most 2 game days; the bound is a safety net
	for i := 0; i < 3 && h <= now; i++ {
		day := h / 24
		end := day*24 + 23
		if end > now {
			end = now
		}
		if day != profitDay {
			t.ScoreDayStart = t.SeasonScore
			profitDay = day
		}
		yield := townmath.BpsOne
		if EventOnDay(day).Kind == townmath.EventShortage {
			yield = FarmShortageYieldBps
		}
		made, after, carry := townmath.HarvestCarry(t.Plots, int(t.Crop), end-h+1, t.Inv[good], FarmStorageCap, yield, t.Carry)
		t.Inv[good] = after
		t.Carry = carry
		raiseSupply(good, made)
		if made > 0 {
			t.SeasonProd += made
		}
		t.SeasonScore = NextFarmScore(t.SeasonScore, t.ScoreDayStart, t.SeasonProd)
		h = end + 1
	}
	t.LastHour = now
	submitFarmScore(t)
}

// NextFarmScore is a farm's season score from units harvested: CapGain of
// seasonProd above the score the day started with, at most DailyFarmScoreCap,
// and never below the previous score or 0.
func NextFarmScore(oldScore, dayStartScore, seasonProd int64) int64 {
	if oldScore < 0 {
		oldScore = 0
	}
	if dayStartScore < 0 {
		dayStartScore = 0
	}
	if dayStartScore > oldScore {
		dayStartScore = oldScore
	}
	if seasonProd < 0 {
		seasonProd = 0
	}
	s := townmath.CapGain(dayStartScore, seasonProd, DailyFarmScoreCap)
	if s < oldScore {
		return oldScore
	}
	return s
}

// cropGood is the inventory slot (and market good) a crop fills.
func cropGood(crop int64) int {
	if crop == townmath.CropHops {
		return GoodHops
	}
	return GoodGrain
}

// assertFarm aborts unless t is a farm.
func assertFarm(t *Tavern) {
	if t.Role != RoleFarm {
		panic("town: farms only")
	}
}

// assertPub aborts unless t is a pub.
func assertPub(t *Tavern) {
	if t.Role != RolePub {
		panic("town: joints only")
	}
}

// assertNoBusiness aborts if the address already has a pub or a farm.
func assertNoBusiness(key string) {
	if taverns.Has(key) {
		panic("town: address already has a joint or farm")
	}
}

package jointv1

// The idle pass. A pub whose owner has not acted for IdleAfterHours game
// hours still dilutes every other pub's share of the customer pool, so
// anyone may prune it: it is settled up to now (it was in the totals while
// it earned), then leaves the totals and becomes dormant. A dormant pub
// earns nothing; its gold, stock, score and leaderboard entry are kept. The
// owner's next own action rejoins it, with no credit for the dormant hours.

// IdleAfterHours is how many game hours without an own action make a pub
// prunable.
const IdleAfterHours int64 = 48

// Prune removes owner's idle pub from the town totals. Anyone may call it,
// including other realms. Pubs only; the pub must not be dormant already and
// its owner's last own action must be at least IdleAfterHours game hours ago.
func Prune(cur realm, owner string) {
	assertNoSend()
	assertNotPaused()
	t := mustTavern(owner)
	assertPub(t)
	if t.Dormant != 0 {
		panic("town: already dormant")
	}
	if CurrentGameHour()-t.LastActionHour < IdleAfterHours {
		panic("town: not idle")
	}
	settleTavern(t) // credits up to now at today's shares
	leaveTotals(t)
	t.Dormant = 1
	writeSnapshot(CurrentGameHour())
}

// joinTotals recomputes t's weight and adds the pub to the town totals.
func joinTotals(t *Tavern) {
	t.Weight = pubWeight(t)
	pubCount++
	totalWeight += t.Weight
	totalPriceCg += t.PriceCg
	totalPriceWeight += t.PriceCg * t.Weight
}

// leaveTotals removes the pub from the town totals with the exact values it
// added (its stored Weight and PriceCg, kept in the record).
func leaveTotals(t *Tavern) {
	pubCount--
	totalWeight -= t.Weight
	totalPriceCg -= t.PriceCg
	totalPriceWeight -= t.PriceCg * t.Weight
}

// settleDormant is what Settle does to a dormant pub (settleTavern leaves
// it unchanged): no hours, revenue, tax or reputation are credited; LastHour
// moves to now and a new game day starts the day's books (ProfitTodayCg 0,
// ScoreDayStart the current score), as a settle with no sales would.
func settleDormant(t *Tavern, now int64) {
	if t.LastHour >= now {
		return
	}
	if now/24 != t.LastHour/24 {
		t.ProfitTodayCg = 0
		t.ScoreDayStart = t.SeasonScore
	}
	t.LastHour = now
}

// ownerActs records an own action of a pub's owner. Call it after the
// settle and after every check of the action passed, before the action
// mutates: a dormant pub rejoins the totals first (LastHour moves to now
// without crediting the dormant hours), then LastActionHour moves.
func ownerActs(t *Tavern) {
	now := CurrentGameHour()
	if t.Dormant != 0 {
		settleDormant(t, now)
		joinTotals(t)
		t.Dormant = 0
		writeSnapshot(now)
	}
	t.LastActionHour = now
}

package jointv1

import (
	"gno.land/p/nt/avl/v0"
	"gno.land/p/g17wg7tk6az05tz7vu6qfkvzau6p30aezuct3nt3/townmath"
)

// Player listings. A farm puts grain or hops up for sale at its own price;
// the goods leave its inventory into the listing (escrow). Pubs buy any part
// of a listing: the buyer pays qty * PriceCg, the seller receives that minus
// a ListingFeeBps fee, and the fee is destroyed (counted in the gold flow).
// The Town Farm's prices, ramp and daily limits do not apply. A listing that
// sells out or is cancelled is removed from the tree, so its storage deposit
// is refunded.

// Listing bounds and fee.
const (
	MinListingPriceCg int64 = 50   // per unit
	MaxListingPriceCg int64 = 2000 // per unit
	MaxListingQty     int64 = 200
	MaxOpenListings   int64 = 5 // per seller
	ListingFeeBps     int64 = 500
	maxListingsPage         = 50
	listingIDWidth          = 12
)

// Listing is one open offer: Qty units of Good at PriceCg centigold each.
type Listing struct {
	ID      uint64
	Seller  address
	Good    int
	Qty     int64
	PriceCg int64
}

var (
	listings      avl.Tree // listingKey(ID) -> *Listing
	nextListingID uint64   // the last ID given out (IDs start at 1)
)

// ListGoods puts qty (1 to 200) units of grain or hops from the caller's
// farm up for sale at priceCg (50 to 2000) centigold per unit. Farms only,
// at most MaxOpenListings open listings per farm. The farm is settled first,
// so the harvest so far counts. Direct user call only.
func ListGoods(cur realm, good int, qty, priceCg int64) {
	listGoods(userActor(cur), good, qty, priceCg)
}

func listGoods(actor address, good int, qty, priceCg int64) {
	assertNotPaused()
	assertGood(good)
	if good != GoodGrain && good != GoodHops {
		panic("town: grain and hops only")
	}
	if qty < 1 || qty > MaxListingQty {
		panic("town: listing quantity must be 1 to 200")
	}
	if priceCg < MinListingPriceCg || priceCg > MaxListingPriceCg {
		panic("town: listing price must be 50 to 2000 centigold")
	}
	t := mustTavern(actor.String())
	assertFarm(t)
	if t.OpenListings >= MaxOpenListings {
		panic("town: at most 5 open listings")
	}
	if nextListingID >= 999999999999 {
		panic("town: no listing ids left")
	}
	settleFarm(t)
	if t.Inv[good] < qty {
		panic("town: not enough stock")
	}
	nextListingID++
	listings.Set(listingKey(nextListingID), &Listing{
		ID:      nextListingID,
		Seller:  actor,
		Good:    good,
		Qty:     qty,
		PriceCg: priceCg,
	})
	t.Inv[good] -= qty
	t.OpenListings++
}

// BuyListing buys qty units (1 to what remains) of listing id. Pubs only.
// The buyer pays qty * PriceCg; the seller receives it minus the
// ListingFeeBps fee, which is destroyed. A listing that reaches 0 is
// removed. Direct user call only.
func BuyListing(cur realm, id uint64, qty int64) {
	buyListing(userActor(cur), id, qty)
}

func buyListing(actor address, id uint64, qty int64) {
	assertNotPaused()
	l := mustListing(id)
	t := mustTavern(actor.String())
	assertPub(t)
	if l.Seller == actor {
		panic("town: cannot buy your own listing")
	}
	if qty < 1 || qty > l.Qty {
		panic("town: quantity must be 1 to what the listing has left")
	}
	seller := mustTavern(l.Seller.String())
	settleTavern(t)
	if t.Inv[l.Good]+qty > MaxInv {
		panic("town: inventory full (max 1000 per good)")
	}
	total := qty * l.PriceCg // at most 200 * 2000
	if total > t.GoldCg {
		panic("town: not enough gold")
	}
	ownerActs(t)
	fee := townmath.MulBps(total, ListingFeeBps)
	t.GoldCg -= total
	t.ProfitTodayCg -= total
	t.SeasonProfitCg -= total
	seller.GoldCg += total - fee
	goldDestroyedCg += fee
	t.Inv[l.Good] += qty
	l.Qty -= qty
	if l.Qty == 0 {
		listings.Remove(listingKey(id))
		seller.OpenListings--
	}
}

// CancelListing closes the caller's listing id and returns what is left of
// it to the farm's inventory (aborts if that would pass FarmStorageCap). The
// farm is settled first. Seller only. Direct user call only.
func CancelListing(cur realm, id uint64) {
	cancelListing(userActor(cur), id)
}

func cancelListing(actor address, id uint64) {
	assertNotPaused()
	l := mustListing(id)
	if l.Seller != actor {
		panic("town: not your listing")
	}
	t := mustTavern(actor.String())
	settleFarm(t)
	// escrow comes back only within the farm's storage cap, so listing and
	// cancelling never stores more than a harvest could
	if t.Inv[l.Good]+l.Qty > FarmStorageCap {
		panic("town: inventory full (a farm stores at most 120 per good)")
	}
	t.Inv[l.Good] += l.Qty
	t.OpenListings--
	listings.Remove(listingKey(id))
}

// Listings returns up to count (clamped to 1..50) open listings from offset
// (at least 0), ordered by ID. Read-only.
func Listings(offset, count int) []Listing {
	if offset < 0 {
		offset = 0
	}
	if count < 1 {
		count = 1
	}
	if count > maxListingsPage {
		count = maxListingsPage
	}
	out := make([]Listing, 0, count)
	listings.IterateByOffset(offset, count, func(_ string, v any) bool {
		out = append(out, *(v.(*Listing)))
		return false
	})
	return out
}

// GetListing returns a copy of listing id and whether it is open. Read-only.
func GetListing(id uint64) (Listing, bool) {
	v := listings.Get(listingKey(id))
	if v == nil {
		return Listing{}, false
	}
	return *(v.(*Listing)), true
}

// ListingCount returns the number of open listings. Read-only.
func ListingCount() int {
	return listings.Size()
}

// OpenListings returns the number of open listings of seller (0 for an
// address with no business). Read-only.
func OpenListings(seller string) int {
	v := taverns.Get(seller)
	if v == nil {
		return 0
	}
	return int(v.(*Tavern).OpenListings)
}

// mustListing returns the stored listing id (a pointer into state).
func mustListing(id uint64) *Listing {
	v := listings.Get(listingKey(id))
	if v == nil {
		panic("town: no such listing")
	}
	return v.(*Listing)
}

// listingKey is id in decimal, zero-padded to 12 digits, so the tree orders
// keys by ID.
func listingKey(id uint64) string {
	var b [listingIDWidth]byte
	for i := listingIDWidth - 1; i >= 0; i-- {
		b[i] = byte('0' + id%10)
		id /= 10
	}
	return string(b[:])
}

package jointv1

import "gno.land/p/g17wg7tk6az05tz7vu6qfkvzau6p30aezuct3nt3/townmath"

// Town market: one supply counter per good. Prices come from the supply
// level (townmath.PriceFromSupply). Buying from the town draws its supply
// down, which raises the price; harvests and sales to the town raise it;
// every touch drifts supply back toward half the target
// (townmath.DriftSupply, at most 48 hours per touch).
//
// The Town Farm is the realm's own trader. Pubs buy from it at a price that
// starts at TownFarmSellBps of the market price and ramps up to
// TownFarmSellMaxBps as that pub itself buys more that day (no global cap
// and no shared ramp: nobody can lock others out or make them pay more). Farms
// sell grain and hops to it at TownFarmBuyBps within a hard daily town
// limit. Both directions have a daily limit per business. A trade over a
// limit is refused whole (all or nothing).

// Bounds for town purchases and inventory.
const (
	MinBuyQty int64 = 1
	MaxBuyQty int64 = 100
	MaxInv    int64 = 1000 // per good, per tavern
	numGoods        = 4
)

// Town Farm prices and daily limits (placeholders, tunable before the final
// deploy). The bps are fixed here and never taken from a caller.
const (
	// pubs pay 130% of the market price before the town bought anything today
	TownFarmSellBps int64 = 13000
	// the most pubs pay: 200% of the market price
	TownFarmSellMaxBps int64 = 20000
	// units a pub buys in a game day before its own price reaches
	// TownFarmSellMaxBps (half of it on a shortage day: the price climbs
	// faster); the same as the pub's daily allowance
	TownFarmSellRampUnits int64 = 120
	// farms get 70% of the market price
	TownFarmBuyBps int64 = 7000
	// units the Town Farm buys from farms per game day (a hard town limit)
	TownFarmDailyBuyGlobal int64 = 600
	// units one farm may sell to the Town Farm per game day
	TownFarmDailyPerPlayer int64 = 60
	// units one pub may buy from the Town Farm per game day (grain and hops
	// together; a pub needs about 70 to 110 grain a day)
	TownFarmDailyBuyPerPlayer int64 = 120
)

var (
	goodBaseCg = [numGoods]int64{600, 200, 350, 1100}   // ale, grain, hops, mead
	goodTarget = [numGoods]int64{2000, 3000, 1500, 800} // supply target
	townSupply = [numGoods]int64{1000, 1500, 750, 400}  // starts at target/2 (neutral)
	marketHour int64                                    // game hour of the last stored drift
)

// GoodBaseCg returns the base centigold price of good, the price at a
// neutral supply (goodBaseCg). Read-only. Aborts for an unknown good.
func GoodBaseCg(good int) int64 {
	assertGood(good)
	return goodBaseCg[good]
}

// GoodPriceCg returns the current town market price of one unit of good in
// centigold, from the supply alone (a shortage cuts farm yield and the Town
// Farm's sales instead; the price rises because supply falls). Read-only.
func GoodPriceCg(good int) int64 {
	assertGood(good)
	return townmath.PriceFromSupply(goodBaseCg[good], townmath.SupplyBps(supplyNow(good), goodTarget[good]))
}

// MarketSupply returns the current town supply counter of good, including
// drift since the last touch. Read-only.
func MarketSupply(good int) int64 {
	assertGood(good)
	return supplyNow(good)
}

// BuyGood buys qty (1 to 100) units of good from the Town Farm for
// qty * townmath.TownFarmSellCg(GoodPriceCg(good), bps) gold, where bps is
// TownFarmSellBpsAt of the units this pub bought today before the order (the
// whole order pays the price at the start of the order). Pubs only, at most
// TownFarmDailyBuyPerPlayer units a day per pub. Grain and hops only (ale is brewed, mead is not sold).
// Direct user call only.
func BuyGood(cur realm, good int, qty int64) {
	buyGood(userActor(cur), good, qty)
}

// buyGood is the game rule behind BuyGood, for the caller actor.
func buyGood(actor address, good int, qty int64) {
	assertNotPaused()
	assertGood(good)
	if good != GoodGrain && good != GoodHops {
		panic("town: grain and hops only")
	}
	assertQty(qty)
	t := mustTavern(actor.String())
	assertPub(t)
	settleTavern(t)
	if t.Inv[good]+qty > MaxInv {
		panic("town: inventory full (max 1000 per good)")
	}
	day := CurrentGameHour() / 24
	used := playerTFUsed(t, day, t.TFBought)
	assertPlayerRoom(qty, used, TownFarmDailyBuyPerPlayer)
	// the whole order pays one unit price, from what this pub bought before
	// it today (all or nothing); the order itself then moves its ramp
	bps := TownFarmSellBpsAt(used, EventOnDay(day).Kind == townmath.EventShortage)
	cost := qty * townmath.TownFarmSellCg(GoodPriceCg(good), bps)
	if cost > t.GoldCg {
		panic("town: not enough gold")
	}
	ownerActs(t)
	rollTownFarmDay(t, day)
	t.GoldCg -= cost
	goldDestroyedCg += cost
	t.ProfitTodayCg -= cost
	t.SeasonProfitCg -= cost
	t.Inv[good] += qty
	t.TFBought += qty
	tfSoldGlobal += qty
	townSupply[good] -= qty
	if townSupply[good] < 0 {
		townSupply[good] = 0
	}
}

// SellGood sells qty (1 to 100) units of grain or hops from the caller's
// farm to the Town Farm for qty * townmath.TownFarmBuyCg(GoodPriceCg(good),
// TownFarmBuyBps) gold. Farms only, within the daily limits
// (TownFarmDailyPerPlayer for the farm, TownFarmDailyBuyGlobal for the
// town). The farm is settled first, so the stock includes the harvest so
// far. Direct user call only.
func SellGood(cur realm, good int, qty int64) {
	sellGood(userActor(cur), good, qty)
}

// sellGood is the game rule behind SellGood, for the caller actor.
func sellGood(actor address, good int, qty int64) {
	assertNotPaused()
	assertGood(good)
	if good != GoodGrain && good != GoodHops {
		panic("town: the town farm buys only grain and hops")
	}
	assertQty(qty)
	t := mustTavern(actor.String())
	assertFarm(t)
	settleFarm(t)
	if t.Inv[good] < qty {
		panic("town: not enough stock")
	}
	day := CurrentGameHour() / 24
	_, _, boughtToday := TownFarmToday()
	assertPlayerRoom(qty, playerTFUsed(t, day, t.TFSold), TownFarmDailyPerPlayer)
	if townmath.Capped(qty, TownFarmDailyBuyGlobal, boughtToday) < qty {
		panic("town: town farm limit reached")
	}
	pay := qty * townmath.TownFarmBuyCg(GoodPriceCg(good), TownFarmBuyBps)
	rollTownFarmDay(t, day)
	t.GoldCg += pay
	goldCreatedCg += pay
	t.Inv[good] -= qty
	t.TFSold += qty
	tfBoughtGlobal += qty
	raiseSupply(good, qty)
}

// TownFarmToday returns the current game day and the units the Town Farm
// sold to pubs and bought from farms on it (0 and 0 before the day's first
// trade). Read-only.
func TownFarmToday() (day, soldGlobal, boughtGlobal int64) {
	day = CurrentGameHour() / 24
	if tfDay != day {
		return day, 0, 0
	}
	return day, tfSoldGlobal, tfBoughtGlobal
}

// playerTFUsed is used (TFSold or TFBought of t) if t's counters are of day,
// else 0.
func playerTFUsed(t *Tavern, day, used int64) int64 {
	if t.TFDay != day {
		return 0
	}
	return used
}

// assertPlayerRoom aborts unless all of qty fits the player's daily limit
// (used so far today).
func assertPlayerRoom(qty, used, limit int64) {
	if townmath.Capped(qty, limit, used) < qty {
		panic("town: town farm limit reached")
	}
}

// TownFarmSellBpsAt is the Town Farm's sell price in bps of the market price
// for a pub that bought used units from it today: TownFarmSellBps +
// (TownFarmSellMaxBps - TownFarmSellBps) * min(used, ramp) / ramp, where ramp
// is TownFarmSellRampUnits, halved on a shortage day. Never above
// TownFarmSellMaxBps; a negative used counts as 0. Pure.
func TownFarmSellBpsAt(used int64, shortage bool) int64 {
	ramp := TownFarmSellRampUnits
	if shortage {
		ramp /= 2
	}
	if used < 0 {
		used = 0
	}
	if used > ramp {
		used = ramp
	}
	return TownFarmSellBps + (TownFarmSellMaxBps-TownFarmSellBps)*used/ramp
}

// TownFarmSellBpsFor is the sell price (bps of the market price) the pub of
// owner would pay for its next order now: TownFarmSellBpsAt of its own units
// bought today and today's event. 13000 for an owner with no business or no
// buys today. It uses the last stored event of today (a settle stores it).
// Read-only.
func TownFarmSellBpsFor(owner string) int64 {
	day := CurrentGameHour() / 24
	used := int64(0)
	if t := GetTavern(owner); t != nil {
		used = playerTFUsed(t, day, t.TFBought)
	}
	return TownFarmSellBpsAt(used, EventOnDay(day).Kind == townmath.EventShortage)
}

// rollTownFarmDay resets the player's and the town's Town Farm counters if
// they are of another day than day. Call it only after every check passed.
func rollTownFarmDay(t *Tavern, day int64) {
	if t.TFDay != day {
		t.TFDay = day
		t.TFSold = 0
		t.TFBought = 0
	}
	if tfDay != day {
		tfDay = day
		tfSoldGlobal = 0
		tfBoughtGlobal = 0
	}
}

func assertQty(qty int64) {
	if qty < MinBuyQty || qty > MaxBuyQty {
		panic("town: quantity must be 1 to 100")
	}
}

// raiseSupply adds n units to the town supply of good, never above the
// good's target. Call it after touchMarket so the drift is stored first.
func raiseSupply(good int, n int64) {
	if n <= 0 {
		return
	}
	s := townSupply[good] + n // both bounded (n <= 100 or a harvest), no wrap
	if s > goodTarget[good] {
		s = goodTarget[good]
	}
	townSupply[good] = s
}

func assertGood(good int) {
	if good < 0 || good >= numGoods {
		panic("town: unknown good")
	}
}

// supplyNow is the stored supply drifted to the current hour (not stored).
func supplyNow(good int) int64 {
	d := CurrentGameHour() - marketHour
	if d <= 0 {
		return townSupply[good]
	}
	return townmath.DriftSupply(townSupply[good], goodTarget[good], d)
}

// touchMarket stores the drift up to the current hour. A clock behind the
// last touch changes nothing.
func touchMarket() {
	now := CurrentGameHour()
	d := now - marketHour
	if d <= 0 {
		return
	}
	for g := 0; g < numGoods; g++ {
		townSupply[g] = townmath.DriftSupply(townSupply[g], goodTarget[g], d)
	}
	marketHour = now
}

package jointv1

import (
	"strings"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/p/g17wg7tk6az05tz7vu6qfkvzau6p30aezuct3nt3/townmath"
	villagers "gno.land/r/g17wg7tk6az05tz7vu6qfkvzau6p30aezuct3nt3/villagersv1"
)

// Town-needs bands. Wide on purpose: a small price move must not flip the
// board. Grain and hops only. Render never stores a smoothed value.
const (
	bandSteady = 0
	bandScarce = 1
	bandPlenty = 2

	scarceBps = 13000
	plentyBps = 8000
	pageSize  = 10
)

// renderRoot is this realm's gnoweb path. Render builds links from it so a
// click stays inside the package. scripts/setns.sh rewrites the prefix.
const renderRoot = "/r/g17wg7tk6az05tz7vu6qfkvzau6p30aezuct3nt3/jointv1"

// Render is the gnoweb view of the town. It is not a crossing function and
// it only reads: no settle, no coins, no stored write. A path it does not
// know returns a short help page, never a panic and never an empty string.
func Render(path string) string {
	if strings.HasPrefix(path, "api/") {
		return renderAPI(path[len("api/"):])
	}
	base, page := parsePage(path)
	switch {
	case path == "" || path == "/":
		return renderHome()
	case path == "needs":
		return renderNeedsPage()
	case base == "market":
		return renderMarket(path, page)
	case strings.HasPrefix(path, "tavern/"):
		return renderBusiness(path[len("tavern/"):])
	case strings.HasPrefix(path, "business/"):
		return renderBusiness(path[len("business/"):])
	case strings.HasPrefix(path, "villager/"):
		return renderVillager(path[len("villager/"):])
	default:
		return renderHelp()
	}
}

func renderHelp() string {
	return "# The Joint\n\n" +
		"Pages: home, needs, market, market?page=N, tavern/<address>, business/<address>, villager/<id>.\n" +
		"JSON: api/town, api/tavern/<address>, api/villager/<id>, api/villagers/<offset>/<count>, api/crew/<address>, api/listings/<offset>/<count>, api/top, api/topfarms, api/season.\n"
}

func renderHome() string {
	h := CurrentGameHour()
	s := "# The Joint\n\n"
	s += ufmt.Sprintf("Day %d, hour %d. Today: %s.\n\n", h/24, h%24, eventKindName(EventOnDay(h/24).Kind))
	s += "## Market\n\n"
	for g := GoodAle; g <= GoodMead; g++ {
		s += ufmt.Sprintf("- %s: %d cg, supply %d\n", goodLabel(g), GoodPriceCg(g), MarketSupply(g))
	}
	s += "\n" + renderNeedsBody()
	s += "\n" + renderBoard("Top joints", Top())
	s += "\n" + renderBoard("Top farms", TopFarms())
	season := GetSeason()
	state := "open"
	if season.Frozen {
		state = "frozen"
	}
	s += ufmt.Sprintf("\n## Season\n\nSeason %d, %s, ends %d, pot %d ugnot, joint share %d bps.\n\n",
		season.Number, state, season.EndsAt, PotNow(), PubPotBps())
	s += "[Market](" + renderRoot + ":market)\n\n[Town needs](" + renderRoot + ":needs)\n\nIncome is not promised.\n"
	return s
}

func renderBoard(title string, rows []townmath.Entry) string {
	s := "## " + title + "\n\n"
	if len(rows) == 0 {
		s += "None yet.\n"
		return s
	}
	s += "| rank | owner | score |\n| --- | --- | --- |\n"
	n := len(rows)
	if n > TopN {
		n = TopN
	}
	for i := 0; i < n; i++ {
		s += ufmt.Sprintf("| %d | %s | %d |\n", i+1, rows[i].Owner, rows[i].Score)
	}
	return s
}

func renderNeedsPage() string {
	return "# Town needs\n\n" + renderNeedsBody()
}

func renderNeedsBody() string {
	pubs, farms, _, _ := TownStats()
	s := "## Town needs\n\n"
	s += ufmt.Sprintf("Joints: %d. Farms: %d.\n", pubs, farms)
	for _, g := range []int{GoodGrain, GoodHops} {
		s += ufmt.Sprintf("%s price %d cg, supply %d.\n", titleGood(g), GoodPriceCg(g), MarketSupply(g))
	}
	return s + needsMessage()
}

// needsMessage is the headline and one supporting sentence. The strongest
// scarce good (grain or hops) wins; otherwise plenty says farms can ease;
// otherwise the town looks steady.
func needsMessage() string {
	gb, gr := needBand(GoodGrain)
	hb, hr := needBand(GoodHops)
	if gb == bandScarce || hb == bandScarce {
		pick := GoodGrain
		if hb == bandScarce && (gb != bandScarce || hr > gr) {
			pick = GoodHops
		}
		return titleGood(pick) + " is scarce.\nFarms are needed.\n"
	}
	if gb == bandPlenty || hb == bandPlenty {
		return "Farms can ease.\nSupply is ahead of the town.\n"
	}
	return "Town supply looks steady.\nPrices sit in a wide band.\n"
}

// needBand classifies good. rank is higher when the price is further above
// its base, then when supply is lower, so two scarce goods can be ordered.
func needBand(good int) (band int, rank int64) {
	price := GoodPriceCg(good)
	base := GoodBaseCg(good)
	supply := MarketSupply(good)
	pubs, _, _, _ := TownStats()
	if base > 0 {
		rank = price * 10000 / base
	} else {
		rank = price
	}
	rank = rank*100000 - supply
	switch {
	case price >= townmath.MulBps(base, scarceBps) || (pubs > 0 && supply < pubs*24):
		band = bandScarce
	case price <= townmath.MulBps(base, plentyBps) && (pubs == 0 || supply > pubs*96):
		band = bandPlenty
	default:
		band = bandSteady
	}
	return band, rank
}

func renderMarket(path string, page int) string {
	s := "# Market\n\n"
	if note := pageNote(path); note != "" {
		s += note + "\n\n"
	}
	total := ListingCount()
	if total == 0 {
		if page <= 1 {
			s += "No listings yet.\n"
		} else {
			s += "No more listings.\n"
		}
		return s
	}
	offset := (page - 1) * pageSize
	if offset < 0 || offset >= total {
		s += "No more listings.\n"
		if page > 1 {
			s += ufmt.Sprintf("[Prev](%s:market?page=%d)\n", renderRoot, page-1)
		}
		return s
	}
	rows := Listings(offset, pageSize)
	s += "| id | seller | good | qty | priceCg |\n| --- | --- | --- | --- | --- |\n"
	for i := 0; i < len(rows); i++ {
		l := rows[i]
		s += ufmt.Sprintf("| %d | %s | %s | %d | %d |\n",
			l.ID, l.Seller.String(), goodLabel(l.Good), l.Qty, l.PriceCg)
	}
	if page > 1 {
		s += ufmt.Sprintf("[Prev](%s:market?page=%d)\n", renderRoot, page-1)
	}
	if offset+len(rows) < total {
		s += ufmt.Sprintf("[Next](%s:market?page=%d)\n", renderRoot, page+1)
	}
	return s
}

func renderBusiness(addr string) string {
	if addr == "" {
		return "No joint at this address.\n"
	}
	t := GetTavern(addr)
	if t == nil {
		return "No joint at this address.\n"
	}
	role := "joint"
	if t.Role == RoleFarm {
		role = "farm"
	}
	s := "# " + escapeMD(t.Name) + "\n\n"
	s += ufmt.Sprintf("Owner: %s\nRole: %s\nGold: %d cg\nStock: %d\n", t.Owner.String(), role, t.GoldCg, t.Stock)
	s += ufmt.Sprintf("Inventory: ale %d, grain %d, hops %d, mead %d\n",
		t.Inv[GoodAle], t.Inv[GoodGrain], t.Inv[GoodHops], t.Inv[GoodMead])
	s += ufmt.Sprintf("Price: %d cg\nReputation: %d\n", t.PriceCg, t.Rep)
	if t.Role == RolePub {
		s += ufmt.Sprintf("seats: %d\n", t.Seats)
		s += "Crew:"
		found := false
		crew := CrewOf(addr)
		for i := 0; i < MaxCrew; i++ {
			if crew[i] != "" {
				s += " " + crew[i]
				found = true
			}
		}
		if !found {
			s += " none"
		}
		s += "\n"
	} else {
		s += ufmt.Sprintf("plots: %d\ncrop: %s\n", t.Plots, cropLabel(t.Crop))
	}
	dorm := "no"
	if t.Dormant != 0 {
		dorm = "yes"
	}
	s += ufmt.Sprintf("dormant: %s\nSeason score: %d\nSeason production: %d\n", dorm, t.SeasonScore, t.SeasonProd)
	return s
}

func renderVillager(id string) string {
	if !knownVillager(id) {
		return "No such villager.\n"
	}
	v := villagers.GetVillager(id)
	hour := CurrentGameHour()
	needs := villagers.NeedsNow(id, hour)
	s := "# Villager " + id + "\n\n"
	s += ufmt.Sprintf("Owner: %s\nJob: %s\nloyalty: %d\n", villagers.OwnerOf(id).String(), jobName(v.Job), v.Loyalty)
	s += ufmt.Sprintf("Traits: %s, %s\n", villagers.TraitName(v.Traits[0]), villagers.TraitName(v.Traits[1]))
	s += ufmt.Sprintf("Needs: thirst %d, fun %d, energy %d\nmood: %s\n",
		needs.Thirst, needs.Fun, needs.Energy, moodName(villagers.MoodNow(id, hour)))
	return s
}

// knownVillager reports whether id is a minted villager without calling
// GetVillager, which aborts for an unknown id.
func knownVillager(id string) bool {
	if len(id) == 0 || len(id) > 12 || id[0] == '0' {
		return false
	}
	n := int64(0)
	for i := 0; i < len(id); i++ {
		if id[i] < '0' || id[i] > '9' {
			return false
		}
		n = n*10 + int64(id[i]-'0')
	}
	return n >= 1 && n <= int64(villagers.Count())
}

// parsePage splits an optional ?page= query. A missing page, page=0, a
// negative page or a non-numeric page is page 1. The base is the path
// before '?'.
func parsePage(path string) (base string, page int) {
	page = 1
	q := strings.IndexByte(path, '?')
	if q < 0 {
		return path, 1
	}
	base = path[:q]
	n, ok := pageNumber(path[q+1:])
	if !ok || n < 1 {
		return base, 1
	}
	if n > 1000000 {
		n = 1000000
	}
	return base, n
}

// pageNote is the one-line warning for a negative or non-numeric page.
// page=0 and a missing page are silent (they are page 1).
func pageNote(path string) string {
	q := strings.IndexByte(path, '?')
	if q < 0 {
		return ""
	}
	raw, present := pageRaw(path[q+1:])
	if !present || raw == "0" {
		return ""
	}
	if raw == "" || raw[0] == '-' {
		return "Invalid page; showing page 1."
	}
	for i := 0; i < len(raw); i++ {
		if raw[i] < '0' || raw[i] > '9' {
			return "Invalid page; showing page 1."
		}
	}
	return ""
}

func pageNumber(q string) (int, bool) {
	raw, ok := pageRaw(q)
	if !ok || raw == "" || raw[0] == '-' {
		return 0, false
	}
	n := 0
	for i := 0; i < len(raw); i++ {
		if raw[i] < '0' || raw[i] > '9' {
			return 0, false
		}
		// A longer number than the cap is past the last page, not invalid.
		if n > 100000 {
			return 1000000, true
		}
		n = n*10 + int(raw[i]-'0')
	}
	if n > 1000000 {
		return 1000000, true
	}
	return n, true
}

func pageRaw(q string) (string, bool) {
	i := strings.Index(q, "page=")
	if i < 0 {
		return "", false
	}
	v := q[i+len("page="):]
	if a := strings.IndexByte(v, '&'); a >= 0 {
		v = v[:a]
	}
	return v, true
}

// escapeMD strips Markdown control characters from player text so a name
// cannot inject a link, emphasis, or an angle-bracket autolink.
func escapeMD(s string) string {
	out := make([]byte, 0, len(s))
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '`', '*', '_', '[', ']', '(', ')', '#', '!', '<', '>':
		default:
			out = append(out, s[i])
		}
	}
	return string(out)
}

