// uint64ToDec writes n in decimal without strconv.FormatUint (not in the
// Gno common subset we rely on).
func uint64ToDec(n uint64) string {
	if n == 0 {
		return "0"
	}
	var buf [20]byte
	i := len(buf)
	for n > 0 {
		i--
		buf[i] = byte('0' + n%10)
		n /= 10
	}
	return string(buf[i:])
}

