// renderAPI dispatches api/* paths. path is the part AFTER the "api/" prefix.
func renderAPI(path string) string {
	switch {
	case path == "town":
		return apiTown()
	case path == "top":
		return apiTop(false)
	case path == "topfarms":
		return apiTop(true)
	case path == "season":
