func parseTwoInts(rest string) (off, count int, ok bool) {
	parts := strings.Split(rest, "/")
	if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
		return 0, 0, false
	}
	o, err1 := strconv.Atoi(parts[0])
	c, err2 := strconv.Atoi(parts[1])
	if err1 != nil || err2 != nil {
		return 0, 0, false
	}
	return o, c, true
}

func jsonBool(v bool) string {
	if v {
		return "true"
	}
	return "false"
}

// jsonString returns a JSON string literal with quotes, escaping \, ", and
// control characters. Names are printable ASCII but may contain " and \.
func jsonString(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case '"', '\\':
			b.WriteByte('\\')
			b.WriteByte(c)
		case '\n':
			b.WriteString(`\n`)
		case '\r':
			b.WriteString(`\r`)
		case '\t':
			b.WriteString(`\t`)
		default:
			if c < 0x20 {
				b.WriteString(`\u00`)
				const hex = "0123456789abcdef"
				b.WriteByte(hex[c>>4])
				b.WriteByte(hex[c&0xf])
			} else {
				b.WriteByte(c)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}

package jointv1

import "gno.land/p/g17wg7tk6az05tz7vu6qfkvzau6p30aezuct3nt3/townmath"

// Shared customer pool and the hourly snapshot ring.
//
// Every game hour the town has one pool of customers (townmath.
// PoolCustomersMilli for the pub count), scaled by the price factor of the
// town's weight-weighted average price against ReferencePriceCg (all pubs
// dearer: fewer customers; a pub with almost no weight barely moves it) and by the day's event, and split among pubs by weight. A pub
// settles lazily, so for each hour it missed it needs the town totals of that
// hour: the ring keeps one snapshot per hour of the last 24, written whenever
// the totals change and by every settle for its own hour (a settle that
// credits hours reads the ring with that write applied, and stores the slot
// once, after its reweigh). An hour nobody wrote uses the last known
// snapshot before it.

// maxPoolScaleClamp is the scale clamp of townmath.PoolCustomersMilli.
const maxPoolScaleClamp int64 = 100000

// ringSize is the number of hourly snapshots kept (one game day).
const ringSize = 24

// Pool parameter bounds (see docs/spikes/pool-sim.md).
const (
	MinPoolK        = 1
	MaxPoolK        = 3
	MinPoolScaleBps = 5000
	MaxPoolScaleBps = 30000
)

// snapshot is the town totals at the end of a game hour. Set tells an
// empty slot from hour 0.
type snapshot struct {
	Hour, Pubs, TotalWeight, TotalPriceWeight int64
	Set                                       bool
}

var (
	ring           [ringSize]snapshot // slot hour % ringSize
	snapshotWrites int64              // stored ring writes (skipped writes not counted)
	poolK          int   = townmath.PoolExponentK
	poolScaleBps   int64 = townmath.PoolScaleBps
)

// currentSnapshot returns the town totals now.
func currentSnapshot(hour int64) snapshot {
	return snapshot{Hour: hour, Pubs: pubCount, TotalWeight: totalWeight, TotalPriceWeight: totalPriceWeight, Set: true}
}

// writeSnapshot stores the current totals in the slot of hour. It skips the
// write when the slot already holds exactly these values for this hour (an
// unchanged write still costs gas), and never replaces a newer hour (block
// time behind the slot).
func writeSnapshot(hour int64) {
	if hour < 0 {
		return
	}
	i := hour % ringSize
	s := ring[i]
	if s.Set && s.Hour > hour {
		return
	}
	if s.Set && s.Hour == hour && s.Pubs == pubCount && s.TotalWeight == totalWeight && s.TotalPriceWeight == totalPriceWeight {
		return
	}
	ring[i] = currentSnapshot(hour)
	snapshotWrites++
}

// snapshotFor returns the snapshot written for exactly hour in rg (a copy
// of the ring), else fallback.
func snapshotFor(rg *[ringSize]snapshot, hour int64, fallback snapshot) snapshot {
	if hour < 0 {
		return fallback
	}
	s := rg[hour%ringSize]
	if s.Set && s.Hour == hour {
		return s
	}
	return fallback
}

// lastKnownSnapshot returns the latest snapshot in rg (a copy of the ring)
// at or before hour, or the current totals if there is none. 24 reads.
func lastKnownSnapshot(rg *[ringSize]snapshot, hour int64) snapshot {
	best := currentSnapshot(hour)
	found := false
	for i := 0; i < ringSize; i++ {
		s := rg[i]
		if s.Set && s.Hour <= hour && (!found || s.Hour > best.Hour) {
			best = s
			found = true
		}
	}
	return best
}

// poolCalc computes a pub's hourly pool share, caching the pool power of
// the last pub count seen (the integer roots are the costly part).
type poolCalc struct {
	pubs, powMilli int64
}

// shareMilli is a pub's share of one hour's pool in thousandths of a
// customer: townmath.PoolCustomersMilli(hod, s.Pubs, poolK, poolScaleBps)
// (computed here as HourCurve * PoolPowMilli times poolScaleBps clamped to
// 0..100000, the same formula), times the price factor of the snapshot's
// weight-weighted average price (TotalPriceWeight / TotalWeight) against
// ReferencePriceCg and the event boost, split by weight against the
// snapshot's total weight.
func (c *poolCalc) shareMilli(hod int, s snapshot, weight, boostBps int64) int64 {
	curve := townmath.HourCurve(hod)
	if curve <= 0 || s.Pubs <= 0 || s.TotalWeight <= 0 || weight <= 0 {
		return 0
	}
	if s.Pubs != c.pubs || c.powMilli == 0 {
		c.pubs = s.Pubs
		c.powMilli = townmath.PoolPowMilli(s.Pubs, poolK)
	}
	scale := poolScaleBps
	if scale < 0 {
		scale = 0
	}
	if scale > maxPoolScaleClamp {
		scale = maxPoolScaleClamp
	}
	pool := townmath.MulBps(curve*c.powMilli, scale)
	pool = townmath.MulBps(pool, townmath.PriceFactorBps(s.TotalPriceWeight/s.TotalWeight, ReferencePriceCg))
	pool = townmath.MulBps(pool, boostBps)
	return townmath.PubShareMilli(pool, weight, s.TotalWeight)
}

// PoolSnapshot returns the raw ring slot that hour maps to (hour % 24): the
// hour it holds, the pub count, total weight and total price x weight then,
// and whether it was ever written. Compare the returned hour with yours: the slot
// may hold another hour. Read-only.
func PoolSnapshot(hour int64) (slotHour, pubs, totalW, totalPriceW int64, set bool) {
	if hour < 0 {
		return 0, 0, 0, 0, false
	}
	s := ring[hour%ringSize]
	return s.Hour, s.Pubs, s.TotalWeight, s.TotalPriceWeight, s.Set
}

// PoolSharesMilli returns, for each pub count in pubs (at most 64 are
// used), the share in milli customers that settlement credits a pub of
// weight at hour of day hod, with the given total weight, total price x
// weight and event boost, under the current pool params. One cached
// calculator serves the whole list, as in a settle. Read-only.
func PoolSharesMilli(hod int, pubs []int64, totalW, totalPriceW, weight, boostBps int64) []int64 {
	n := len(pubs)
	if n > 64 {
		n = 64
	}
	out := make([]int64, n)
	var c poolCalc
	for i := 0; i < n; i++ {
		s := snapshot{Pubs: pubs[i], TotalWeight: totalW, TotalPriceWeight: totalPriceW, Set: true}
		out[i] = c.shareMilli(hod, s, weight, boostBps)
	}
	return out
}

// SnapshotWrites returns how many ring writes were stored (writes skipped
// because nothing changed are not counted). Read-only.
func SnapshotWrites() int64 {
	return snapshotWrites
}

// GetPoolParams returns the pool exponent step count k and the demand scale
// in basis points.
func GetPoolParams() (k int, scaleBps int64) {
	return poolK, poolScaleBps
}

package jointv1

import (
	"time"

	"chain"
	"chain/banker"

	"gno.land/p/g17wg7tk6az05tz7vu6qfkvzau6p30aezuct3nt3/townmath"
)

// Seasons and the prize pot. The realm keeps one season. While it is running,
// shop sales add to the live pot. Freeze copies the live boards and splits
// that pot; claims pay the copy. The next StartSeason waits until every rank
// that would pay has claimed, then drops the copy. Live boards are cleared
// at the start. Each tavern's season fields are cleared lazily, the next
// time it is settled, by comparing ScoreGen to seasonGen.

const (
	// MinPubPotBps and MaxPubPotBps bound the pubs' share of a frozen pot.
	MinPubPotBps int64 = 4000
	MaxPubPotBps int64 = 8000

	minSeasonSeconds int64 = 60
	maxSeasonSeconds int64 = 86400 * 30
)

// Season is the frozen prize snapshot. Number 0 means a season has never
// started. Pots are ugnot. Top and FarmTop are copies of the live boards
// at the freeze, and Claimed* marks a rank (0-based) already paid.
type Season struct {
	Number, EndsAt, PotUgnot, PubPotUgnot, FarmPotUgnot int64
	Frozen                                              bool
	Top                                                 [TopN]townmath.Entry
	TopLen                                              int
	FarmTop                                             [TopN]townmath.Entry
	FarmTopLen                                          int
	ClaimedPubs, ClaimedFarms                           [TopN]bool
}

// PubPotBps is the pubs' share of the next freeze, in basis points.
func PubPotBps() int64 { return pubPotBps }

// GetSeason returns a copy of the season snapshot.
func GetSeason() Season { return season }

// SeasonGen returns the live season generation. StartSeason increments it.
// Read-only.
func SeasonGen() int64 { return seasonGen }

// StartSeason opens a season of durationSeconds (60 to 30 days). Admin only.
// Allowed when no season has started, or the current one is frozen and every
// rank that would pay has been claimed. Live boards are cleared. Per-tavern
// scores are left in place until the next settle (see seasonGen).
func StartSeason(cur realm, durationSeconds int64) {
	assertAdmin(cur)
	assertNoSend()
	if durationSeconds < minSeasonSeconds || durationSeconds > maxSeasonSeconds {
		panic("town: season duration must be 60 to 2592000")
	}
	if season.Number != 0 && !season.Frozen {
		panic("town: season already active")
	}
	if season.Frozen && unclaimedPrizes() {
		panic("town: unclaimed prizes")
	}
	seasonGen++
	season = Season{
		Number: season.Number + 1,
		EndsAt: time.Now().Unix() + durationSeconds,
	}
	clearLiveBoards()
}

// FreezeSeason snapshots the live boards and splits the live pot. Anyone may
// call it, once, at or after EndsAt. The live pot is zeroed so later sales
// accumulate the next season's pot; the shop stays open.
func FreezeSeason(cur realm) {
	if !cur.Previous().IsUserCall() {
		panic("town: must be a direct user call")
	}
	assertNoSend()
	if season.Number == 0 || season.Frozen || time.Now().Unix() < season.EndsAt {
		panic("town: season not ended")
	}
	season.Frozen = true
	season.Top = top
	season.TopLen = topLen
	season.FarmTop = farmTop
	season.FarmTopLen = farmTopLen
	pot := potUgnot
	season.PotUgnot = pot
	season.PubPotUgnot = townmath.MulBps(pot, pubPotBps)
	season.FarmPotUgnot = pot - season.PubPotUgnot
	potUgnot = 0
	for i := 0; i < TopN; i++ { // TopN is 10
		season.ClaimedPubs[i] = false
		season.ClaimedFarms[i] = false
	}
}

// ClaimPrize pays the caller their frozen prize, pubs or farms. The realm
// balance is checked, then the rank is marked, then the coins are sent.
func ClaimPrize(cur realm) {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("town: must be a direct user call")
	}
	assertNoSend()
	if !season.Frozen {
		panic("town: season not frozen")
	}
	caller := prev.Address().String()
	farm := false
	rank := -1
	for i := 0; i < season.TopLen && i < TopN; i++ {
		if season.Top[i].Owner == caller {
			rank = i
			break
		}
	}
	if rank < 0 {
		farm = true
		for i := 0; i < season.FarmTopLen && i < TopN; i++ {
			if season.FarmTop[i].Owner == caller {
				rank = i
				break
			}
		}
	}
	if rank < 0 {
		panic("town: not a winner")
	}
	if farm {
		if season.ClaimedFarms[rank] {
			panic("town: already claimed")
		}
	} else if season.ClaimedPubs[rank] {
		panic("town: already claimed")
	}
	pot := season.PubPotUgnot
	if farm {
		pot = season.FarmPotUgnot
	}
	amt := townmath.Payout(pot, rank+1)
	if amt == 0 {
		panic("town: nothing to claim")
	}
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	if bk.GetCoin(cur.Address(), "ugnot") < amt {
		panic("town: insufficient realm balance")
	}
	if farm {
		season.ClaimedFarms[rank] = true
	} else {
		season.ClaimedPubs[rank] = true
	}
	bk.SendCoins(cur.Address(), prev.Address(), chain.NewCoins(chain.NewCoin("ugnot", amt)))
}

// unclaimedPrizes reports whether a frozen snapshot still owes a rank whose
// payout would be more than zero.
func unclaimedPrizes() bool {
	for i := 0; i < season.TopLen && i < TopN; i++ {
		if !season.ClaimedPubs[i] && townmath.Payout(season.PubPotUgnot, i+1) > 0 {
			return true
		}
	}
	for i := 0; i < season.FarmTopLen && i < TopN; i++ {
		if !season.ClaimedFarms[i] && townmath.Payout(season.FarmPotUgnot, i+1) > 0 {
			return true
		}
	}
	return false
}

func clearLiveBoards() {
	topLen = 0
	farmTopLen = 0
	for i := 0; i < TopN; i++ { // TopN is 10
		top[i] = townmath.Entry{}
		farmTop[i] = townmath.Entry{}
	}
}

package jointv1

import (
	"chain/runtime"

	"gno.land/p/g17wg7tk6az05tz7vu6qfkvzau6p30aezuct3nt3/townmath"
)

// Settlement, daily events and the live leaderboard.
//
// Settling a tavern applies the game hours LastHour+1..now, at most the last
// townmath.MaxCatchUpHours (24) of them, split at game-day boundaries so each
// day uses its own event. A day's event comes from a per-day seed stored by
// the first mutating call of that day, in a fixed ring of the last SeedRing
// days (settlement reads at most the current and the previous day), so seed
// storage stays constant.

const (
	// DailyScoreCap is the most a tavern's season score can grow in one game day.
	DailyScoreCap int64 = 5000
	// TopN is the leaderboard length.
	TopN = 10
	// BarmaidStaffBps is the weight multiplier with a barmaid (10000 without).
	BarmaidStaffBps int64 = 12500
	// MaxSeats bounds the seats used in settlement.
	MaxSeats int64 = 50
	maxRep   int64 = 500
	// SeedRing is how many recent game days keep their seed.
	SeedRing = 4
)

// seedSlot holds one day's seed; Set tells an empty slot from day 0.
type seedSlot struct {
	Day  int64
	Seed uint64
	Set  bool
}

var (
	seeds    [SeedRing]seedSlot // slot day % SeedRing
	seeded   bool               // any seed stored yet
	lastSeed uint64             // most recently stored seed (valid when seeded)
	// The leaderboard lives in a fixed array updated in place (element
	// writes), so a settle never stores a new slice: assigning a fresh slice
	// every settle grew storage by about 465 bytes each time.
	top    [TopN]townmath.Entry
	topLen int // entries in use, 0..TopN
	// farmTop is the production board. Pubs never go on it and farms never
	// go on top. Same fixed-array rules as the pub board.
	farmTop    [TopN]townmath.Entry
	farmTopLen int
)

// Settle settles owner's pub or farm up to the current game hour (a farm
// harvests its crop; a dormant pub earns nothing and only its LastHour
// moves). Anyone may call it, including other realms; it only credits what
// the rules already owe. The owner's own direct call on a pub is an own
// action: it moves LastActionHour and rejoins a dormant pub.
func Settle(cur realm, owner string) {
	assertNoSend()
	assertNotPaused()
	t := mustTavern(owner)
	if t.Role == RoleFarm {
		settleFarm(t)
		return
	}
	settleTavern(t)
	if prev := cur.Previous(); prev.IsUserCall() && prev.Address() == t.Owner {
		ownerActs(t) // the owner's own settle is an own action: it rejoins
		return
	}
	if t.Dormant != 0 {
		settleDormant(t, CurrentGameHour())
	}
}

// EventToday returns the event of the current game day, or the no-event
// value if no call has stored the day's seed yet. Read-only.
func EventToday() townmath.Event {
	return EventOnDay(CurrentGameHour() / 24)
}

// EventOnDay returns the event of a game day from its stored seed, or the
// no-event value if that day has no seed. Read-only.
func EventOnDay(day int64) townmath.Event {
	s, ok := DaySeed(day)
	if !ok {
		return noEvent()
	}
	return townmath.EventForDay(s, day)
}

// DaySeed returns the stored seed of a game day. Only the last SeedRing
// days that were touched keep a seed.
func DaySeed(day int64) (uint64, bool) {
	if day < 0 {
		return 0, false
	}
	sl := seeds[day%SeedRing]
	if !sl.Set || sl.Day != day {
		return 0, false
	}
	return sl.Seed, true
}

// LastSeed returns the seed the next new day seed chains from: the most
// recently stored day seed, or the deploy time before any day was seeded.
func LastSeed() uint64 {
	if !seeded {
		return uint64(genesisUnix)
	}
	return lastSeed
}

// Top returns a copy of the live pub leaderboard (at most TopN entries).
func Top() []townmath.Entry {
	out := make([]townmath.Entry, topLen)
	for i := 0; i < topLen; i++ { // topLen <= TopN
		out[i] = top[i]
	}
	return out
}

// TopFarms returns a copy of the live farm production board.
func TopFarms() []townmath.Entry {
	out := make([]townmath.Entry, farmTopLen)
	for i := 0; i < farmTopLen; i++ { // farmTopLen <= TopN
		out[i] = farmTop[i]
	}
	return out
}

// ensureSeasonScore clears a tavern's season fields when a new season has
// started since they were last scored. Called from settle, before any
// early return, so a same-hour settle still drops the previous season's
// score and does not submit it again. A field that is already zero is left
// untouched. ScoreGen is still set to the live generation.
func ensureSeasonScore(t *Tavern) {
	if t.ScoreGen == seasonGen {
		return
	}
	if t.SeasonScore != 0 {
		t.SeasonScore = 0
	}
	if t.SeasonProfitCg != 0 {
		t.SeasonProfitCg = 0
	}
	if t.SeasonProd != 0 {
		t.SeasonProd = 0
	}
	if t.ScoreDayStart != 0 {
		t.ScoreDayStart = 0
	}
	if t.ProfitTodayCg != 0 {
		t.ProfitTodayCg = 0
	}
	t.ScoreGen = seasonGen
}

// NextSeasonScore returns the new season score for a tavern: the score from
// profit and reputation (negative profit counts as 0, reputation is clamped
// to 0..500), grown at most DailyScoreCap above the score the day started
// with, and never below the old score or 0.
func NextSeasonScore(oldScore, dayStartScore, seasonProfitCg, rep int64) int64 {
	if oldScore < 0 {
		oldScore = 0
	}
	if dayStartScore < 0 {
		dayStartScore = 0
	}
	if dayStartScore > oldScore {
		dayStartScore = oldScore
	}
	if seasonProfitCg < 0 {
		seasonProfitCg = 0
	}
	if rep < 0 {
		rep = 0
	}
	if rep > maxRep {
		rep = maxRep
	}
	raw := townmath.SeasonScore(seasonProfitCg, rep)
	if raw < 0 {
		raw = 0
	}
	s := townmath.CapGain(dayStartScore, raw, DailyScoreCap)
	if s < oldScore {
		return oldScore
	}
	return s
}

// settleTavern applies the elapsed game hours to t. Hours already settled,
// or a LastHour ahead of the clock, credit nothing. Each missed hour's
// customers are t's share of that hour's town pool (see ring.gno), from the
// ring snapshot of that hour or the last known one before it; fractions of a
// customer carry over in t.Carry. The crew's regulars (crewBonus) are added
// to each hour's whole customers after the carry step. Staff is part of the weight, so the
// demand is not scaled again here. A dormant pub earns nothing and is left
// unchanged, so an own action can still be refused after the settle without
// having changed it (see settleDormant).
func settleTavern(t *Tavern) {
	ensureSeasonScore(t)
	ensureDaySeed()
	touchMarket()
	now := CurrentGameHour()
	last := t.LastHour
	if t.Dormant != 0 {
		return // earns nothing; Settle and ownerActs move its LastHour
	}
	if last >= now {
		writeSnapshot(now)
		return
	}
	hours := now - last
	if hours > townmath.MaxCatchUpHours {
		hours = townmath.MaxCatchUpHours
	}
	seats := t.Seats
	if seats < 0 {
		seats = 0
	}
	if seats > MaxSeats {
		seats = MaxSeats
	}
	profitDay := last / 24
	h := now - hours + 1
	// Read the ring once, with the start-of-settle snapshot of now applied to
	// the copy only: the reweigh at the end stores the slot of now (one ring
	// write per settle instead of two; the stored result is the same).
	rg := ring
	if s := rg[now%ringSize]; !s.Set || s.Hour <= now {
		rg[now%ringSize] = currentSnapshot(now)
	}
	known := lastKnownSnapshot(&rg, h)
	var calc poolCalc
	// The crew is read once per settle (at most MaxCrew OwnerOf and
	// GetVillager reads, none for an empty crew).
	var crew [MaxCrew]crewMember
	var moods [MaxCrew]int
	hasCrew := loadCrew(t, &crew)
	// 24 hours span at most 2 game days; the bound is a safety net
	for i := 0; i < 3 && h <= now; i++ {
		day := h / 24
		end := day*24 + 23
		if end > now {
			end = now
		}
		if day != profitDay {
			t.ProfitTodayCg = 0
			t.ScoreDayStart = t.SeasonScore
			profitDay = day
		}
		ev := EventOnDay(day)
		profit := int64(0)
		if ev.TaxBps > 0 && t.LastTaxDay != day+1 && t.GoldCg > 0 {
			bps := ev.TaxBps
			if bps > townmath.BpsOne {
				bps = townmath.BpsOne
			}
			tax := townmath.MulBps(t.GoldCg, bps)
			t.GoldCg -= tax
			goldDestroyedCg += tax
			profit -= tax
			t.LastTaxDay = day + 1
		}
		n := end - h + 1 // 1..24
		if hasCrew {
			dayMoods(&crew, &moods, day, h, end)
		}
		demands := make([]int64, n)
		for j := int64(0); j < n; j++ {
			known = snapshotFor(&rg, h+j, known)
			milli := calc.shareMilli(int((h+j)%24), known, t.Weight, ev.BoostBps)
			demands[j], t.Carry = townmath.CarryDemand(milli, t.Carry)
			if hasCrew {
				// regulars come on top of the pool share, after the carry
				demands[j] += crewBonus(&crew, &moods, h+j)
			}
		}
		out := townmath.SettleRangeDemand(demands, townmath.SettleIn{
			PriceCg:  t.PriceCg,
			Rep:      t.Rep,
			Stock:    t.Stock,
			Seats:    seats,
			EventBps: townmath.BpsOne,
			StaffBps: townmath.BpsOne,
		})
		t.GoldCg += out.RevenueCg
		goldCreatedCg += out.RevenueCg
		t.Stock = out.StockLeft
		t.Rep = out.RepAfter
		profit += out.RevenueCg
		t.ProfitTodayCg += profit
		t.SeasonProfitCg += profit
		t.SeasonScore = NextSeasonScore(t.SeasonScore, t.ScoreDayStart, t.SeasonProfitCg, t.Rep)
		h = end + 1
	}
	t.LastHour = now
	reweigh(t, t.PriceCg) // settlement moves reputation
	submitScore(t)
}

// submitScore puts t's score on the leaderboard. The entry never falls
// (max of the listed and the new score) and only t's own entry changes.
// An owner already listed with the same score changes nothing (no write).
// Otherwise townmath.InsertTop updates the fixed array in place, with the
// same result as townmath.UpdateTop.
func submitScore(t *Tavern) {
	if t.Role != RolePub {
		return // farms are scored on farmTop only
	}
	owner := t.Owner.String()
	s := t.SeasonScore
	listed := false
	for i := 0; i < topLen; i++ { // topLen <= TopN
		if top[i].Owner == owner {
			listed = true
			if top[i].Score > s {
				s = top[i].Score
			}
			if top[i].Score == s {
				return // unchanged
			}
		}
	}
	if s <= 0 {
		return
	}
	if !listed && topLen == TopN && top[TopN-1].Score >= s {
		return // would rank below a full board: InsertTop would drop it
	}
	topLen = townmath.InsertTop(top[:], topLen, townmath.Entry{Owner: owner, Score: s})
}

// submitFarmScore puts a farm's production score on the farm board. Same
// high-water rule as pubs: the listed score never falls, and an unchanged
// score does not write. Pubs are ignored.
func submitFarmScore(t *Tavern) {
	if t.Role != RoleFarm {
		return
	}
	owner := t.Owner.String()
	s := t.SeasonScore
	listed := false
	for i := 0; i < farmTopLen; i++ { // farmTopLen <= TopN
		if farmTop[i].Owner == owner {
			listed = true
			if farmTop[i].Score > s {
				s = farmTop[i].Score
			}
			if farmTop[i].Score == s {
				return
			}
		}
	}
	if s <= 0 {
		return
	}
	if !listed && farmTopLen == TopN && farmTop[TopN-1].Score >= s {
		return
	}
	farmTopLen = townmath.InsertTop(farmTop[:], farmTopLen, townmath.Entry{Owner: owner, Score: s})
}

// ensureDaySeed stores the current game day's seed if no call has yet.
func ensureDaySeed() {
	day := CurrentGameHour() / 24 // never negative
	sl := seeds[day%SeedRing]
	if sl.Set && sl.Day >= day {
		// already seeded, or the slot holds a newer day (block time behind
		// it): never replace a newer seed, so a day's event cannot change
		return
	}
	s := townmath.Mix(LastSeed() ^ uint64(runtime.ChainHeight()))
	seeds[day%SeedRing] = seedSlot{Day: day, Seed: s, Set: true} // replaces an older day
	lastSeed = s
	seeded = true
}

func noEvent() townmath.Event {
	return townmath.Event{Kind: townmath.EventNone, BoostBps: townmath.BpsOne, GrainMulBps: townmath.BpsOne}
}

// mustTavern returns the stored tavern of owner (a pointer into state).
func mustTavern(owner string) *Tavern {
	v := taverns.Get(owner)
	if v == nil {
		panic("town: no joint for this address")
	}
	return v.(*Tavern)
}

package jointv1

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/g17wg7tk6az05tz7vu6qfkvzau6p30aezuct3nt3/townmath"
	villagers "gno.land/r/g17wg7tk6az05tz7vu6qfkvzau6p30aezuct3nt3/villagersv1"
)

// GNOT shop. Gold is not involved: a sale splits ugnot between the live
// season pot and the treasury. The pack seed mixes the block height, a
// counter and the buyer. It is weak and the buyer can steer it by choosing
// the block, the same class of randomness as the daily event seed. Traits
// from a pack are cosmetic.

const (
	ItemNeon = "neon"
	ItemFloor = "floor"
	ItemPack = "pack"

	PriceNeonUgnot  int64 = 2_000_000
	PriceFloorUgnot int64 = 5_000_000
	PricePackUgnot  int64 = 3_000_000

	// FloorSeatsBonus is the seats a floor adds, once per pub.
	FloorSeatsBonus int64 = 3
)

// ShopPrice returns the ugnot price of a shop item, or 0 when item is unknown.
func ShopPrice(item string) int64 {
	switch item {
	case ItemNeon:
		return PriceNeonUgnot
	case ItemFloor:
		return PriceFloorUgnot
	case ItemPack:
		return PricePackUgnot
	}
	return 0
}

// PotNow is the live season pot in ugnot (not the frozen snapshot).
func PotNow() int64 { return potUgnot }

// TreasuryNow is the ugnot the treasury address may withdraw.
func TreasuryNow() int64 { return treasuryUgnot }

// Treasury is the address allowed to withdraw, or empty when unset.
func Treasury() address { return treasuryAddr }

// BuyItem sells item to the caller for exactly its ugnot price. Neon and a
// floor require a pub that does not already have them. A pack mints one
// villager to the buyer; any user may buy one. The price then splits into
// the live pot and the treasury. Every check runs before a write or a mint:
// a panic in the test VM does not roll attached coins back.
func BuyItem(cur realm, item string) {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("town: must be a direct user call")
	}
	assertNotPaused()
	sent := unsafe.OriginSend()
	if len(sent) != 1 {
		panic("town: send exactly one coin")
	}
	if sent[0].Denom != "ugnot" {
		panic("town: only ugnot")
	}
	price := ShopPrice(item)
	if price == 0 {
		panic("town: unknown item")
	}
	if sent[0].Amount != price {
		panic("town: wrong amount")
	}
	buyer := prev.Address()
	switch item {
	case ItemNeon, ItemFloor:
		t := mustTavern(buyer.String())
		assertPub(t)
		if item == ItemNeon {
			if t.HasNeon {
				panic("town: already has neon")
			}
			t.HasNeon = true
		} else {
			if t.HasFloor {
				panic("town: already has floor")
			}
			t.Seats += FloorSeatsBonus
			t.HasFloor = true
			reweigh(t, t.PriceCg) // seats change the pub's weight
		}
	case ItemPack:
		// Height, the per-sale counter and the buyer. Weak: a buyer who
		// waits for a block they like can steer the seed.
		seed := townmath.Mix(uint64(runtime.ChainHeight()) ^ packCounter ^ foldAddr(buyer))
		packCounter++
		villagers.MintFor(cross(cur), buyer, seed, CurrentGameHour())
	default:
		panic("town: unknown item")
	}
	pot, tre := townmath.SplitPayment(sent[0].Amount, params.PotBps)
	potUgnot += pot
	treasuryUgnot += tre
}

// WithdrawTreasury sends the whole treasury balance to the treasury address
// and only to them. The balance is checked before the accounting is cleared,
// then the accounting is cleared before the send, so a second withdraw in
// the same call cannot pay twice and a short realm does not wipe the books
// (a panic in the test VM would not roll that write back).
func WithdrawTreasury(cur realm) {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("town: must be a direct user call")
	}
	assertNoSend()
	if treasuryAddr == "" || prev.Address() != treasuryAddr {
		panic("town: treasury only")
	}
	amt := treasuryUgnot
	if amt == 0 {
		panic("town: nothing to withdraw")
	}
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	if bk.GetCoin(cur.Address(), "ugnot") < amt {
		panic("town: insufficient realm balance")
	}
	treasuryUgnot = 0
	bk.SendCoins(cur.Address(), prev.Address(), chain.NewCoins(chain.NewCoin("ugnot", amt)))
}

// foldAddr XORs an address string as little-endian 8-byte chunks. An empty
// address folds to 0. At most 16 chunks are read (128 bytes).
func foldAddr(a address) uint64 {
	s := a.String()
	n := len(s)
	if n > 128 {
		n = 128
	}
	var x uint64
	for i := 0; i < n; i += 8 { // at most 16 chunks
		var chunk uint64
		for j := 0; j < 8 && i+j < n; j++ {
			chunk |= uint64(s[i+j]) << (uint(j) * 8)
		}
		x ^= chunk
	}
	return x
}

// Package town is The Joint game realm: joints, params and admin.
// The realm has no background loop; time is read from the block (time.Now())
// and converted to game hours on demand.
package jointv1

import (
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ownable/v0"
)

// Goods index into Tavern.Inv.
const (
	GoodAle   = 0
	GoodGrain = 1
	GoodHops  = 2
	GoodMead  = 3
)

// Starting values for a new tavern.
const (
	StartStock   int64 = 18
	StartPriceCg int64 = 600
	StartRep     int64 = 360
	StartSeats   int64 = 5
)

// Bounds for caller-set values.
const (
	MinNameLen                = 3
	MaxNameLen                = 24
	MinSecondsPerGameHour     = 10
	MaxSecondsPerGameHour     = 3600
	MinPotBps                 = 0
	MaxPotBps                 = 10000
	defaultSecondsPerGameHour = 60
	defaultPotBps             = 7000
	defaultStartGoldCg        = 24000
)

// noKeyAdmin is used only when init sees an empty deployer address, which
// happens in the gno test VM (package init runs with an empty caller) and never
// on chain, where addpkg always has a signer. It is the raw bytes
// "noadmin_____________", not derived from any public key, so nobody can sign
// as it: on chain the fallback would leave the realm with no usable admin.
// Tests act as admin through Admin().
const noKeyAdmin address = "g1dehkzerdd9h97h6lta047h6lta047h6l4mazdj"

// Params are the admin-tunable game settings.
type Params struct {
	SecondsPerGameHour, PotBps, StartGoldCg int64
	Paused                                  bool
}

// Business roles (Tavern.Role). One business per address across both roles.
const (
	RolePub  int64 = 0
	RoleFarm int64 = 1
)

// ReferencePriceCg is the fixed market price a pub's weight is measured
// against. It is fixed (not the moving town price) so the incrementally kept
// town totals stay valid when the market moves.
const ReferencePriceCg int64 = 600

// Starting values for a new farm. FarmStartPlots stays within
// townmath.MaxFarmPlots (checked by the roles tests).
const (
	FarmStartPlots int64 = 1
	FarmStartGrain int64 = 6
)

// Tavern is one player's business: a pub (Role RolePub) or a farm (Role
// RoleFarm). Money is in centigold (Cg).
// LastHour is the last game hour settled. ProfitTodayCg is the profit of the
// game day LastHour/24. LastTaxDay is 1 + the last game day taxed (0 = never).
// ScoreDayStart is SeasonScore when the current game day began; the day's
// score gain is capped from it.
// Plots is a farm's plot count. Weight is a pub's pull on the customer pool
// as counted in totalWeight (always 0 for a farm). Carry is, for a pub, the
// fraction of a customer (0..999 thousandths) its pool share carries to the
// next hour; for a farm, the fraction of a crop unit (0..9999 ten-thousandths)
// its harvest carries to the next settle. AdLevel and AdEndHour are reserved for ads (0 until then).
// Crop is what a farm grows (townmath.CropGrain or CropHops; 0, grain, by
// default). TFDay is the game day TFSold and TFBought count: the units this
// business sold to and bought from the Town Farm on that day.
// Dormant is 1 for a pub the idle pass removed from the town totals (0
// otherwise; farms are never dormant). LastActionHour is the game hour of
// the owner's last own action (creation, SetPrice, Hire, Brew, BuyGood,
// BuyListing, the crew actions, the owner's own Settle); a third party's Settle never moves it. OpenListings is the
// number of the seller's listings still open. Crew holds a pub's crew
// villager ids ("" = empty slot) and CrewRestUntil the game hour each slot's
// day off ends (see crew.gno).
// HasFloor is set by the GNOT floor item; it adds FloorSeatsBonus seats once.
// SeasonProd is the units a farm has harvested this season (its season
// score is that total, capped per day, not gold). ScoreGen is the season
// generation those season fields were scored in. StartSeason bumps the
// town's generation and the next settle clears a tavern whose ScoreGen is
// behind, so old scores are not walked at the start.
// Every field is a value type (no slices, maps or pointers), so the shallow
// copy GetTavern returns never aliases realm state. Keep it that way.
type Tavern struct {
	Owner                                                  address
	Name                                                   string
	GoldCg, Stock, PriceCg, Rep, Seats                     int64
	Inv                                                    [4]int64
	HasBarmaid, HasNeon, HasFloor                          bool
	LastHour                                               int64
	ProfitTodayCg, SeasonProfitCg, SeasonScore, LastTaxDay int64
	ScoreDayStart                                          int64
	Role, Plots, Weight, Carry, AdLevel, AdEndHour         int64
	Crop, TFDay, TFSold, TFBought                          int64
	Dormant, LastActionHour, OpenListings                  int64
	Crew                                                   [MaxCrew]string
	CrewRestUntil                                          [MaxCrew]int64
	SeasonProd, ScoreGen                                   int64
}

var (
	admin       *ownable.Ownable
	params      Params
	genesisUnix int64
	// Game clock: CurrentGameHour = hourBase + (now - anchorUnix) / SecondsPerGameHour.
	// SetSecondsPerGameHour re-anchors so a speed change never re-maps past time.
	hourBase   int64
	anchorUnix int64
	taverns    avl.Tree // owner address string -> *Tavern (pubs and farms)
	// Town totals, kept incrementally (see reweigh in farm.gno).
	pubCount     int64
	farmCount    int64
	totalWeight  int64 // sum of Weight over pubs
	totalPriceCg int64 // sum of PriceCg over pubs
	// sum of PriceCg * Weight over pubs (at most 1200 * 5.6e6 per pub, so
	// safe in int64 for millions of pubs): the pool elasticity uses the
	// weight-weighted average price totalPriceWeight / totalWeight
	totalPriceWeight int64
	// Town Farm counters of game day tfDay: units it sold to pubs and
	// bought from farms. The first trade of another day resets them.
	tfDay          int64
	tfSoldGlobal   int64
	tfBoughtGlobal int64
	// Gold flow (centigold): all gold the game created (customer revenue,
	// Town Farm purchases from farms) and destroyed (tax, hires, Town Farm
	// sales to pubs). Start capital is the baseline and is not counted, so
	// the sum of all GoldCg = businesses * StartGoldCg + created - destroyed.
	goldCreatedCg   int64
	goldDestroyedCg int64
	// GNOT shop. potUgnot is the live pot (sales while a season is frozen
	// still add here, and become the next season's pot). treasuryUgnot is
	// what treasuryAddr may withdraw. packCounter is mixed into pack seeds.
	// pubPotBps is the pubs' share of a frozen pot; farms receive the rest.
	// seasonGen increments in StartSeason. season is the one frozen snapshot.
	potUgnot      int64
	treasuryUgnot int64
	treasuryAddr  address
	packCounter   uint64
	pubPotBps     int64 = 6000
	seasonGen     int64
	season        Season
)

func init(cur realm) {
	deployer := cur.Previous().Address()
	if deployer == "" {
		deployer = noKeyAdmin
	}
	admin = ownable.NewWithAddress(deployer)
	params = Params{
		SecondsPerGameHour: defaultSecondsPerGameHour,
		PotBps:             defaultPotBps,
		StartGoldCg:        defaultStartGoldCg,
	}
	genesisUnix = time.Now().Unix()
	hourBase = 0
	anchorUnix = genesisUnix
}

// GetParams returns a copy of the current params.
func GetParams() Params {
	return params
}

// CurrentGameHour is the number of whole game hours since deployment. Hours
// are continuous: a speed change applies only to time after the change.
// Never negative and never decreasing while block time moves forward.
func CurrentGameHour() int64 {
	elapsed := time.Now().Unix() - anchorUnix
	if elapsed < 0 {
		elapsed = 0
	}
	return hourBase + elapsed/params.SecondsPerGameHour
}

// GameClock returns the hour base and anchor time (unix seconds) that
// CurrentGameHour counts from.
func GameClock() (int64, int64) {
	return hourBase, anchorUnix
}

// GenesisUnix is the block time (unix seconds) at deployment.
func GenesisUnix() int64 {
	return genesisUnix
}

package jointv1

// CreateTavern opens a tavern (a pub) for the calling user. One business
// (pub or farm) per address. The name is 3 to 24 bytes of printable ASCII.
func CreateTavern(cur realm, name string) {
	prev := cur.Previous()
	// validate everything first; mutate only after
	if !prev.IsUserCall() {
		panic("town: CreateTavern must be a direct user call")
	}
	assertNotPaused()
	assertNoSend()
	validateName(name)
	owner := prev.Address()
	key := owner.String()
	assertNoBusiness(key)

	now := CurrentGameHour()
	t := &Tavern{
		Owner:          owner,
		Name:           name,
		GoldCg:         params.StartGoldCg,
		Stock:          StartStock,
		PriceCg:        StartPriceCg,
		Rep:            StartRep,
		Seats:          StartSeats,
		LastHour:       now,
		Role:           RolePub,
		LastActionHour: now,
		ScoreGen:       seasonGen,
	}
	taverns.Set(key, t)
	joinTotals(t)
	writeSnapshot(now)
}

// GetTavern returns a copy of owner's tavern, or nil if there is none.
// Changing the copy does not change realm state.
func GetTavern(owner string) *Tavern {
	v := taverns.Get(owner)
	if v == nil {
		return nil
	}
	c := *(v.(*Tavern))
	return &c
}

// TavernCount returns the number of pubs in the town totals: dormant pubs
// and farms are not counted. Use TownStats for both the pub and the farm
// count, and BusinessCount for every stored business.
func TavernCount() int {
	return int(pubCount)
}

func validateName(name string) {
	if len(name) < MinNameLen || len(name) > MaxNameLen {
		panic("town: name must be 3 to 24 bytes")
	}
	for i := 0; i < len(name); i++ { // bounded by MaxNameLen
		c := name[i]
		if c < 0x20 || c > 0x7e {
			panic("town: name must be printable ASCII")
		}
	}
}

// Bounds and costs for tavern actions.
const (
	MinPriceCg int64 = 200
	MaxPriceCg int64 = 1200
	HireCostCg int64 = 12000
	MaxStock   int64 = 60
	BrewGrain  int64 = 12 // grain used per brew
	BrewHops   int64 = 3  // hops used per brew
	BrewAle    int64 = 12 // ale stock made per brew
)

// Every gold-only action has a public crossing wrapper that takes the actor
// from the direct user call, and an internal function that takes the actor
// address and applies the rules: validate, settle, check, mutate.

// SetPrice sets the caller's menu price for ale, 200 to 1200 centigold.
func SetPrice(cur realm, priceCg int64) {
	setPrice(userActor(cur), priceCg)
}

func setPrice(actor address, priceCg int64) {
	assertNotPaused()
	t := mustTavern(actor.String())
	assertPub(t)
	if priceCg < MinPriceCg || priceCg > MaxPriceCg {
		panic("town: price must be 200 to 1200 centigold")
	}
	settleTavern(t)
	ownerActs(t) // every check passed: a dormant pub rejoins here
	old := t.PriceCg
	t.PriceCg = priceCg
	reweigh(t, old)
}

// Hire hires a barmaid for 12000 centigold, once per tavern. A barmaid
// raises the pub's weight (its pull on the customer pool) by 25%.
func Hire(cur realm) {
	hire(userActor(cur))
}

func hire(actor address) {
	assertNotPaused()
	t := mustTavern(actor.String())
	assertPub(t)
	settleTavern(t)
	if t.HasBarmaid {
		panic("town: joint already has a barmaid")
	}
	if t.GoldCg < HireCostCg {
		panic("town: not enough gold")
	}
	ownerActs(t)
	t.GoldCg -= HireCostCg
	goldDestroyedCg += HireCostCg
	t.ProfitTodayCg -= HireCostCg
	t.SeasonProfitCg -= HireCostCg
	t.HasBarmaid = true
	reweigh(t, t.PriceCg)
}

// Brew turns 12 grain and 3 hops from the caller's inventory into 12 ale
// stock. It is refused if grain (checked first) or hops are short, or if
// stock would pass 60.
func Brew(cur realm) {
	brew(userActor(cur))
}

func brew(actor address) {
	assertNotPaused()
	t := mustTavern(actor.String())
	assertPub(t)
	settleTavern(t)
	if t.Inv[GoodGrain] < BrewGrain {
		panic("town: not enough grain (a brew needs 12)")
	}
	if t.Inv[GoodHops] < BrewHops {
		panic("town: not enough hops (a brew needs 3)")
	}
	if t.Stock+BrewAle > MaxStock {
		panic("town: stock full (max 60)")
	}
	ownerActs(t)
	t.Inv[GoodGrain] -= BrewGrain
	t.Inv[GoodHops] -= BrewHops
	t.Stock += BrewAle
}

// userActor returns the caller of a gold-only action after checking it is a
// direct user call with no coins attached.
func userActor(cur realm) address {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("town: must be a direct user call")
	}
	assertNoSend()
	return prev.Address()
}

package jointexamplev1

import (
	"strings"

	"gno.land/p/nt/ufmt/v0"
	town "gno.land/r/g17wg7tk6az05tz7vu6qfkvzau6p30aezuct3nt3/jointv1"
)

// Render is a small supplier dashboard that only reads the town realm.
// It shows the four market prices. A bech32 address, or tavern/<address>,
// says whether that pub's menu price is above, below or equal to the ale
// market. A farm is not a pub. Nothing here is written and no coins move.
func Render(path string) string {
	s := "# Supplier dashboard\n\n"
	goods := []int{town.GoodAle, town.GoodGrain, town.GoodHops, town.GoodMead}
	names := []string{"ale", "grain", "hops", "mead"}
	for i := 0; i < len(goods); i++ {
		s += ufmt.Sprintf("%s %d\n", names[i], town.GoodPriceCg(goods[i]))
	}
	addr := path
	if strings.HasPrefix(path, "tavern/") {
		addr = path[len("tavern/"):]
	}
	if !looksAddr(addr) {
		return s
	}
	t := town.GetTavern(addr)
	if t == nil {
		s += "No joint at this address.\n"
		return s
	}
	if t.Role != town.RolePub {
		s += "not a pub\n"
		return s
	}
	ale := town.GoodPriceCg(town.GoodAle)
	s += ufmt.Sprintf("menu %d cg, ale market %d cg: ", t.PriceCg, ale)
	switch {
	case t.PriceCg > ale:
		s += "above\n"
	case t.PriceCg < ale:
		s += "below\n"
	default:
		s += "equal\n"
	}
	return s
}

// looksAddr is a shape check (g1…, lowercase), not a checksum check.
func looksAddr(s string) bool {
	if len(s) < 39 || len(s) > 45 || s[0] != 'g' || s[1] != '1' {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if (c < '0' || c > '9') && (c < 'a' || c > 'z') {
			return false
		}
	}
	return true
}

// Package arisan implements an on-chain rotating savings club (ROSCA),
// known as "arisan" in Indonesia and Southeast Asia.
//
// A circle works like this:
//   - A creator opens a circle with a fixed per-round contribution and a
//     maximum number of members, and automatically becomes its first member.
//   - Other members join while the circle is open.
//   - The creator starts the circle once at least two members have joined.
//   - Every round, each member contributes exactly the agreed amount of
//     ugnot by attaching it to a Contribute call.
//   - As soon as every member has contributed, the realm pays the whole pot
//     to one member, rotating in join order, and the next round begins.
//   - After every member has received the pot exactly once, the circle is
//     finished. No fees are taken and no funds are ever locked outside a
//     round in progress: a round's pot is paid out the moment it completes.
package arisan

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
)

const (
	// minContribution is the smallest allowed per-round contribution:
	// 1000 ugnot = 0.001 GNOT.
	minContribution int64 = 1000
	// minMembers is the smallest circle that can be started.
	minMembers = 2
	// maxMembersCap is the largest allowed circle size.
	maxMembersCap = 12
	// maxNameLen bounds circle names so Render output stays tidy.
	maxNameLen = 48

	statusOpen      = "open"
	statusActive    = "active"
	statusFinished  = "finished"
	statusCancelled = "cancelled"
)

// Circle is one rotating savings club.
type Circle struct {
	id           int
	name         string
	creator      address
	contribution int64 // ugnot each member pays per round
	maxMembers   int
	members      []address
	round        int // current round, 0-based
	status       string
	paid         map[address]bool // contributions received in the current round
	payouts      []address        // pot recipients, in order
}

var (
	circles []*Circle
	nextID  int
)

// originCaller returns the address that signed the transaction. It requires
// a direct call from a user account (an EOA), so an intermediary realm —
// including an ephemeral `maketx run` script — cannot act on a user's
// behalf. For Contribute this guard pairs with the OriginSend amount check:
// only for a direct user call is it guaranteed that the coins attached to
// the transaction actually landed at this realm's address.
func originCaller(cur realm) address {
	if !cur.Previous().IsUserCall() {
		panic("arisan: must be called directly by a user account")
	}
	return cur.Previous().Address()
}

// validateName restricts circle names to characters that are safe to print
// verbatim in the Markdown that Render returns: no Markdown control
// characters, so a name cannot inject links, images, or headings into the
// realm's pages.
func validateName(name string) {
	for _, r := range name {
		ok := (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') ||
			(r >= '0' && r <= '9') || r == ' ' || r == '-' ||
			r == '\'' || r == '.' || r == ',' || r == '!' ||
			r == '(' || r == ')'
		if !ok {
			panic("arisan: circle name contains unsupported characters")
		}
	}
}

func getCircle(id int) *Circle {
	if id < 0 || id >= len(circles) {
		panic("arisan: circle not found")
	}
	return circles[id]
}

func isMember(c *Circle, who address) bool {
	for _, m := range c.members {
		if m == who {
			return true
		}
	}
	return false
}

// nextRecipient returns the member scheduled to receive the current round's
// pot. Recipients rotate in join order, one per round.
func nextRecipient(c *Circle) address {
	return c.members[c.round%len(c.members)]
}

// CreateCircle opens a new circle and returns its ID. The creator is
// automatically the first member.
func CreateCircle(cur realm, name string, contribution int64, maxMembers int) int {
	return createCircle(originCaller(cur), name, contribution, maxMembers)
}

// createCircle is the internal implementation of CreateCircle, separated
// from the transaction envelope so it can be unit-tested directly.
func createCircle(caller address, name string, contribution int64, maxMembers int) int {
	name = strings.TrimSpace(name)
	if name == "" {
		panic("arisan: circle name must not be empty")
	}
	if len(name) > maxNameLen {
		panic("arisan: circle name too long")
	}
	validateName(name)
	if contribution < minContribution {
		panic("arisan: contribution below minimum of 1000 ugnot")
	}
	if maxMembers < minMembers || maxMembers > maxMembersCap {
		panic("arisan: maxMembers must be between 2 and 12")
	}
	c := &Circle{
		id:           nextID,
		name:         name,
		creator:      caller,
		contribution: contribution,
		maxMembers:   maxMembers,
		members:      []address{caller},
		status:       statusOpen,
		paid:         map[address]bool{},
	}
	circles = append(circles, c)
	nextID++
	return c.id
}

// JoinCircle adds the caller to an open circle that is not yet full.
func JoinCircle(cur realm, id int) {
	joinCircle(originCaller(cur), id)
}

func joinCircle(caller address, id int) {
	c := getCircle(id)
	if c.status != statusOpen {
		panic("arisan: circle is not open for joining")
	}
	if isMember(c, caller) {
		panic("arisan: already a member of this circle")
	}
	if len(c.members) >= c.maxMembers {
		panic("arisan: circle is full")
	}
	c.members = append(c.members, caller)
}

// StartCircle moves an open circle into its first round. Only the creator
// can start it, and at least two members must have joined.
func StartCircle(cur realm, id int) {
	startCircle(originCaller(cur), id)
}

func startCircle(caller address, id int) {
	c := getCircle(id)
	if caller != c.creator {
		panic("arisan: only the creator can start the circle")
	}
	if c.status != statusOpen {
		panic("arisan: circle is not open")
	}
	if len(c.members) < minMembers {
		panic("arisan: need at least 2 members to start")
	}
	c.status = statusActive
}

// CancelCircle cancels an open circle. Only the creator can cancel, and
// only before the circle starts (no contributions exist yet, so nothing
// needs to be refunded).
func CancelCircle(cur realm, id int) {
	cancelCircle(originCaller(cur), id)
}

func cancelCircle(caller address, id int) {
	c := getCircle(id)
	if caller != c.creator {
		panic("arisan: only the creator can cancel the circle")
	}
	if c.status != statusOpen {
		panic("arisan: only an open circle can be cancelled")
	}
	c.status = statusCancelled
}

// Contribute records the caller's contribution for the current round. The
// caller must attach exactly the circle's contribution amount in ugnot to
// the call (gnokey: -send "<amount>ugnot"). When the last member of the
// round contributes, the pot is paid out immediately.
func Contribute(cur realm, id int) {
	caller := originCaller(cur)
	sent := unsafe.OriginSend()
	contribute(cur, getCircle(id), caller, int64(sent.AmountOf("ugnot")))
}

// contribute holds the contribution logic, separated from the transaction
// envelope so it can be unit-tested with arbitrary senders and amounts.
func contribute(cur realm, c *Circle, caller address, sentAmount int64) {
	if c.status != statusActive {
		panic("arisan: circle is not active")
	}
	if !isMember(c, caller) {
		panic("arisan: only members can contribute")
	}
	if c.paid[caller] {
		panic("arisan: already contributed this round")
	}
	if sentAmount != c.contribution {
		panic("arisan: must send exactly the contribution amount")
	}
	c.paid[caller] = true

	for _, m := range c.members {
		if !c.paid[m] {
			return // still waiting on other members
		}
	}
	payout(cur, c)
}

// payout sends the completed round's pot to the scheduled recipient and
// advances the circle: next round, or finished once every member has
// received the pot exactly once.
func payout(cur realm, c *Circle) {
	recipient := nextRecipient(c)
	pot := c.contribution * int64(len(c.members))
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), recipient, chain.Coins{{"ugnot", pot}})
	c.payouts = append(c.payouts, recipient)
	c.round++
	c.paid = map[address]bool{}
	if c.round >= len(c.members) {
		c.status = statusFinished
	}
}

// CircleCount returns how many circles have ever been created.
func CircleCount() int {
	return len(circles)
}

// formatGNOT renders a ugnot amount as a decimal GNOT string.
func formatGNOT(ugnot int64) string {
	whole := ugnot / 1_000_000
	frac := ugnot % 1_000_000
	if frac == 0 {
		return strconv.FormatInt(whole, 10) + " GNOT"
	}
	fs := strconv.FormatInt(frac, 10)
	for len(fs) < 6 {
		fs = "0" + fs
	}
	fs = strings.TrimRight(fs, "0")
	return strconv.FormatInt(whole, 10) + "." + fs + " GNOT"
}

// Render is the realm's gnoweb page. The home page lists all circles;
// "circle/<id>" renders one circle's detail page.
func Render(path string) string {
	if path == "" {
		return renderHome()
	}
	parts := strings.Split(path, "/")
	if len(parts) == 2 && parts[0] == "circle" {
		id, err := strconv.Atoi(parts[1])
		if err != nil || id < 0 || id >= len(circles) {
			return "# Arisan Circle\n\nCircle not found."
		}
		return renderCircle(circles[id])
	}
	return "# Arisan Circle\n\nPage not found."
}

func renderHome() string {
	var sb strings.Builder
	sb.WriteString("# Arisan Circle\n\n")
	sb.WriteString("A rotating savings club (ROSCA) on Gno.land, inspired by the Indonesian *arisan*: ")
	sb.WriteString("members contribute a fixed amount every round, and each round one member receives the whole pot, ")
	sb.WriteString("rotating until everyone has received it once. No fees, no custodian — the realm holds a round's ")
	sb.WriteString("contributions only until the round completes, then pays out automatically.\n\n")
	sb.WriteString("## Circles\n\n")
	if len(circles) == 0 {
		sb.WriteString("No circles yet. Create the first one with `CreateCircle`.\n")
	}
	for _, c := range circles {
		sb.WriteString("### [" + c.name + "](circle/" + strconv.Itoa(c.id) + ")\n\n")
		sb.WriteString("- Status: **" + c.status + "**\n")
		sb.WriteString("- Contribution: " + formatGNOT(c.contribution) + " per member, per round\n")
		sb.WriteString("- Members: " + strconv.Itoa(len(c.members)) + "/" + strconv.Itoa(c.maxMembers) + "\n")
		if c.status == statusActive {
			sb.WriteString("- Round: " + strconv.Itoa(c.round+1) + " of " + strconv.Itoa(len(c.members)) +
				" — next pot goes to `" + nextRecipient(c).String() + "`\n")
		}
		sb.WriteString("\n")
	}
	sb.WriteString("## How to take part\n\n")
	sb.WriteString("1. `CreateCircle(name, contributionUgnot, maxMembers)` opens a circle.\n")
	sb.WriteString("2. `JoinCircle(id)` joins an open circle.\n")
	sb.WriteString("3. `StartCircle(id)` (creator only) starts round 1.\n")
	sb.WriteString("4. `Contribute(id)` with exactly the contribution attached pays into the current round.\n")
	sb.WriteString("5. When everyone has paid, the pot is sent to that round's recipient automatically.\n")
	return sb.String()
}

func renderCircle(c *Circle) string {
	var sb strings.Builder
	sb.WriteString("# " + c.name + "\n\n")
	sb.WriteString("- Status: **" + c.status + "**\n")
	sb.WriteString("- Creator: `" + c.creator.String() + "`\n")
	sb.WriteString("- Contribution: " + formatGNOT(c.contribution) + " (" + strconv.FormatInt(c.contribution, 10) + " ugnot) per member, per round\n")
	sb.WriteString("- Pot per round: " + formatGNOT(c.contribution*int64(len(c.members))) + "\n\n")

	sb.WriteString("## Members (in payout order)\n\n")
	for i, m := range c.members {
		line := strconv.Itoa(i+1) + ". `" + m.String() + "`"
		if c.status == statusActive {
			if c.paid[m] {
				line += " — paid this round ✅"
			} else {
				line += " — not yet paid this round"
			}
			if m == nextRecipient(c) {
				line += " — **receives this round's pot**"
			}
		}
		sb.WriteString(line + "\n")
	}

	if c.status == statusActive {
		sb.WriteString("\nRound " + strconv.Itoa(c.round+1) + " of " + strconv.Itoa(len(c.members)) + " is in progress.\n")
	}
	if len(c.payouts) > 0 {
		sb.WriteString("\n## Payout history\n\n")
		for i, p := range c.payouts {
			sb.WriteString("- Round " + strconv.Itoa(i+1) + ": `" + p.String() + "`\n")
		}
	}
	sb.WriteString("\n[← All circles](./)\n")
	return sb.String()
}

package arisan

import (
	"chain"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

var (
	alice   = testutils.TestAddress("alice")
	bob     = testutils.TestAddress("bob")
	charlie = testutils.TestAddress("charlie")
	dave    = testutils.TestAddress("dave")
)

// newStartedCircle creates a 3-member circle (alice, bob, charlie) with a
// 100000 ugnot contribution and starts it, using the internal
// implementations so no transaction envelope is involved.
func newStartedCircle(t *testing.T) *Circle {
	id := createCircle(alice, "Test Circle", 100_000, 3)
	joinCircle(bob, id)
	joinCircle(charlie, id)
	startCircle(alice, id)

	c := getCircle(id)
	uassert.Equal(t, statusActive, c.status)
	uassert.Equal(t, 3, len(c.members))
	return c
}

func TestCreateCircleValidation(cur realm, t *testing.T) {
	uassert.PanicsContains(t, cur, "arisan:", func() { createCircle(alice, "", 100_000, 3) })
	uassert.PanicsContains(t, cur, "arisan:", func() { createCircle(alice, "Bad [Name]", 100_000, 3) })
	uassert.PanicsContains(t, cur, "arisan:", func() { createCircle(alice, "x", 999, 3) })
	uassert.PanicsContains(t, cur, "arisan:", func() { createCircle(alice, "x", 100_000, 1) })
	uassert.PanicsContains(t, cur, "arisan:", func() { createCircle(alice, "x", 100_000, 13) })

	before := CircleCount()
	id := createCircle(alice, "Keluarga", 50_000, 4)
	uassert.Equal(t, before+1, CircleCount())

	c := getCircle(id)
	uassert.Equal(t, statusOpen, c.status)
	uassert.Equal(t, alice, c.creator)
	uassert.Equal(t, 1, len(c.members))
	uassert.Equal(t, int64(50_000), c.contribution)
}

func TestJoinAndStartGuards(cur realm, t *testing.T) {
	id := createCircle(alice, "Guards", 100_000, 2)

	// Creator is already a member.
	uassert.PanicsContains(t, cur, "arisan:", func() { joinCircle(alice, id) })
	// Non-creator cannot start.
	uassert.PanicsContains(t, cur, "arisan:", func() { startCircle(bob, id) })
	// Creator cannot start with a single member.
	uassert.PanicsContains(t, cur, "arisan:", func() { startCircle(alice, id) })

	joinCircle(bob, id)

	// Circle is full now.
	uassert.PanicsContains(t, cur, "arisan:", func() { joinCircle(charlie, id) })

	startCircle(alice, id)
	uassert.Equal(t, statusActive, getCircle(id).status)

	// Joining after start is closed.
	uassert.PanicsContains(t, cur, "arisan:", func() { joinCircle(charlie, id) })
}

func TestCancelCircle(cur realm, t *testing.T) {
	id := createCircle(alice, "Cancel Me", 100_000, 3)

	uassert.PanicsContains(t, cur, "arisan:", func() { cancelCircle(bob, id) })

	cancelCircle(alice, id)
	uassert.Equal(t, statusCancelled, getCircle(id).status)
}

func TestContributeGuards(cur realm, t *testing.T) {
	c := newStartedCircle(t)

	// Non-member cannot contribute.
	uassert.PanicsContains(t, cur, "arisan:", func() { contribute(cur, c, dave, 100_000) })
	// Wrong amount is rejected.
	uassert.PanicsContains(t, cur, "arisan:", func() { contribute(cur, c, alice, 99_999) })
	uassert.PanicsContains(t, cur, "arisan:", func() { contribute(cur, c, alice, 0) })

	// A valid contribution is recorded, and a second one is rejected.
	contribute(cur, c, alice, 100_000)
	uassert.True(t, c.paid[alice])
	uassert.PanicsContains(t, cur, "arisan:", func() { contribute(cur, c, alice, 100_000) })
}

func TestFullLifecycle(cur realm, t *testing.T) {
	c := newStartedCircle(t)
	members := []address{alice, bob, charlie}

	// The internal contribute() calls in this test move no real coins, so
	// pre-fund the realm's account with the total of all three pots
	// (3 rounds x 3 members x 100000 ugnot) for the payouts to draw on.
	realmAddr := chain.PackageAddress("gno.land/r/g1ulwmlzxtx922c7r8asp6ux23ks8rw6r8m2uftg/arisan")
	testing.IssueCoins(realmAddr, chain.Coins{{"ugnot", 900_000}})

	// Play all three rounds. Recipients must rotate in join order, and the
	// circle must finish exactly when everyone has received the pot once.
	for round := 0; round < 3; round++ {
		uassert.Equal(t, round, c.round)
		uassert.Equal(t, members[round], nextRecipient(c))
		for _, m := range members {
			contribute(cur, c, m, 100_000)
		}
		uassert.Equal(t, round+1, len(c.payouts))
		uassert.Equal(t, members[round], c.payouts[round])
	}
	uassert.Equal(t, statusFinished, c.status)

	// A finished circle takes no more contributions.
	uassert.PanicsContains(t, cur, "arisan:", func() { contribute(cur, c, alice, 100_000) })
}

func TestRender(cur realm, t *testing.T) {
	c := newStartedCircle(t)

	home := Render("")
	uassert.True(t, len(home) > 0)
	uassert.True(t, contains(home, "Test Circle"))

	page := Render("circle/" + itoa(c.id))
	uassert.True(t, contains(page, "Test Circle"))
	uassert.True(t, contains(page, "Round 1 of 3"))

	uassert.True(t, contains(Render("circle/99999"), "not found"))
	uassert.True(t, contains(Render("nonsense"), "not found"))
}

// TestCrossingEntryPoints exercises the real transaction-facing functions
// the way gnokey calls them, with the caller simulated by the test
// framework's user realms.
func TestCrossingEntryPoints(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(alice))
	id := CreateCircle(cross(cur), "Crossing", 100_000, 2)

	testing.SetRealm(testing.NewUserRealm(bob))
	JoinCircle(cross(cur), id)

	testing.SetRealm(testing.NewUserRealm(alice))
	StartCircle(cross(cur), id)

	uassert.Equal(t, statusActive, getCircle(id).status)
}

func contains(s, sub string) bool {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return true
		}
	}
	return false
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	digits := ""
	for n > 0 {
		digits = string(rune('0'+n%10)) + digits
		n /= 10
	}
	return digits
}

// Package komit implements Komit: stake-backed habit streaks on Gno.land.
//
// A user locks testnet GNOT (ugnot) as a stake, picks a habit and a target
// number of consecutive daily check-ins, and must call CheckIn once per UTC
// day. Miss a day and the streak breaks: the stake is forfeited into a shared
// reward pool. Reach the target and Claim returns the stake plus a bonus of
// min(reward pool balance, stake) -- up to 2x back.
//
// There is deliberately no owner/admin functionality: nobody can withdraw
// user stakes or the pool. Coins leave the realm only through Claim (to the
// challenge owner) -- forfeited stakes stay in the realm as the pool.
package komit

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"
)

const (
	DenomUgnot = "ugnot"

	MinStakeUgnot = int64(1_000_000)   // 1 GNOT
	MaxStakeUgnot = int64(100_000_000) // 100 GNOT

	MinTargetDays = 3
	MaxTargetDays = 90

	MaxHabitLen = 64

	StatusActive    = "ACTIVE"
	StatusCompleted = "COMPLETED"
	StatusFailed    = "FAILED"

	// PkgPath is this realm's own on-chain path, used in Render's
	// copy-paste commands.
	PkgPath = "gno.land/r/g10w0ycc9802gyja9w99xctx5s6vkgyc6fcj0f6u/komit"
)

// Challenge is one user's stake-backed habit streak.
type Challenge struct {
	Owner         address
	Habit         string
	TargetDays    int
	Stake         int64 // ugnot locked in the realm
	Streak        int   // consecutive daily check-ins so far
	StartDay      int64 // UTC day number (unix/86400) the challenge started
	LastCheckDay  int64 // UTC day number of the last check-in (StartDay-1 before the first)
	Status        string
	StartedHeight int64
}

var (
	activeByOwner  = make(map[address]*Challenge)
	finished       []*Challenge // completed and failed, oldest first
	poolBalance    int64        // ugnot forfeited into the shared reward pool, minus bonuses paid
	activeStaked   int64        // ugnot currently locked in active challenges
	totalStaked    int64        // ugnot staked all-time
	completedCount int
	failedCount    int
)

// today returns the current UTC day number, derived from the block time.
// In Gno, time.Now() returns the timestamp of the block the transaction is
// included in, so this is deterministic across validators.
func today() int64 {
	return time.Now().Unix() / 86400
}

// isStale reports whether the challenge's streak is broken at the given day:
// the last check-in day is older than yesterday.
func (c *Challenge) isStale(day int64) bool {
	return day > c.LastCheckDay+1
}

// breakChallenge closes an active challenge as failed and forfeits its stake
// into the shared reward pool. The coins stay at the realm address; only the
// accounting moves.
func breakChallenge(c *Challenge) {
	c.Status = StatusFailed
	poolBalance += c.Stake
	activeStaked -= c.Stake
	failedCount++
	delete(activeByOwner, c.Owner)
	finished = append(finished, c)

	chain.Emit(
		"ChallengeBroken",
		"owner", c.Owner.String(),
		"habit", c.Habit,
		"streak", strconv.Itoa(c.Streak),
		"forfeited_ugnot", strconv.FormatInt(c.Stake, 10),
	)
}

// startChallenge validates and records a new challenge for owner. Any stale
// previous challenge is broken first (lazy evaluation); a still-live previous
// challenge rejects the new one.
func startChallenge(owner address, habit string, targetDays int, stake int64, day int64) *Challenge {
	if prev, ok := activeByOwner[owner]; ok {
		if prev.isStale(day) {
			breakChallenge(prev)
		} else {
			panic("you already have an active challenge; finish it or let it break first")
		}
	}

	habit = strings.TrimSpace(habit)
	if habit == "" {
		panic("habit must not be empty")
	}
	if len(habit) > MaxHabitLen {
		panic("habit is too long (max 64 characters)")
	}
	if targetDays < MinTargetDays || targetDays > MaxTargetDays {
		panic("targetDays must be between 3 and 90")
	}
	if stake < MinStakeUgnot {
		panic("stake too small: send at least 1 GNOT (1000000ugnot) with the call")
	}
	if stake > MaxStakeUgnot {
		panic("stake too large: send at most 100 GNOT (100000000ugnot) with the call")
	}

	c := &Challenge{
		Owner:         owner,
		Habit:         habit,
		TargetDays:    targetDays,
		Stake:         stake,
		Streak:        0,
		StartDay:      day,
		LastCheckDay:  day - 1, // first check-in is due on the start day itself
		Status:        StatusActive,
		StartedHeight: runtime.ChainHeight(),
	}
	activeByOwner[owner] = c
	totalStaked += stake
	activeStaked += stake

	chain.Emit(
		"ChallengeStarted",
		"owner", owner.String(),
		"habit", habit,
		"target_days", strconv.Itoa(targetDays),
		"stake_ugnot", strconv.FormatInt(stake, 10),
	)
	return c
}

// checkInOn records a check-in for owner at the given UTC day. It returns the
// new streak, or (0, true) if the streak was broken by a missed day (the
// break is committed, not panicked, so the forfeit persists).
func checkInOn(owner address, day int64) (int, bool) {
	c, ok := activeByOwner[owner]
	if !ok {
		panic("no active challenge; start one first")
	}
	if c.isStale(day) {
		breakChallenge(c)
		return 0, true
	}
	if day == c.LastCheckDay {
		panic("already checked in today; come back tomorrow (UTC)")
	}
	// Here day == LastCheckDay+1: the consecutive day.
	c.Streak++
	c.LastCheckDay = day

	chain.Emit(
		"CheckedIn",
		"owner", owner.String(),
		"habit", c.Habit,
		"streak", strconv.Itoa(c.Streak),
		"target_days", strconv.Itoa(c.TargetDays),
	)
	return c.Streak, false
}

// claimOn settles owner's challenge at the given UTC day. If the streak is
// broken by then, the stake is forfeited and 0 is paid. If the target is
// reached, it pays stake + bonus where bonus = min(pool balance, stake),
// following Checks-Effects-Interactions: state is updated before the
// coin transfer.
func claimOn(cur realm, owner address, day int64) int64 {
	c, ok := activeByOwner[owner]
	if !ok {
		panic("no active challenge to claim")
	}
	if c.isStale(day) {
		breakChallenge(c)
		return 0
	}
	if c.Streak < c.TargetDays {
		panic("target not reached yet: streak " + strconv.Itoa(c.Streak) + " of " + strconv.Itoa(c.TargetDays))
	}

	bonus := poolBalance
	if bonus > c.Stake {
		bonus = c.Stake
	}
	payout := c.Stake + bonus

	// Effects before interactions.
	c.Status = StatusCompleted
	poolBalance -= bonus
	activeStaked -= c.Stake
	completedCount++
	delete(activeByOwner, owner)
	finished = append(finished, c)

	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), owner, chain.NewCoins(chain.NewCoin(DenomUgnot, payout)))

	chain.Emit(
		"ChallengeClaimed",
		"owner", owner.String(),
		"habit", c.Habit,
		"stake_ugnot", strconv.FormatInt(c.Stake, 10),
		"bonus_ugnot", strconv.FormatInt(bonus, 10),
		"payout_ugnot", strconv.FormatInt(payout, 10),
	)
	return payout
}

// StartChallenge starts a new habit challenge, locking the ugnot sent with
// the call as the caller's stake. Send between 1 and 100 GNOT
// (1000000 to 100000000 ugnot) with -send. Your first CheckIn is due the
// same UTC day.
func StartChallenge(cur realm, habit string, targetDays int) {
	if !cur.Previous().IsUser() {
		panic("StartChallenge must be called directly by a user account")
	}
	owner := cur.Previous().Address()
	stake := unsafe.OriginSend().AmountOf(DenomUgnot)
	startChallenge(owner, habit, targetDays, stake, today())
}

// CheckIn records today's check-in. It returns the new streak, or 0 if a
// missed day broke the streak and forfeited the stake to the reward pool.
func CheckIn(cur realm) int {
	if !cur.Previous().IsUser() {
		panic("CheckIn must be called directly by a user account")
	}
	streak, _ := checkInOn(cur.Previous().Address(), today())
	return streak
}

// Claim settles the caller's challenge. If the streak reached the target,
// it returns the payout in ugnot (stake + bonus of up to the stake again,
// drawn from the reward pool). If a missed day broke the streak, the stake
// is forfeited and 0 is returned. Claim by the day after your last
// check-in at the latest, or the challenge breaks like any other.
func Claim(cur realm) int64 {
	if !cur.Previous().IsUser() {
		panic("Claim must be called directly by a user account")
	}
	return claimOn(cur, cur.Previous().Address(), today())
}

// --- Read-only getters (used by Render and available via vm/qeval) ---

func ActiveChallenges() int { return len(activeByOwner) }

func PoolUgnot() int64 { return poolBalance }

func ActiveStakedUgnot() int64 { return activeStaked }

func TotalStakedUgnot() int64 { return totalStaked }

func CompletedCount() int { return completedCount }

func FailedCount() int { return failedCount }

// MyChallenge returns a one-line summary of the caller's active challenge,
// or an empty string if they have none. Note: as a read-only query it does
// not apply lazy break evaluation.
func MyChallenge(addr address) string {
	c, ok := activeByOwner[addr]
	if !ok {
		return ""
	}
	return c.Habit + ": streak " + strconv.Itoa(c.Streak) + "/" + strconv.Itoa(c.TargetDays) +
		", stake " + strconv.FormatInt(c.Stake, 10) + "ugnot, started day " + strconv.FormatInt(c.StartDay, 10)
}

package komit

import (
	"chain"
	"chain/banker"
	"strings"
	"testing"
)

var (
	userA = address("g1dmt3sa5ucvecxuhf3j6ne5r0e3z4x7h6c03xc0")
	userB = address("g1akeqsvhucjt8gf5yupyzjxsjd29wv8fayng37c")
)

func resetState() {
	activeByOwner = make(map[address]*Challenge)
	finished = nil
	poolBalance = 0
	activeStaked = 0
	totalStaked = 0
	completedCount = 0
	failedCount = 0
}

// NOTE on SetRealm placement: testing.SetRealm applies the realm override
// to the nearest non-testing caller frame, so it must be called directly in
// the same function that performs the cross(cur) call into the realm --
// wrapping it in another helper lands the override on the helper's frame
// and the public functions then see the realm itself as Previous().

// startViaPublicPath funds the realm exactly like a real payable call and
// then calls the public StartChallenge. On-chain, the bank module moves the
// sent coins into the realm address before the function runs, and the
// function reads them back through the origin-send envelope; a
// BankerTypeRealmSend banker cannot pull coins out of a user account, so
// the test issues the coins straight to the realm address (where the VM
// would have put them) and sets the envelope to match.
func startViaPublicPath(cur realm, user address, habit string, targetDays int, stakeUgnot int64) {
	coins := chain.NewCoins(chain.NewCoin(DenomUgnot, stakeUgnot))
	testing.IssueCoins(cur.Address(), coins)
	testing.SetOriginSend(coins)
	testing.SetRealm(testing.NewUserRealm(user))
	StartChallenge(cross(cur), habit, targetDays)
}

func assertPanics(t *testing.T, label string, fn func()) {
	t.Helper()
	if r := revive(fn); r == nil {
		t.Fatalf("expected panic for case %q, but succeeded", label)
	}
}

func TestStartCheckInClaimHappyPath(cur realm, t *testing.T) {
	resetState()
	ro := banker.NewReadonlyBanker()

	startViaPublicPath(cur, userA, "Meditate", 3, 5_000_000)

	c, ok := activeByOwner[userA]
	if !ok {
		t.Fatalf("expected an active challenge for userA")
	}
	if c.Streak != 0 || c.Stake != 5_000_000 || c.TargetDays != 3 {
		t.Fatalf("unexpected challenge state: streak %d stake %d target %d", c.Streak, c.Stake, c.TargetDays)
	}
	if ActiveStakedUgnot() != 5_000_000 || TotalStakedUgnot() != 5_000_000 {
		t.Fatalf("unexpected accounting: active %d total %d", ActiveStakedUgnot(), TotalStakedUgnot())
	}

	balBefore := ro.GetCoin(userA, DenomUgnot)

	// First check-in on the start day (public path).
	testing.SetRealm(testing.NewUserRealm(userA))
	if streak := CheckIn(cross(cur)); streak != 1 {
		t.Fatalf("expected streak 1 after first check-in, got %d", streak)
	}

	// Double check-in on the same day is rejected.
	assertPanics(t, "double check-in same day", func() {
		testing.SetRealm(testing.NewUserRealm(userA))
		CheckIn(cross(cur))
	})

	// Claiming before the target is rejected.
	assertPanics(t, "claim before target", func() {
		testing.SetRealm(testing.NewUserRealm(userA))
		Claim(cross(cur))
	})

	// Two more consecutive days via the day-parameterised path the public
	// functions wrap.
	day := today()
	if streak, broke := checkInOn(userA, day+1); broke || streak != 2 {
		t.Fatalf("expected streak 2, got %d (broke=%v)", streak, broke)
	}
	if streak, broke := checkInOn(userA, day+2); broke || streak != 3 {
		t.Fatalf("expected streak 3, got %d (broke=%v)", streak, broke)
	}

	// Claim: pool is empty, so payout is exactly the stake back.
	payout := claimOn(cross(cur), userA, day+2)
	if payout != 5_000_000 {
		t.Fatalf("expected payout 5000000, got %d", payout)
	}
	if got := ro.GetCoin(userA, DenomUgnot) - balBefore; got != 5_000_000 {
		t.Fatalf("expected userA balance +5000000 after claim, got %d", got)
	}
	if CompletedCount() != 1 || ActiveChallenges() != 0 || PoolUgnot() != 0 {
		t.Fatalf("unexpected final state: completed %d active %d pool %d",
			CompletedCount(), ActiveChallenges(), PoolUgnot())
	}
}

func TestSecondActiveChallengeRejected(cur realm, t *testing.T) {
	resetState()

	startViaPublicPath(cur, userA, "Stretch", 7, 2_000_000)

	assertPanics(t, "second active challenge", func() {
		startViaPublicPath(cur, userA, "Another habit", 7, 2_000_000)
	})

	if ActiveChallenges() != 1 {
		t.Fatalf("expected exactly 1 active challenge, got %d", ActiveChallenges())
	}
	if c := activeByOwner[userA]; c.Habit != "Stretch" || c.Stake != 2_000_000 {
		t.Fatalf("original challenge was modified: %+v", c)
	}
}

func TestInvalidStartsRejected(cur realm, t *testing.T) {
	resetState()

	// Zero stake: no coins sent with the call.
	testing.SetOriginSend(chain.NewCoins())
	assertPanics(t, "zero stake", func() {
		testing.SetRealm(testing.NewUserRealm(userA))
		StartChallenge(cross(cur), "Read", 7)
	})

	// Below the 1 GNOT minimum.
	assertPanics(t, "stake below minimum", func() {
		startViaPublicPath(cur, userA, "Read", 7, 500_000)
	})

	// Above the 100 GNOT maximum.
	assertPanics(t, "stake above maximum", func() {
		startViaPublicPath(cur, userA, "Read", 7, 100_000_001)
	})

	// Target below the 3-day minimum and above the 90-day maximum.
	assertPanics(t, "target too small", func() {
		startViaPublicPath(cur, userA, "Read", 2, 2_000_000)
	})
	assertPanics(t, "target too large", func() {
		startViaPublicPath(cur, userA, "Read", 91, 2_000_000)
	})

	// Empty habit.
	assertPanics(t, "empty habit", func() {
		startViaPublicPath(cur, userA, "   ", 7, 2_000_000)
	})

	if ActiveChallenges() != 0 || TotalStakedUgnot() != 0 {
		t.Fatalf("no challenge should have been recorded: active %d total %d",
			ActiveChallenges(), TotalStakedUgnot())
	}
}

func TestMissedDayBreaksAndForfeits(cur realm, t *testing.T) {
	resetState()
	ro := banker.NewReadonlyBanker()

	// userA starts at day 100, checks in, then misses day 101. The internal
	// start moves no coins, so back its stake at the realm address the way
	// a real payable call would have.
	startChallenge(userA, "Run", 5, 5_000_000, 100)
	testing.IssueCoins(cur.Address(), chain.NewCoins(chain.NewCoin(DenomUgnot, 5_000_000)))
	if streak, broke := checkInOn(userA, 100); broke || streak != 1 {
		t.Fatalf("expected streak 1, got %d (broke=%v)", streak, broke)
	}
	if streak, broke := checkInOn(userA, 102); !broke || streak != 0 {
		t.Fatalf("expected break at day 102, got streak %d broke=%v", streak, broke)
	}
	if ActiveChallenges() != 0 || FailedCount() != 1 {
		t.Fatalf("expected challenge closed as failed: active %d failed %d", ActiveChallenges(), FailedCount())
	}
	if PoolUgnot() != 5_000_000 {
		t.Fatalf("expected pool 5000000 after forfeit, got %d", PoolUgnot())
	}
	if ActiveStakedUgnot() != 0 {
		t.Fatalf("expected active staked 0, got %d", ActiveStakedUgnot())
	}

	// userB completes a 3-day challenge with a 2 GNOT stake and claims
	// stake + min(pool, stake) = 2 + 2 = 4 GNOT.
	startViaPublicPath(cur, userB, "Read", 3, 2_000_000)
	day := today()
	checkInOn(userB, day)
	checkInOn(userB, day+1)
	if streak, broke := checkInOn(userB, day+2); broke || streak != 3 {
		t.Fatalf("expected userB streak 3, got %d (broke=%v)", streak, broke)
	}
	balBefore := ro.GetCoin(userB, DenomUgnot)
	payout := claimOn(cross(cur), userB, day+2)
	if payout != 4_000_000 {
		t.Fatalf("expected payout 4000000 (stake + bonus), got %d", payout)
	}
	if got := ro.GetCoin(userB, DenomUgnot) - balBefore; got != 4_000_000 {
		t.Fatalf("expected userB balance +4000000, got %d", got)
	}
	if PoolUgnot() != 3_000_000 || CompletedCount() != 1 {
		t.Fatalf("expected pool 3000000 and 1 completion, got pool %d completed %d", PoolUgnot(), CompletedCount())
	}

	// A claim that arrives after a missed day forfeits instead of paying.
	startChallenge(userA, "Swim", 3, 1_000_000, 300)
	checkInOn(userA, 300)
	if payout := claimOn(cross(cur), userA, 302); payout != 0 {
		t.Fatalf("expected stale claim to pay 0, got %d", payout)
	}
	if FailedCount() != 2 || PoolUgnot() != 4_000_000 {
		t.Fatalf("expected failed 2 and pool 4000000, got failed %d pool %d", FailedCount(), PoolUgnot())
	}
}

func TestStartBreaksStalePrevious(cur realm, t *testing.T) {
	resetState()

	startChallenge(userA, "Code", 5, 1_000_000, 100)
	// Five days later with no check-ins: starting again breaks the stale
	// challenge (forfeiting its stake) and records the new one.
	c := startChallenge(userA, "Code daily", 5, 2_000_000, 105)

	if FailedCount() != 1 || PoolUgnot() != 1_000_000 {
		t.Fatalf("expected stale challenge forfeited: failed %d pool %d", FailedCount(), PoolUgnot())
	}
	if c.StartDay != 105 || c.Stake != 2_000_000 || ActiveChallenges() != 1 {
		t.Fatalf("unexpected new challenge: %+v", c)
	}
}

func TestRenderContainsKeyContent(cur realm, t *testing.T) {
	resetState()

	startChallenge(userA, "Meditate", 7, 5_000_000, today())
	out := Render("")

	for _, want := range []string{"Komit", "Leaderboard", "StartChallenge", "CheckIn", "Claim", "Meditate", "onyx-1", "Reward pool"} {
