package komit

import (
	"strconv"
	"strings"
)

// fmtGNOT renders a ugnot amount as a GNOT string, e.g. 5500000 -> "5.5 GNOT".
func fmtGNOT(ugnot int64) string {
	whole := ugnot / 1_000_000
	frac := ugnot % 1_000_000
	if frac == 0 {
		return strconv.FormatInt(whole, 10) + " GNOT"
	}
	fracStr := strconv.FormatInt(frac+1_000_000, 10)[1:] // zero-padded 6 digits
	fracStr = strings.TrimRight(fracStr, "0")
	return strconv.FormatInt(whole, 10) + "." + fracStr + " GNOT"
}

// sortedActive returns the active challenges ordered by streak (desc),
// then by stake (desc). Insertion sort; the set is small.
func sortedActive() []*Challenge {
	list := make([]*Challenge, 0, len(activeByOwner))
	for _, c := range activeByOwner {
		list = append(list, c)
	}
	for i := 1; i < len(list); i++ {
		for j := i; j > 0; j-- {
			a, b := list[j-1], list[j]
			if b.Streak > a.Streak || (b.Streak == a.Streak && b.Stake > a.Stake) {
				list[j-1], list[j] = b, a
			} else {
				break
			}
		}
	}
	return list
}

// Render is the realm's public gnoweb page.
func Render(path string) string {
	var sb strings.Builder

	sb.WriteString("# Komit — stake-backed habit streaks\n\n")
	sb.WriteString("Put testnet GNOT where your mouth is. Lock a stake, pick a habit, and check in **every UTC day**. ")
	sb.WriteString("Miss a day and your stake is forfeited into a shared reward pool. Finish your streak and you claim your stake back **plus a bonus of up to the same amount again**, paid from the pool.\n\n")
	sb.WriteString("No admin can touch the stakes or the pool — coins leave this realm only through `Claim`, only to the challenge owner.\n\n")

	sb.WriteString("## Live stats\n\n")
	sb.WriteString("| | |\n|---|---|\n")
	sb.WriteString("| Active challenges | " + strconv.Itoa(len(activeByOwner)) + " |\n")
	sb.WriteString("| Currently staked | " + fmtGNOT(activeStaked) + " |\n")
	sb.WriteString("| Reward pool | " + fmtGNOT(poolBalance) + " |\n")
	sb.WriteString("| Completed challenges | " + strconv.Itoa(completedCount) + " |\n")
	sb.WriteString("| Broken challenges | " + strconv.Itoa(failedCount) + " |\n")
	sb.WriteString("| Staked all-time | " + fmtGNOT(totalStaked) + " |\n\n")

	sb.WriteString("## Leaderboard — current streaks\n\n")
	list := sortedActive()
	if len(list) == 0 {
		sb.WriteString("No active challenges yet. Be the first.\n\n")
	} else {
		sb.WriteString("| # | Address | Habit | Streak | Stake |\n|---|---|---|---|---|\n")
		limit := len(list)
		if limit > 20 {
			limit = 20
		}
		for i := 0; i < limit; i++ {
			c := list[i]
			sb.WriteString("| " + strconv.Itoa(i+1) + " | `" + c.Owner.String() + "` | " +
				c.Habit + " | " + strconv.Itoa(c.Streak) + "/" + strconv.Itoa(c.TargetDays) +
				" | " + fmtGNOT(c.Stake) + " |\n")
		}
		sb.WriteString("\n")
	}

	if len(finished) > 0 {
		sb.WriteString("## Recent results\n\n")
		sb.WriteString("| Address | Habit | Result | Final streak |\n|---|---|---|---|\n")
		from := len(finished) - 10
		if from < 0 {
			from = 0
		}
		for i := len(finished) - 1; i >= from; i-- {
			c := finished[i]
			result := "✅ completed"
			if c.Status == StatusFailed {
				result = "💔 broken"
			}
			sb.WriteString("| `" + c.Owner.String() + "` | " + c.Habit + " | " + result +
				" | " + strconv.Itoa(c.Streak) + "/" + strconv.Itoa(c.TargetDays) + " |\n")
		}
		sb.WriteString("\n")
	}

	sb.WriteString("## How it works\n\n")
	sb.WriteString("1. **Start** a challenge: choose a habit and a target of 3–90 consecutive days, and send a stake of 1–100 GNOT with the call. The realm locks it.\n")
	sb.WriteString("2. **Check in** once per UTC day — your first check-in is due the *same* UTC day you start. Each check-in extends your streak by one.\n")
	sb.WriteString("3. **Don't miss a day.** Breaks are evaluated lazily: the next time any state-changing function runs after a missed day, the challenge closes as failed and the stake moves into the reward pool.\n")
	sb.WriteString("4. **Claim** once your streak reaches the target — by the day after your last check-in at the latest. You receive your stake back plus a bonus of `min(reward pool, your stake)`, so up to 2x back while the pool lasts.\n")
	sb.WriteString("5. One active challenge per address. Starting a new one first breaks a stale old one (forfeiting its stake); a live one blocks the new start.\n\n")

	sb.WriteString("## Play from the command line\n\n")
	sb.WriteString("You need a key (`gnokey add mykey`), testnet GNOT from [faucet.gno.land](https://faucet.gno.land) (pick the Onyx testnet), and the commands below. Replace `mykey` with your key name.\n\n")

	sb.WriteString("Start a 7-day challenge with a 5 GNOT stake:\n\n")
	sb.WriteString("```\n")
	sb.WriteString("gnokey maketx call \\\n")
	sb.WriteString("  -pkgpath \"" + PkgPath + "\" \\\n")
	sb.WriteString("  -func \"StartChallenge\" -args \"Read 20 pages\" -args 7 \\\n")
	sb.WriteString("  -send 5000000ugnot \\\n")
	sb.WriteString("  -gas-fee 200000ugnot -gas-wanted 20000000 \\\n")
	sb.WriteString("  -chainid onyx-1 -remote https://rpc.onyx.testnets.gno.land:443 \\\n")
	sb.WriteString("  mykey\n```\n\n")

	sb.WriteString("Check in (once per UTC day):\n\n")
	sb.WriteString("```\n")
	sb.WriteString("gnokey maketx call \\\n")
	sb.WriteString("  -pkgpath \"" + PkgPath + "\" \\\n")
	sb.WriteString("  -func \"CheckIn\" \\\n")
	sb.WriteString("  -gas-fee 200000ugnot -gas-wanted 20000000 \\\n")
	sb.WriteString("  -chainid onyx-1 -remote https://rpc.onyx.testnets.gno.land:443 \\\n")
	sb.WriteString("  mykey\n```\n\n")

	sb.WriteString("Claim after reaching your target:\n\n")
	sb.WriteString("```\n")
	sb.WriteString("gnokey maketx call \\\n")
	sb.WriteString("  -pkgpath \"" + PkgPath + "\" \\\n")
	sb.WriteString("  -func \"Claim\" \\\n")
	sb.WriteString("  -gas-fee 200000ugnot -gas-wanted 20000000 \\\n")
	sb.WriteString("  -chainid onyx-1 -remote https://rpc.onyx.testnets.gno.land:443 \\\n")
	sb.WriteString("  mykey\n```\n\n")

	sb.WriteString("---\n\nKomit runs on the Gno.land Onyx testnet (`onyx-1`). Stakes are testnet tokens with no monetary value.\n")
	return sb.String()
}

// Package taverncrown is a king-of-the-hill game realm for gno.land.
//
// Anyone can seize the Crown by paying the current price in ugnot into
// the pot. Every seizure raises the price by 10% and resets the round
// timer. When the timer expires, the last Crown holder wins the whole
// pot. Payout uses the pull-payment pattern: after the deadline anyone
// can call ClaimPot to settle the round and pay the winner.
//
// The realm is immutable and has no admin keys: the rules below are the
// whole game. State is intentionally small (holder, pot, price,
// deadline, and a capped winners list) to keep storage deposits low.
package taverncrown

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
)

const (
	denom       = "ugnot"
	basePrice   = int64(1_000_000) // 1 GNOT, the price of the first seizure each round
	priceNum    = int64(11)        // price grows by x11/10 per seizure (+10%)
	priceDen    = int64(10)
	roundBlocks = int64(720) // round length in blocks (~1 hour at ~5s blocks)
	maxWinners  = 20         // hall-of-fame cap, bounds storage growth
)

// winner records one settled round.
type winner struct {
	addr   address
	amount int64
	round  int
}

var (
	holder   address // current Crown holder; zero when no round is active
	pot      int64   // ugnot accumulated this round
	price    int64   // current price to seize the Crown, in ugnot
	deadline int64   // block height at which the round expires
	round    int     // current round number, starting at 1
	seizures int     // seizures so far this round
	winners  []winner
)

func init() {
	price = basePrice
	round = 1
}

// SeizeCrown takes the Crown for the caller.
//
// The caller must attach at least the current price in ugnot to the
// call (-send). Any excess over the price is refunded immediately. On a
// successful seizure the caller becomes the Crown holder, the price
// rises by 10%, and the round timer resets.
//
// If the previous round already expired, it is settled first (the old
// holder is paid) and the seizure opens a fresh round at the base price.
//
// Only direct user calls (maketx call) are accepted: the payment check
// relies on the origin-send envelope, which only describes a real
// receipt at this realm when the caller is a plain account.
func SeizeCrown(cur realm) {
	if !cur.Previous().IsUserCall() {
		panic("only user-call (maketx call) accepted")
	}
	sender := cur.Previous().Address()

	// Settle an expired round before pricing the new seizure.
	if holder != "" && runtime.ChainHeight() >= deadline {
		settle(cur)
	}

	sent := unsafe.OriginSend().AmountOf(denom)
	if sent < price {
		panic("payment below current crown price")
	}

	// Refund any excess over the price.
	if sent > price {
		pay(cur, sender, sent-price)
	}

	pot += price
	holder = sender
	seizures++
	price = price * priceNum / priceDen
	deadline = runtime.ChainHeight() + roundBlocks

	chain.Emit("CrownSeized",
		"holder", string(sender),
		"round", strconv.Itoa(round),
		"paid", strconv.FormatInt(pot, 10),
		"nextPrice", strconv.FormatInt(price, 10),
		"deadline", strconv.FormatInt(deadline, 10),
	)
}

// ClaimPot settles the current round once its deadline has passed,
// paying the whole pot to the Crown holder. Anyone may call it; the
// payout always goes to the holder of record, never to the caller.
func ClaimPot(cur realm) {
	if holder == "" {
		panic("no active round")
	}
	if runtime.ChainHeight() < deadline {
		panic("round not finished yet")
	}
	settle(cur)
}

// settle pays the pot to the current holder, records the winner, and
// resets the round. State is reset before the payout so the realm is
// consistent even if the transfer were to fail partway (it cannot:
// the pot is fully backed by received coins).
func settle(cur realm) {
	w := holder
	amount := pot
	wonRound := round

	winners = append(winners, winner{addr: w, amount: amount, round: wonRound})
	if len(winners) > maxWinners {
		winners = winners[len(winners)-maxWinners:]
	}

	holder = ""
	pot = 0
	price = basePrice
	seizures = 0
	deadline = 0
	round++

	chain.Emit("PotClaimed",
		"winner", string(w),
		"round", strconv.Itoa(wonRound),
		"amount", strconv.FormatInt(amount, 10),
	)

	if amount > 0 {
		pay(cur, w, amount)
	}
}

// pay sends amount ugnot from the realm to the given address.
func pay(cur realm, to address, amount int64) {
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), to, chain.NewCoins(chain.NewCoin(denom, amount)))
}

// GetHolder returns the current Crown holder (zero address if no round).
func GetHolder() address { return holder }

// GetPot returns the current pot in ugnot.
func GetPot() int64 { return pot }

// GetPrice returns the current seizure price in ugnot.
func GetPrice() int64 { return price }

// GetDeadline returns the block height at which the round expires.
func GetDeadline() int64 { return deadline }

// GetRound returns the current round number.
func GetRound() int { return round }

// GetSeizures returns the number of seizures this round.
func GetSeizures() int { return seizures }

// formatGNOT renders an ugnot amount as a GNOT decimal string.
func formatGNOT(ugnot int64) string {
	whole := ugnot / 1_000_000
	frac := ugnot % 1_000_000
	if frac == 0 {
		return strconv.FormatInt(whole, 10)
	}
	fracStr := strconv.FormatInt(frac+1_000_000, 10)[1:] // zero-padded to 6 digits
	fracStr = strings.TrimRight(fracStr, "0")
	return strconv.FormatInt(whole, 10) + "." + fracStr
}

// Render renders the game page in markdown.
//
// Paths: "" (home), "winners" (hall of fame), "rules" (how to play).
// The path is never echoed back, so no user input reaches the output.
func Render(path string) string {
	switch path {
	case "":
		return renderHome()
	case "winners":
		return renderWinners()
	case "rules":
		return renderRules()
	default:
		return "# Tavern Crown\n\nUnknown page. Try the home page, `winners`, or `rules`.\n"
	}
}

func renderHome() string {
	var b strings.Builder
	b.WriteString("# 👑 Tavern Crown\n\n")
	b.WriteString("King of the hill, on-chain. Seize the Crown, hold it until the timer runs out, take the pot.\n\n")

	if holder == "" {
		b.WriteString("## No reigning monarch\n\n")
		b.WriteString("The Crown sits unclaimed. Round " + strconv.Itoa(round) + " is open — ")
		b.WriteString("seize it for **" + formatGNOT(price) + " GNOT** and start the clock.\n\n")
	} else {
		remaining := deadline - runtime.ChainHeight()
		if remaining < 0 {
			remaining = 0
		}
		b.WriteString("## Current reign\n\n")
		b.WriteString("- **Crown holder:** `" + string(holder) + "`\n")
		b.WriteString("- **Pot:** " + formatGNOT(pot) + " GNOT\n")
		b.WriteString("- **Price to seize:** " + formatGNOT(price) + " GNOT\n")
		b.WriteString("- **Blocks remaining:** " + strconv.FormatInt(remaining, 10) + "\n")
		b.WriteString("- **Round:** " + strconv.Itoa(round) + " (" + strconv.Itoa(seizures) + " seizures)\n\n")
		if remaining == 0 {
			b.WriteString("⏰ The round has expired — call **ClaimPot** to pay the holder and open the next round.\n\n")
		}
	}

	b.WriteString("## How to play\n\n")
	b.WriteString("1. Call **SeizeCrown** with the current price attached (`-send`). Excess is refunded.\n")
	b.WriteString("2. Each seizure raises the price 10% and resets the timer (" + strconv.FormatInt(roundBlocks, 10) + " blocks).\n")
	b.WriteString("3. When the timer expires, the last holder wins the pot — anyone can trigger **ClaimPot**.\n\n")
	b.WriteString("See `rules` for the full rules and `winners` for past champions.\n")
	return b.String()
}

func renderWinners() string {
	var b strings.Builder
	b.WriteString("# 🏆 Hall of Fame\n\n")
	if len(winners) == 0 {
		b.WriteString("No champions yet. The first Crown is still waiting.\n")
		return b.String()
	}
	b.WriteString("| Round | Winner | Pot (GNOT) |\n|---|---|---|\n")
	for i := len(winners) - 1; i >= 0; i-- {
		w := winners[i]
		b.WriteString("| " + strconv.Itoa(w.round) + " | `" + string(w.addr) + "` | " + formatGNOT(w.amount) + " |\n")
	}
	return b.String()
}

func renderRules() string {
	var b strings.Builder
	b.WriteString("# 📜 Tavern Crown — Rules\n\n")
	b.WriteString("- **Seize:** call `SeizeCrown` with at least the current price in ugnot attached. Overpayment is refunded in the same transaction.\n")
	b.WriteString("- **Price curve:** the first seizure of a round costs " + formatGNOT(basePrice) + " GNOT; every seizure multiplies the price by 11/10 (+10%).\n")
	b.WriteString("- **Timer:** each seizure sets the deadline " + strconv.FormatInt(roundBlocks, 10) + " blocks ahead. Seize again before it expires to extend your reign — anyone else can take the Crown from you the same way.\n")
	b.WriteString("- **Winning:** when the deadline passes, the holder of record wins the entire pot. `ClaimPot` (callable by anyone) settles the round; a seizure after expiry also settles the old round first.\n")
	b.WriteString("- **Fair play:** no admin keys, no pause, no upgrades. The realm code is the rulebook. Payments are verified from the transaction envelope; only direct account calls can seize.\n")
	return b.String()
}

package taverncrown

import (
	"chain"
	"chain/banker"
	"strings"
	"testing"
)

const testPkgPath = "gno.land/r/g1frp3vfzvw5ft00aes9q5h957sf00lls8wpd3wn/taverncrown"

var (
	alice = chain.PackageAddress("gno.land/r/test/alice")
	bob   = chain.PackageAddress("gno.land/r/test/bob")
	carol = chain.PackageAddress("gno.land/r/test/carol")
)

func resetState() {
	holder = ""
	pot = 0
	price = basePrice
	deadline = 0
	round = 1
	seizures = 0
	winners = nil
	testing.SetHeight(1000)
	// Fund the realm so refunds/payouts have balance in the harness
	// (SetOriginSend only sets the envelope metadata in tests).
	testing.IssueCoins(chain.PackageAddress(testPkgPath), chain.Coins{{"ugnot", 1_000_000_000}})
}

func seizeAs(cur realm, who address, amount int64) {
	testing.SetRealm(testing.NewUserRealm(who))
	testing.SetOriginSend(chain.Coins{{"ugnot", amount}})
	SeizeCrown(cross(cur))
}

func balanceOf(addr address) int64 {
	return banker.NewReadonlyBanker().GetCoin(addr, denom)
}

func mustEqual(t *testing.T, want, got any, what string) {
	t.Helper()
	if want != got {
		t.Fatalf("%s: want %v, got %v", what, want, got)
	}
}

func mustTrue(t *testing.T, cond bool, what string) {
	t.Helper()
	if !cond {
		t.Fatalf("expected true: %s", what)
	}
}

func mustAbort(t *testing.T, wantMsg string, f func()) {
	t.Helper()
	r := revive(f)
	if r == nil {
		t.Fatalf("expected abort %q, but call succeeded", wantMsg)
	}
	if s, ok := r.(string); !ok || s != wantMsg {
		t.Fatalf("expected abort %q, got %v", wantMsg, r)
	}
}

func TestSeizeCrown_Basic(cur realm, t *testing.T) {
	resetState()

	seizeAs(cur, alice, basePrice)

	mustEqual(t, alice, holder, "holder")
	mustEqual(t, basePrice, pot, "pot")
	mustEqual(t, basePrice*priceNum/priceDen, price, "next price")
	mustEqual(t, int64(1000)+roundBlocks, deadline, "deadline")
	mustEqual(t, 1, seizures, "seizures")
	mustEqual(t, 1, round, "round")
}

func TestSeizeCrown_UnderpayReverts(cur realm, t *testing.T) {
	resetState()

	testing.SetRealm(testing.NewUserRealm(alice))
	testing.SetOriginSend(chain.Coins{{"ugnot", basePrice - 1}})
	mustAbort(t, "payment below current crown price", func() {
		SeizeCrown(cross(cur))
	})
	mustEqual(t, address(""), holder, "holder unchanged")
	mustEqual(t, int64(0), pot, "pot unchanged")
}

func TestSeizeCrown_ExcessRefunded(cur realm, t *testing.T) {
	resetState()
	excess := int64(500_000)

	seizeAs(cur, alice, basePrice+excess)

	mustEqual(t, basePrice, pot, "only the price enters the pot")
	mustEqual(t, excess, balanceOf(alice), "excess refunded to sender")
}

func TestSeizeCrown_PriceCurveAndTakeover(cur realm, t *testing.T) {
	resetState()

	seizeAs(cur, alice, basePrice)
	p2 := price
	seizeAs(cur, bob, p2)

	mustEqual(t, bob, holder, "holder")
	mustEqual(t, basePrice+p2, pot, "pot")
	mustEqual(t, p2*priceNum/priceDen, price, "next price")
	mustEqual(t, 2, seizures, "seizures")
	mustEqual(t, int64(1000)+roundBlocks, deadline, "deadline resets on seizure")
}

func TestClaimPot_BeforeDeadlineReverts(cur realm, t *testing.T) {
	resetState()
	seizeAs(cur, alice, basePrice)

	testing.SetRealm(testing.NewUserRealm(alice))
	mustAbort(t, "round not finished yet", func() {
		ClaimPot(cross(cur))
	})
	mustEqual(t, alice, holder, "holder unchanged")
}

func TestClaimPot_NoRoundReverts(cur realm, t *testing.T) {
	resetState()

	testing.SetRealm(testing.NewUserRealm(alice))
	mustAbort(t, "no active round", func() {
		ClaimPot(cross(cur))
	})
}

func TestClaimPot_PaysHolderAndResets(cur realm, t *testing.T) {
	resetState()

	seizeAs(cur, alice, basePrice)
	p2 := price
	seizeAs(cur, bob, p2)
	totalPot := pot

	// Advance past the deadline; a third party triggers the payout.
	testing.SkipHeights(roundBlocks)
	testing.SetRealm(testing.NewUserRealm(carol))
	ClaimPot(cross(cur))

	mustEqual(t, totalPot, balanceOf(bob), "pot goes to the holder, not the caller")
	mustEqual(t, int64(0), balanceOf(carol), "caller gets nothing")
	mustEqual(t, address(""), holder, "holder reset")
	mustEqual(t, int64(0), pot, "pot reset")
	mustEqual(t, basePrice, price, "price reset")
	mustEqual(t, 0, seizures, "seizures reset")
	mustEqual(t, 2, round, "round increments")
	mustEqual(t, 1, len(winners), "one winner recorded")
	mustEqual(t, bob, winners[0].addr, "winner addr")
	mustEqual(t, totalPot, winners[0].amount, "winner amount")
	mustEqual(t, 1, winners[0].round, "winner round")

	// Double claim reverts: the round is gone.
	mustAbort(t, "no active round", func() {
		ClaimPot(cross(cur))
	})
}

func TestSeizeCrown_AfterExpirySettlesFirst(cur realm, t *testing.T) {
	resetState()

	seizeAs(cur, alice, basePrice)
	testing.SkipHeights(roundBlocks + 5)

	// Bob seizes after expiry: Alice must be paid the old pot first,
	// and Bob's seizure opens round 2 at the base price.
	seizeAs(cur, bob, basePrice)

	mustEqual(t, basePrice, balanceOf(alice), "expired round pays its holder")
	mustEqual(t, bob, holder, "new holder")
	mustEqual(t, basePrice, pot, "new round pot holds only the new payment")
	mustEqual(t, 2, round, "round 2")
	mustEqual(t, 1, len(winners), "one winner recorded")
	mustEqual(t, alice, winners[0].addr, "winner is alice")
}

func TestSeizeCrown_SameHolderExtends(cur realm, t *testing.T) {
	resetState()

	seizeAs(cur, alice, basePrice)
	testing.SkipHeights(100)
	seizeAs(cur, alice, price)

	mustEqual(t, alice, holder, "holder")
	mustEqual(t, 2, seizures, "seizures")
	mustEqual(t, int64(1000)+100+roundBlocks, deadline, "timer resets from latest seizure")
}

func TestRender(cur realm, t *testing.T) {
	resetState()

	home := Render("")
	mustTrue(t, strings.Contains(home, "No reigning monarch"), "empty home page")

	seizeAs(cur, alice, basePrice)
	home = Render("")
	mustTrue(t, strings.Contains(home, string(alice)), "home shows holder")
	mustTrue(t, strings.Contains(home, "Pot:** 1 GNOT"), "home shows pot")

	mustTrue(t, strings.Contains(Render("rules"), "Price curve"), "rules page")
	mustTrue(t, strings.Contains(Render("winners"), "No champions yet"), "empty winners page")

	// Unknown paths never echo user input.
	out := Render("<script>alert(1)</script>")
	mustTrue(t, !strings.Contains(out, "<script>"), "path not echoed")

	// After a settled round, the hall of fame lists the winner.
	testing.SkipHeights(roundBlocks)
	testing.SetRealm(testing.NewUserRealm(alice))
	ClaimPot(cross(cur))
	w := Render("winners")
	mustTrue(t, strings.Contains(w, string(alice)), "winners lists alice")
	mustTrue(t, strings.Contains(w, "| 1 |"), "winners lists round 1")
}

func TestFormatGNOT(t *testing.T) {
	mustEqual(t, "0", formatGNOT(0), "zero")
	mustEqual(t, "1", formatGNOT(1_000_000), "one")
	mustEqual(t, "1.1", formatGNOT(1_100_000), "one point one")
	mustEqual(t, "0.000001", formatGNOT(1), "one ugnot")
	mustEqual(t, "2.5", formatGNOT(2_500_000), "two point five")
	mustEqual(t, "10.05", formatGNOT(10_050_000), "ten point zero five")
}

package evolution

// 첫 번째 설계도: 펄서 창 + 프리즘 렌즈
func CanEvolve(weapon string, weaponLevel int, accessory string, accessoryLevel int) bool {
	return weapon == "pulsar_lance" &&
		weaponLevel == 10 &&
		accessory == "prism_lens" &&
		accessoryLevel == 8
}

func result(weaponLevel int, accessoryLevel int) string {
	if CanEvolve("pulsar_lance", weaponLevel, "prism_lens", accessoryLevel) {
		return "READY: Quasar Trident"
	}
	return "LOCKED"
}

func Render(path string) string {
	return "# GNOME SURVIVAL - Evolution Lab\n\n" +
		"* Pulsar Lance Lv10 + Prism Lens Lv7: " + result(10, 7) + "\n" +
		"* Pulsar Lance Lv10 + Prism Lens Lv8: " + result(10, 8) + "\n"
}

package evolution

import "testing"

func TestPulsarEvolution(t *testing.T) {
	if !CanEvolve("pulsar_lance", 10, "prism_lens", 8) {
		t.Fatal("matching equipment at max level should evolve")
	}
	if CanEvolve("pulsar_lance", 9, "prism_lens", 8) {
		t.Fatal("weapon level 9 should not evolve")
	}
	if CanEvolve("pulsar_lance", 10, "prism_lens", 7) {
		t.Fatal("accessory level 7 should not evolve")
	}
	if CanEvolve("pulsar_lance", 10, "wrong_accessory", 8) {
		t.Fatal("wrong accessory should not evolve")
	}
	if CanEvolve("wrong_weapon", 10, "prism_lens", 8) {
		t.Fatal("wrong weapon should not evolve")
	}
}

